/* ÇEVİRİ nl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("nl","olay",{
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Bezetting van Bosnië-Herzegovina en Novi Pazar door Oostenrijk-Hongarije", "e5f901df"], "d": ["Steunend op de bevoegdheid die het Verdrag van Berlijn gaf, trokken de legers van Oostenrijk-Hongarije Bosnië binnen; hoewel de Osmaanse regering instemde met niet-verzet, grepen de lokale moslimse en orthodoxe bevolking in Sarajevo en Mostar naar de wapens en boden drie maanden lang hevig weerstand. De bezetting kon pas op 20 oktober 1878 worden voltooid. De juridische soevereiniteit van de sultan duurde op papier tot 1908, maar het vierhonderd jaar oude Osmaanse Bosnië ging feitelijk verloren en een grote golf van moslimmigratie begon. Andere plaatsen die op dezelfde datum verloren gingen: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Muharrem-decreet en stichting van de Düyûn-ı Umûmiyye-administratie", "02b7cc03"], "d": ["De onderhandelingen die na het faillissement van 1875 met de vertegenwoordigers van de schuldeisende staten werden gevoerd, mondden uit in het decreet van 28 Muharrem 1299 (20 december 1881): de hoofdsom van de schuld werd met meer dan de helft verlaagd, daartegenover werden de meest productieve inkomstenposten zoals zout, tabak, zijde, zegel- en visrechten overgedragen aan de Düyûn-ı Umûmiyye-administratie, die rechtstreeks door de schuldeisers werd beheerd. Deze administratie, die duizenden ambtenaren in dienst had, veranderde in een afzonderlijke financiële organisatie binnen de staat. Zij wordt beschouwd als de datum waarop de Osmaanse financiële onafhankelijkheid feitelijk eindigde.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — de enige haven die niet aan de Mahdi viel", "5a37b198"], "d": ["Terwijl vanaf februari 1884 alle gebieden van Oost-Soedan behalve Suakin onder de heerschappij van Muhammad Ahmad al-Mahdi kwamen, bleef de haven overeind onder de militaire bescherming van een Brits detachement van drie bataljons onder bevel van generaal Graham. Dit was het begin van een periode waarin feitelijke en juridische situatie uiteenliepen: hoewel de kust feitelijk onder Britse militaire controle stond, zou de administratieve band in 1885 aan Egypte worden ontnomen en rechtstreeks aan de provincie Jemen, dus aan de Hoge Porte, worden gebonden — die orde duurde tot 1888, toen Frankrijk Zeila bezette.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Moord op Midhat Pasja in de gevangenis van Ta'if", "f4562261"], "d": ["Midhat Pasja, de architect van de Kanûn-ı Esâsî en het symbool van de Eerste Constitutionele Periode, was in het Yıldız-proces over de dood van Abdülaziz schuldig bevonden en kreeg een doodstraf die in ballingschap werd omgezet; hij werd naar Ta'if gezonden. Volgens de TDV-aantekening werd hij in de nacht van 7-8 mei 1884 in zijn cel gewurgd, als officiële reden werd de ziekte 'şîrpençe' opgegeven. Zijn dood werd onder Abdülhamid II het symbool van de liquidatie van de constitutionele oppositie.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Concessie voor de spoorlijn Haydarpaşa–Ankara aan de Duitsers", "5705b163"], "d": ["Met sultansirade werd de concessie voor bouw en exploitatie van de lijn Haydarpaşa–Ankara verleend aan de bankier Alfred von Kaulla, die de Deutsche Bank vertegenwoordigde, en de Anatolische Spoorwegmaatschappij werd opgericht. Deze concessie werd het keerpunt dat in het Osmaanse vervoer en buitenlands beleid het Engels-Franse monopolie brak en de Duitse invloed vestigde. Samen met de concessie voor de Bagdadlijn die elf jaar later aan dezelfde maatschappij zou worden verleend, ontstond de droom van 'Berlijn–Bagdad', die een van de hoofdassen van de grote-machtenrivaliteit voor de Eerste Wereldoorlog zou worden.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Stichting van het Ittihad-ı Osmani Genootschap in Constantinopel", "b7187939"], "d": ["Vier studenten van de Militaire Geneeskundeschool richtten het Ittihad-ı Osmani Genootschap op als geheime organisatie tegen het despotische bestuur; deze structuur veranderde snel in het Comité voor Eenheid en Vooruitgang, dat alle oppositionele elementen van de Jongturkse beweging onder zijn dak zou verzamelen. De organisatie op basis van cellen verenigde zich met de ballingen in Europa en de officieren in Thessaloniki. Het kader dat in 1908 de Tweede Constitutionele Periode zou afdwingen en na 1913 de staat alleen zou besturen, kwam voort uit deze kleine studentencel.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Overval op de Osmaanse Bank: actie van Dasjnak-activisten in Galata", "08b3095f"], "d": ["Een gewapende groep van de Armeense organisatie Dasjnaktsoetjoen overviel het hoofdkantoor van de Osmaanse Bank in Galata, nam gijzelaars en dreigde het gebouw op te blazen, met als doel de aandacht van Europa op de Armeense kwestie te vestigen. De crisis eindigde door tussenkomst van de ambassadeurs, in ruil voor het per schip uit het land brengen van de activisten. De bloedige gebeurtenissen in Constantinopel in de dagen na de overval waren bepalend voor de verandering van de Armeense kwestie in een hefboom voor internationale interventie.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Begin van de Osmaans-Griekse oorlog van 1897: front van Thessalië", "33e490ab"], "d": ["Na de landing van Griekenland met vloot en soldaten op Kreta en de bendeaanvallen aan de grens met Rumelië verklaarde de Osmaanse staat de oorlog. Het Osmaanse leger, getraind door de Duitse hervormingsmissie, rukte in Thessalië snel op en nam binnen een maand Yenişehir (Larissa), Çatalca en Domokos in; het Griekse leger viel uiteen. Door tussenkomst van de grote mogendheden werden de veroverde gebieden teruggegeven, maar de oorlog bleef de enige beslissende militaire overwinning uit de tijd van Abdülhamid II en kon het feitelijke verlies van Kreta niet verhinderen.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Concessie voor de lijn Konya–Bagdad aan de Duitsers", "fd8b6cbd"], "d": ["Na het bezoek van keizer Wilhelm II aan Constantinopel en Damascus in 1898 werd aan de Anatolische Spoorwegmaatschappij de voorconcessie verleend voor een lijn van Konya naar Bagdad en Basra. Het Bagdad-spoorwegproject betekende voor de Osmanen het versterken van de centrale controle over de Arabische provincies en voor Duitsland het bereiken van de Perzische Golf. Dit project, waartegen Engeland en Rusland zich hevig verzetten, werd een van de meest omstreden dossiers van de imperialistische rivaliteit die naar de Eerste Wereldoorlog leidde.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Begin van de bouw van de Hidjaz-spoorlijn in Damascus", "62f58f68"], "d": ["De lijn die Abdülhamid II beval met zijn irade van 2 mei 1900, begon met de bouw op 1 september 1900 in een officiële ceremonie in Damascus. Het project, dat volledig werd uitgevoerd met donaties uit de islamitische wereld en de arbeid van Osmaanse ingenieur-soldaten, bracht de reis van pelgrims tussen Damascus en Medina terug van veertig dagen tot vijf dagen. Het was zowel een prestigewerk dat het morele gezag van het kalifaat versterkte als een strategische investering die de militaire controle over de Hidjaz versterkte.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Mürzsteg-programma: internationale hervormingscontrole in Macedonië", "4c7464da"], "d": ["Na de Ilinden-opstand ontmoetten de Russische en Oostenrijkse keizers elkaar in Mürzsteg en bereidden een nieuw hervormingspakket voor Macedonië voor. Het programma voorzag in het plaatsen van twee buitenlandse burgerlijke agenten naast de Osmaanse inspecteur-generaal, het herorganiseren van de gendarmerie door Europese officieren en het wijzigen van de administratieve grenzen op basis van nationaliteit. Hoewel de Hoge Porte zich verzette met als reden dat haar soevereine rechten werden geschonden, moest zij onder gezamenlijke druk aanvaarden; het programma werd een van de voornaamste factoren die de Unionistische organisatie onder de jonge officieren versnelde.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Overlijden van Murad V", "396659a7"], "d": ["Murad V, die in 1876 ongeveer drie maanden op de troon bleef en werd afgezet, leefde na de pogingen om hem weer op de troon te zetten achtentwintig jaar als gevangene onder strikte bewaking en stierf aan suikerziekte. Hij werd begraven naast zijn moeder in het Cedîd Havâtîn-mausoleum in de Yeni Cami. Hij ging de geschiedenis in als de Osmaanse sultan die het kortst op de troon bleef.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Verlies van Sanaa aan Imam Yahya", "e7f876cb"], "d": ["De opstand die de Zaidi-imam Yahya Hamid ad-Din in 1904 begon, eindigde in april 1905 met de val van Sanaa na een beleg; de stad verliet het Osmaanse bestuur en tijdens het beleg braken honger en epidemieën uit. De bergachtige geografie van Jemen, de lengte van de bevoorradingslijnen en de lokale legitimiteit van het Zaidi-imamaat maakten de Osmaanse heerschappij daar vanaf haar stichting kwetsbaar. De stad zou vijf maanden later tegen zware verliezen worden teruggenomen, maar het Jemen-probleem zou tot 1918 niet worden gesloten.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Aanslag in Yıldız: bomaanslag op Abdülhamid II", "1ee2e1a6"], "d": ["De Dasjnaktsoetjoen-organisatie pleegde een aanslag door een landauer met tijdbom te laten ontploffen bij de koets van de sultan die van het vrijdagse selamlık kwam; dat Abdülhamid enkele minuten vertraging had doordat hij met de sjeik-ul-islam sprak, redde zijn leven. Bij de explosie kwamen zesentwintig mensen om en meer dan vijftig raakten gewond. Het voorval verhardde de veiligheidsobsessie van de sultan en zijn op de spionagedienst gebaseerde despotische bestuur nog meer; het werd ook het onderwerp van het gedicht 'Bir Lahza-i Taahhur' van Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Herovering van Sanaa: neerslaging van de opstand van Imam Yahya", "dec3b8f9"], "d": ["De opstand die in 1904 begon onder leiding van de Zaidi-imam Yahya eindigde in april 1905 met de val van Sanaa en in de stad braken honger en epidemieën uit. De versterkingslegers onder bevel van Ali Rızâ Pasja en Ahmed Feyzi Pasja namen met de campagne die zij tussen 15 juli en 1 september 1905 voerden, ondersteund door de strijdkrachten in Taiz, de stad tegen zware verliezen terug en de opstand werd neergeslagen. De Jemen-campagne bracht het Osmaanse leger tienduizenden verliezen en een enorme financiële last; onder de officieren in Rumelië was de vrees voor 'verbanning naar Jemen' een van de voornaamste grieven die de Unionistische organisatie voedden.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Bijeenkomst van de eerste Meclis-i Meb'ûsan van de Tweede Constitutionele Periode", "e7fd2716"], "d": ["Het parlement, gevormd door de na dertig jaar gehouden tweetrapsverkiezingen, werd op 17 december 1908 geopend met de troonrede van de sultan en Ahmed Rızâ Bey, de leider van de Jongturkse beweging, werd tot voorzitter gekozen. Het parlement, bestaande uit Turkse, Arabische, Albanese, Griekse, Armeense en Joodse afgevaardigden, was de laatste grote proef van het ideaal van het Osmanisme. Maar de onafhankelijkheid van Bulgarije, de annexatie van Bosnië en de proclamatie van de aansluiting van Kreta bij Griekenland hadden dit optimisme al overschaduwd voordat het parlement was geopend.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Actieleger en afzetting van Abdülhamid II: troonsbestijging van Mehmed V Reşad", "6a65a704"], "d": ["Het Actieleger, dat na het Incident van 31 maart uit Thessaloniki vertrok, trok in de nacht van 22-23 april in vier colonnes Constantinopel binnen en op 24 april gaf het Yıldız-paleis zich over. De Meclis-i Umûmî-i Millî besloot op 27 april tot de afzetting van Abdülhamid II; de sultan werd naar Thessaloniki gezonden en zijn broer Mehmed V Reşad werd op de troon gezet. Het persoonlijke bewind van drieëndertig jaar kwam zo ten einde, maar werd opgevolgd door een nieuw tijdperk waarin de sultan een symbool werd en het Comité voor Eenheid en Vooruitgang met steun van het leger regeerde.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Albanese opstand: gewapend verzet in Kosovo en Shkodër", "93ed30c6"], "d": ["Het centralistische belastingbeleid van de Unionistische regering, de wapeninzamelingscampagne en de discussie over het Latijnse alfabet brachten de Albanese stammen, die tot dan toe tot de trouwste elementen van de staat werden gerekend, in opstand. Hoewel het leger onder bevel van Mahmud Şevket Pasja de opstand hard neersloeg, laaide de onrust in 1911 en 1912 opnieuw op. Deze opstanden putten het Osmaanse leger aan de vooravond van de Balkanoorlog uit en versnelden ook de geboorte van de Albanese nationale beweging.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Verdrag van Ouchy: Tripolitanië en Benghazi aan Italië gelaten", "4ffa1fd2"], "d": ["De Hoge Porte, die tegenover de oorlogsvoorbereiding van de Balkanstaten een gevecht aan twee fronten niet aandurfde, sloot in het Zwitserse stadje Ouchy een geheime vrede met Italië en liet Tripolitanië en Benghazi achter. De Osmaanse staat verloor zo zijn laatste grondgebied in Afrika; daartegenover werd de teruggave van het door Italië bezette Rhodos en de Dodekanesos beloofd, maar deze belofte werd nooit nagekomen. Toen het verdrag werd ondertekend, was de Balkanoorlog al begonnen. Met deze gebeurtenis gingen Murzuk (Fezzan), Ghat, Sabha, Ubari, Traghan, Zawila en al-Qatrun (Fezzan (sandjak van de provincie Tripolitanië)) over naar Italiaans bestuur.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Griekse bezetting van Lemnos", "9555af1d"], "d": ["In de Eerste Balkanoorlog bezette de Griekse vloot Lemnos; de haven Moudros van het eiland werd een basis voor de blokkade van de Dardanellen. Het eiland werd in Lausanne (24 juli 1923) aan Griekenland gelaten.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Griekse bezetting van Thasos", "6c03c7f0"], "d": ["In de Eerste Balkanoorlog bezette Griekenland Thasos en Samothrake.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Griekse bezetting van Samothrake", "911e82a3"], "d": ["In de Eerste Balkanoorlog bezette Griekenland Samothrake.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Griekse bezetting van Lesbos", "6b2b07ba"], "d": ["De Griekse vloot ging op Lesbos aan land; het eiland werd aan het einde van de Eerste Balkanoorlog door het Griekse leger en de vloot ingenomen. De Conferentie van Londen (mei 1913) bevestigde de situatie.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Griekse landing op Chios", "901c6539"], "d": ["Chios, dat tijdens de Eerste Balkanoorlog op 7 april 1912 werd gebombardeerd, werd door de Grieken aangevallen met een landing; het Osmaanse garnizoen gaf zich op 3 januari 1913 over. Het eiland werd met het Verdrag van Lausanne (24 juli 1923) aan Griekenland gelaten.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Moord op grootvizier Mahmud Şevket Pasja in Constantinopel", "68e60e63"], "d": ["Mahmud Şevket Pasja, die na de Overval op de Hoge Porte tot grootvizier was benoemd, werd op weg naar het ministerie van Oorlog bij Çarşıkapı gedood door vuur op zijn koets. Het Comité voor Eenheid en Vooruitgang schoof de aanslag in de schoenen van de oppositie en begon een brede golf van arrestaties en executies; de Partij voor Vrijheid en Overeenstemming werd feitelijk geliquideerd. Met dit voorval werd de eenpartijdictatuur van de Unionisten, gebaseerd op het trio Enver-Talat-Cemal, definitief gevestigd.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Begin van de Tweede Balkanoorlog: verdelingsstrijd van de bondgenoten", "48d088a2"], "d": ["De Balkanbondgenoten, die de met het Verdrag van Londen op de Osmanen veroverde gebieden niet konden verdelen, raakten met elkaar slaags; de tweede oorlog begon doordat Bulgarije de Servische en Griekse stellingen aanviel. Toen ook Roemenië en Montenegro tegen Bulgarije het front betraden, stortte het Bulgaarse leger in. De Osmaanse staat maakte van deze gelegenheid gebruik, overschreed de door het Verdrag van Londen getrokken lijn Midye-Enez en nam Oost-Thracië samen met Edirne terug.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Verdrag van Constantinopel: vrede met Bulgarije en bevestiging van Edirne", "c8c18b2d"], "d": ["Het verdrag dat na de Tweede Balkanoorlog tussen de Osmaanse staat en Bulgarije werd ondertekend, aanvaardde de Maritsa als grens en bevestigde juridisch dat Edirne, Kırklareli, Dimetoka en Oost-Thracië Osmaans bleven. Dedeağaç (Alexandroupoli) werd aan Bulgarije gelaten (Kavala was na de Bulgaarse bezetting van de herfst van 1912 in juli 1913 naar Griekenland gegaan en werd op 10 augustus 1913 met het Verdrag van Boekarest in Griekenland bevestigd); de wederzijdse bevolkingsuitwisseling tussen de twee landen en de rechten van de moslims in Bulgarije werden geregeld. De garantie voor het enige stuk grondgebied dat uit de Balkanramp kon worden teruggenomen, is deze tekst. Andere plaatsen die op dezelfde datum werden toegevoegd: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Herovering van Tenedos en Imbros — Verdrag van Athene", "ec084d09"], "d": ["Tenedos en Imbros, die de ingang van de zeestraat bewaken en tot de in de Balkanoorlog door Griekenland bezette noordelijke Egeïsche eilanden behoorden, werden in de onderhandelingen van het Verdrag van Athene voor de verdediging van de Dardanellen als onmisbaar beschouwd en aan de Osmanen teruggegeven. De overige eilanden bleven bij Griekenland. Deze twee eilanden werden de laatste gebieden die het rijk in de Egeïsche Zee in handen hield en werden in Lausanne aan Turkije gelaten.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Verdrag van Athene: vrede met Griekenland en overdracht van Thessaloniki-Ioannina", "8e94def7"], "d": ["Het verdrag dat tussen de Osmaanse staat en Griekenland werd ondertekend, erkende formeel de overgang naar Griekenland van Thessaloniki, Ioannina en Zuid-Macedonië, die in de Balkanoorlog waren verloren, en er werd afgezien van de Osmaanse rechten over Kreta. De rechten op godsdienst en eigendom van de in Griekenland achtergebleven moslims, de status van de vakoefs en de benoeming van muftis werden gedetailleerd geregeld. De status van de Egeïsche eilanden werd onopgelost gelaten en bleef een bron van voortdurende spanning tussen beide staten.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Ondertekening van het geheime Osmaans-Duitse bondgenootschapsverdrag in Constantinopel", "0472efb3"], "d": ["Zodra in Europa de oorlog uitbrak, werd in het herenhuis van grootvizier Said Halim Pasja een geheim bondgenootschapsverdrag tussen de Osmaanse staat en Duitsland ondertekend; de tekst voorzag dat de Osmanen zich aan Duitse zijde zouden scharen indien Rusland tegen Duitsland ten strijde trok. Het verdrag werd zelfs voor het kabinet verborgen gehouden en was slechts aan vier personen bekend. Drie maanden later zou de Osmaanse staat met de overval op de Zwarte Zee feitelijk in de oorlog worden meegesleept, het lot van het rijk was met dit document verbonden.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Eenzijdige afschaffing van de capitulaties", "ec773d18"], "d": ["De Osmaanse regering verklaarde op een moment dat Europa met de oorlog bezig was, dat zij de capitulaties, die aan buitenlanders gerechtelijke, financiële en douaneprivileges verleenden, met ingang van 1 oktober 1914 eenzijdig had afgeschaft. Het einde van deze vierhonderd jaar oude privilegeorde werd in het land met groot enthousiasme voor de onafhankelijkheid ontvangen en in Constantinopel werden feesten gehouden. Alle staten, ook de bondgenoot Duitsland, protesteerden tegen het besluit; de capitulaties zouden pas in 1923 in Lausanne definitief tot het verleden gaan behoren.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Overval op de Zwarte Zee: bombardement van Russische havens door de Osmaanse vloot", "8ad4ef61"], "d": ["De uit Duitsland ontsnapte en 'gekochte' Goeben en Breslau (Yavuz en Midilli), die zich bij de Osmaanse vloot voegden, voeren onder bevel van admiraal Souchon naar de Zwarte Zee, beschoten Russische havens en lieten schepen zinken. Dit bevel, dat Enver Pasja buiten het kabinet om gaf, maakte feitelijk een einde aan de neutraliteit. Binnen een week verklaarden Rusland, Engeland en Frankrijk de oorlog en de Osmaanse staat trad onherroepelijk de Eerste Wereldoorlog in.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Inname van Fao door Brits-Indische strijdkrachten — opening van het Iraakse front", "08663813"], "d": ["Op de ochtend na de dag dat de Entente-mogendheden de Osmaanse staat de oorlog verklaarden, ging de Brits-Indische brigade die in Bahrein wachtte aan land bij Fao aan de monding van de Shatt al-Arab. De kleine Osmaanse eenheid in de vervallen burcht van Fao trok zich onder vuur van de oorlogsschepen terug en het station van de Indische telegraaflijn kwam in Britse handen. Zo werd het Iraakse front geopend.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Afkondiging van de Grote Jihad: voorlezing van de jihad-fatwa in de Fatih-moskee", "2a6174e8"], "d": ["De vijf fatwa's die sjeik-ul-islam Ürgüplü Hayri Efendi gaf, werden in naam van de kalief-sultan in de Fatih-moskee voorgelezen en alle moslims werden opgeroepen tot de jihad tegen de Entente-mogendheden. Deze zet, waarop Duitsland grote hoop vestigde, was erop gericht de moslims in de Britse en Franse koloniën in opstand te brengen. De verwachte algemene opstand kwam niet; integendeel, de opstand van sjerief Hoessein, de emir van Mekka, twee jaar later met Britse steun toonde op pijnlijke wijze de grenzen van de politieke invloed van het kalifaat.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Overgave van Qurna aan de Britten", "621d36b0"], "d": ["De strijdkrachten van Subhi Bey, de gouverneur van Basra, die zich na de val van Basra hadden teruggetrokken naar Qurna, waar de Tigris en de Eufraat samenvloeien, gaven zich na de gevechten van 4-8 december op de ochtend van 9 december 1914 over.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Egypte onder Britse bescherming gebracht en sultanaat uitgeroepen", "55d4e520"], "d": ["Toen de Osmaanse staat de oorlog inging, verklaarde Engeland dat het Egypte, dat het sinds 1882 feitelijk bezet hield, formeel onder zijn bescherming nam; khedive Abbas Hilmi Pasja, die trouw aan de Osmanen bleef, werd afgezet en Hüseyin Kâmil werd met de titel 'sultan' in zijn plaats gezet. Zo werd de sinds 1517 durende juridische Osmaanse soevereiniteit eenzijdig beëindigd. De Hoge Porte erkende het besluit niet en deed twee maanden later met de Kanaalcampagne een poging Egypte terug te nemen.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Campagne van Sarıkamış: ramp aan het Kaukasusfront", "5cbde7f0"], "d": ["Enver Pasja, die de in 1878 verloren Kars-Ardahan-Batoem wilde terugnemen en de Turken in de Kaukasus in opstand wilde brengen, stuurde het 3e Leger in de winter over de Allahuekber-bergen in een manoeuvre om de Russische strijdkrachten te omsingelen. Door onvoldoende winteruitrusting, uitgeputte bevoorrading en sneeuwstormen tot min dertig graden smolt het leger weg voordat het in de strijd kwam; tienduizenden soldaten stierven door bevriezing. De campagne werd een van de zwaarste rampen van de Osmanen in de oorlog en liet het oostfront twee jaar onverdedigd.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Eerste Kanaalcampagne: aanval op Suez over de Sinaïwoestijn", "02dd72f5"], "d": ["Cemal Pasja, de commandant van het 4e Leger, voerde een offensief over de Sinaïwoestijn uit om Egypte van de Britse bezetting te bevrijden en het Suezkanaal voor het verkeer te sluiten. Hoewel de Osmaanse troepen de oostoever van het kanaal bereikten en een deel erin slaagde over te steken, trokken zij zich terug wegens de Britse overmacht en omdat de verwachte Egyptische volksopstand uitbleef. De campagne bereikte haar doel niet, maar had een indirect strategisch effect doordat zij Engeland dwong een grote troepenmacht in Egypte te houden.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Uitvaardiging van de Wet op Verzending en Vestiging (Tehcir)", "2f2bc22c"], "d": ["Na de opstand in Van en de Russische opmars vaardigde de regering de tijdelijke wet uit die de legercommandanten toestond de bevolking die werd geacht de veiligheid achter het front te verstoren naar andere regio's over te brengen, en de sultan bekrachtigde haar op 27 mei 1915. Als gevolg van de toepassing werd het grootste deel van de Armeense bevolking in de oostelijke en zuidelijke provincies van Anatolië in de richting van Syrië en Mosul verzonden; tijdens het transport vielen door ziekte, honger en aanvallen zeer grote aantallen doden. Het besluit is gebleven als de zwaarste en ook vandaag nog meest omstreden kwestie van de laatste jaren van de Osmanen.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Osmaanse eenheden namen Muş terug van de Russische bezetting", "fb1be113"], "d": ["Zes maanden na de eerste Russische bezetting van Muş trok het Osmaanse 16e Korps in het tegenoffensief van Bitlis-Muş het stadje binnen.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş kwam opnieuw in Russische handen", "43ad8a03"], "d": ["Bij het Russische tegenoffensief ontruimde het Osmaanse detachement Muş; het stadje kwam tussen 22 en 25 augustus 1916 opnieuw onder Russische bezetting en bleef tot de lente van 1917 in hun handen.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş definitief bevrijd van Russische bezetting", "f0e89703"], "d": ["Muş, dat in de Eerste Wereldoorlog onder Russische bezetting was gekomen, werd op 1 mei 1917 door Osmaanse strijdkrachten definitief teruggenomen.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Overlijden van Abdülhamid II in het Beylerbeyi-paleis", "c9662582"], "d": ["Abdülhamid II, die in 1909 was afgezet en eerst naar Thessaloniki en na het verlies van de stad in de Balkanoorlog naar Constantinopel was gebracht en in het Beylerbeyi-paleis onder huisarrest werd gehouden, stierf. Tijdens zijn regering van drieëndertig jaar had hij geprobeerd tijd te winnen door de staat uit oorlogen te houden, maar werd ook herinnerd om zijn despotische bestuur. Zijn lichaam werd met een grote menigte begraven in het mausoleum van Mahmud I aan de Divanyolu; zijn dood viel in een oorlogsjaar waarin de orde die hij had gevestigd al lang was geliquideerd.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Verdrag van Brest-Litovsk: herovering van Kars, Ardahan en Batoem", "da82636f"], "d": ["Het verdrag dat werd ondertekend tussen het Rusland dat zich na de bolsjewistische revolutie uit de oorlog had teruggetrokken en de Centrale Mogendheden, sloot het oostfront en gaf de Osmaanse staat Kars, Ardahan en Batoem (Elviye-i Selâse) terug, die met het Verdrag van Berlijn van 1878 waren verloren. Dit was de enige gebiedswinst die de Osmanen na veertig jaar behaalden. Maar na de Wapenstilstand van Moudros zou de regio opnieuw verloren gaan, de definitieve oplossing kwam met het Verdrag van Kars van 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Osmaanse eenheden trokken Artvin binnen", "ca7d1778"], "d": ["De Osmaanse eenheden die op 25 maart de grens van 1914 overschreden, trokken op de Elviye-i Selâse, waarvan Brest-Litovsk de grens van vóór 1878 teruggaf, en trokken op 28 maart 1918 Artvin binnen. Artvin was in 1878 als deel van de sandjak Batoem aan Rusland gelaten; het TDV-lemma Artvin schrijft de terugkeer alleen als 'maart 1918', de dag wordt gegeven door Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan kwam in handen van het Turkse leger", "7fd9e3db"], "d": ["In de Elviye-i Selâse-campagne nam het Osmaanse leger na Artvin op 3 april 1918 Ardahan in; Ardahan was in de Oorlog van '93 in 1877 gevallen en in 1878 aan Rusland gelaten. Kars zou een maand later, op 25 april, worden ingenomen.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Herovering van Batoem", "d37a1a0d"], "d": ["Na de terugtrekking van Rusland uit de oorlog door het Verdrag van Brest-Litovsk nam het Osmaanse leger, dat naar het oosten oprukte, de in 1878 verloren haven Batoem na veertig jaar terug. Deze haven aan het oostelijke uiteinde van de Zwarte Zee was de zee-uitgang van de olie van Bakoe. De winst duurde slechts zeven maanden; na de Wapenstilstand van Moudros zou de regio worden ontruimd.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars kwam onder Osmaans bestuur", "02cbf0b3"], "d": ["In Brest-Litovsk was besloten tot teruggave van de drie sandjaks die met het Verdrag van Berlijn van 1878 waren verloren — Kars, Ardahan en Batoem; het Osmaanse leger trok op 3 april Ardahan, op 14 april Batoem en op 25 april 1918 Kars binnen en het bestuur werd feitelijk gevestigd. Deze gebieden, die de naam 'Elviye-i Selâse' droegen, golden als compensatie voor het sinds de Oorlog van '93 durende verlies. Zij zouden na de wapenstilstand opnieuw verloren gaan en pas met het Verdrag van Kars van 1921 definitief aan Turkije worden gebonden.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Iğdır ingenomen — opmars in de Arasvallei", "87ebf4d3"], "d": ["In het kader van het in februari 1918 begonnen offensief versloegen de Turkse eenheden de Armeense eenheden bij Serderabad ten noorden van de Aras en namen Iğdır op 20 mei 1918 in. Iğdır maakte geen deel uit van de Elviye-i Selâse maar was de kaza Sürmeli van het gouvernement Erivan; na ongeveer 180 jaar werd in de regio het eerste Osmaanse bestuur gevestigd.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Overlijden van Mehmed V Reşad en troonsbestijging van Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, wiens regering van negen jaar werd doorgebracht met de Tripolitaanse, Balkan- en Wereldoorlogen, stierf in de meest kritieke periode van de oorlog en zijn broer Vahdeddin besteeg als Mehmed VI de troon. De nieuwe sultan probeerde zich van de voogdij van het Unionistische kader te bevrijden; toen vier maanden later de wapenstilstand werd getekend, zou hij de liquidatie van het rijk moeten leiden. Hij was de zesendertigste en laatste sultan van de Osmaanse dynastie.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Komst van de Entente-vloot voor Constantinopel en feitelijke bezetting van de stad", "d10cb14d"], "d": ["Na de Wapenstilstand van Moudros ging een geallieerde vloot van meer dan zestig schepen, bestaande uit Britse, Franse, Italiaanse en Griekse schepen, voor Dolmabahçe voor anker en werd Constantinopel feitelijk bezet. Na vierhonderdvijfenzestig jaar kwam de hoofdstad voor het eerst onder controle van buitenlandse soldaten. De uitspraak 'Zoals ze gekomen zijn, zullen ze gaan', die Mustafa Kemal Pasja volgens de overlevering deed toen hij op dezelfde dag in Haydarpaşa aankwam en het tafereel zag, zou een van de symbolische zinnen van de Nationale Strijd worden.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Terugtrekking in het Arasgebied: Iğdır ontruimd", "57572ab4"], "d": ["Krachtens de bepaling van de Wapenstilstand van Moudros over terugtrekking achter de grens van 1914 beval Yakup Şevki Pasja bij emirname van 21 november dat de eenheden buiten de grens van Brest-Litovsk tot 4 december werden teruggetrokken; Iğdır en omgeving werden op deze datum volledig ontruimd. Daarna werd de Aras-Turkse Regering eind december 1918 door de Armeniërs opgeheven.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["De Britten vestigden zich in Artvin", "e2cb3153"], "d": ["Omdat de Wapenstilstand van Moudros van 30 oktober 1918 bepaalde dat het Osmaanse leger zich achter de grens van 1914 terugtrok, werd Artvin ontruimd en op 17 december 1918 door de Britten bezet. Volgens het TDV-lemma Artvin duurde de Britse bezetting tot april 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Brits bestuur in Batoem na Moudros", "9dd768fc"], "d": ["Krachtens de Wapenstilstand van Moudros van 30 oktober 1918 moest de Osmaanse staat zich uit Batoem terugtrekken; de stad werd op 24 december 1918 door Britse eenheden bezet. Batoem, dat in april 1918 een zelfstandig sandjakcentrum was geworden, bleef vanaf deze datum tot juli 1920 onder Britse controle.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan kwam onder Georgische heerschappij", "97cf47f6"], "d": ["Ardahan, dat na Moudros was ontruimd, werd op 20 april 1919 door Georgische strijdkrachten bezet in de dagen waarin de Regering van Zuidwest-Kaukasus door de Britten werd ontbonden. De Georgische heerschappij zou tot 23 februari 1921 duren.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston droeg het bestuur van Kars over aan de Armeense gouverneur", "efa81cb0"], "d": ["De Britse commandant Preston, die op 12-13 april 1919 de Regering van Zuidwest-Kaukasus ontbond, hief op 30 april 1919 de voorlopige sovjetregering op en droeg het bestuur van de stad over aan de Armeniër Karganov, die tot gouverneur van Kars werd gemaakt; in Kars begon de periode van Armeens bestuur, die duurde tot de overwinning van Kâzım Karabekir op 30 oktober 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Congres van Erzurum: nationaal verzetsbesluit van de oostelijke provincies", "41ef0457"], "d": ["Het congres, bijeengeroepen door het Genootschap voor Verdediging van de Rechten van Oost-Anatolië, werd na uitstel door Britse druk met zesenvijftig afgevaardigden geopend en Mustafa Kemal Pasja, die uit het leger was getreden, werd tot voorzitter gekozen. Het congres verklaarde dat het vaderland binnen de nationale grenzen een geheel was, dat mandaat en protectoraat niet konden worden aanvaard en dat de natie, indien de regering uiteenviel, haar eigen lot in handen zou nemen. Deze besluiten zouden zes maanden later de kern van de tekst van het Nationale Pact vormen.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Congres van Sivas: nationaal verzet verenigd onder één dak", "0e9ad36b"], "d": ["Het congres, dat op 4 september 1919 zijn werkzaamheden begon in de Sivas Sultânîsi, verenigde de genootschappen voor verdediging van de rechten uit alle delen van het land onder de naam Genootschap voor Verdediging van de Rechten van Anatolië en Rumelië en koos een Vertegenwoordigend Comité (Heyet-i Temsîliyye). Het voorstel voor een Amerikaans mandaat werd na lange discussies verworpen. Met de op 11 september gepubliceerde verklaring werd de Nationale Strijd een legitieme politieke beweging met één centrum en begon een openlijke machtsstrijd met de regering van Constantinopel.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protocol van Amasya: gesprekken tussen de regering van Constantinopel en het Vertegenwoordigend Comité", "40e6a6ab"], "d": ["Nadat Damat Ferid was gevallen en de regering van Ali Rızâ Pasja was gevormd, werd minister van Marine Salih Pasja naar Amasya gezonden om met het Vertegenwoordigend Comité te spreken. Met de bereikte protocollen erkende de regering van Constantinopel feitelijk het bestaan van de Anatolische beweging; de bijeenroeping van de Meclis-i Meb'ûsan, vrije verkiezingen en het behoud van de nationale grenzen werden aanvaard. Dit is de eerste officiële politieke winst die de Nationale Strijd tegenover Constantinopel behaalde.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Aanvaarding van het Nationale Pact in de laatste Osmaanse Vergadering", "6322865e"], "d": ["De tekst van het Misâk-ı Millî (Ahd-i Millî), ondertekend door 121 afgevaardigden in de laatste Osmaanse Meclis-i Meb'ûsan, stelde als voorwaarde de ondeelbare eenheid van de gebieden binnen de lijn van Moudros waar de Turks-moslimse meerderheid woonde, een volksstemming in de Arabische provincies en West-Thracië, de afschaffing van de capitulaties en volledige politieke en financiële onafhankelijkheid. De tekst werd op 17 februari 1920 met algemene stemmen aanvaard en aan de wereld bekendgemaakt. Deze verklaring was zowel het politieke programma van de Nationale Strijd als de kaart van de grenzen die in Lausanne zouden worden verdedigd; zij werd de directe reden dat de Entente-mogendheden op 16 maart Constantinopel formeel bezetten.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Bij het vertrek van de Britten bleef Artvin bij Georgië", "6d086b06"], "d": ["Volgens het TDV-lemma Artvin duurde de Britse bezetting tot april 1920; bij hun vertrek lieten de Britten de stad aan Georgië. Artvin bleef in Georgische handen tot het ultimatum van de TBMM van 23 februari 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batoem overgedragen aan Georgisch bestuur", "6523d095"], "d": ["De formele overdracht van Batoem door de Britten aan de Georgiërs vond plaats op 7 juli 1920 (het TDV-lemma Batum geeft alleen 'juli 1920'). De regering van Ankara protesteerde op 25 juli tegen de overdracht als 'bezetting'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Verdrag van Gyumri: eerste internationale verdrag van de regering van de TBMM", "9232c690"], "d": ["Nadat het Oostelijke Legerfront onder bevel van Kâzım Karabekir Sarıkamış en Kars had teruggenomen, vroeg Armenië om vrede en aanvaardde met het in Gyumri (Gümrü) ondertekende verdrag dat het Sèvres niet erkende en afzag van zijn gebiedseisen in het oosten. Dit eerste verdrag dat de regering van Ankara ondertekende, werd het eerste internationale document dat Sèvres feitelijk verwierp en opende voor de TBMM de weg naar juridische erkenning. Zo was de oostgrens veiliggesteld en werd het mogelijk strijdkrachten naar het Westelijk front te verplaatsen.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Eerste Slag bij İnönü: eerste overwinning van het reguliere leger", "4add3719"], "d": ["Het nieuw gevormde reguliere leger hield de uit de richting van Bursa oprukkende Griekse strijdkrachten bij de stellingen van İnönü tegen en dwong hen tot terugtrekking. Hoewel dit succes militair beperkt van omvang was, waren de politieke gevolgen zeer groot: de regering van Ankara werd uitgenodigd voor de Conferentie van Londen, de weg werd geopend naar het Verdrag van Moskou met Sovjet-Rusland en de Teşkilât-ı Esâsiyye Kanunu werd aanvaard. Ook het vertrouwen van de binnenlandse publieke opinie in het reguliere leger werd met deze overwinning bevestigd.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Tweede Slag bij İnönü: Grieks offensief voor de tweede keer gebroken", "a974521c"], "d": ["Het Griekse leger, dat van de Conferentie van Londen geen resultaat had, ging uit de richting van Bursa en Uşak opnieuw over tot een offensief, maar werd opnieuw op de heuvels van İnönü tegengehouden en moest zich terugtrekken. Het telegram 'U hebt daar niet alleen de vijand maar ook het slechte lot van de natie overwonnen' dat Mustafa Kemal Pasja aan İsmet Pasja zond, werd na deze overwinning geschreven. De slag verhoogde het internationale aanzien van de Nationale Strijd en versnelde het proces van terugtrekking van Italië uit Anatolië.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Akkoord van Ankara: vrede met Frankrijk en sluiting van het zuidelijk front", "35fc32db"], "d": ["Met het akkoord dat na de overwinning aan de Sakarya in Ankara met Frankrijk werd ondertekend, kwam een einde aan de oorlog aan het zuidelijk front; de Franse strijdkrachten ontruimden Çukurova en Zuidoost-Anatolië, inclusief Adana, Antep, Maraş en Urfa, en trokken zich terug naar de Syrische grens. Een van de Entente-mogendheden had zo de regering van Ankara feitelijk erkend en in het front tegen Sèvres ontstond de eerste scheur. De wapens die uit de ontruimde gebieden werden overgenomen en de vrijgekomen eenheden speelden een cruciale rol in de voorbereiding van het Grote Offensief.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Wapenstilstand van Mudanya: overdracht van Constantinopel en de Zeestraten zonder strijd", "ac0d9baf"], "d": ["Nadat het Turkse leger na het Grote Offensief bij Çanakkale en İzmit tegenover Britse strijdkrachten kwam te staan, eindigde de in Mudanya bijeengekomen conferentie na elf dagen moeizaam onderhandelen met een wapenstilstand. Er werd aanvaard dat Oost-Thracië tot aan de Maritsa binnen vijftien dagen door Griekenland zou worden ontruimd en aan het Turkse bestuur overgedragen en dat Constantinopel en de Zeestraten bij de vredesovereenkomst zouden worden overgedragen. Zo werd de gewapende fase van de Nationale Strijd afgesloten met een diplomatieke overwinning die zonder één schot was behaald en ging de deur naar Lausanne open.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Vertrek van Mehmed VI Vahdeddin uit Constantinopel en verkiezing van Abdülmecid Efendi tot kalief", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, de laatste sultan, wiens positie na de afschaffing van het sultanaat omstreden was geworden, verliet Constantinopel op vrijdagochtend 17 november 1922 met het Britse pantserschip Malaya en ging naar Malta. De TBMM koos twee dagen later, op 19 november, Abdülmecid Efendi tot kalief zonder politieke bevoegdheid. De zeshonderddrieëntwintig jaar durende Osmaanse dynastieke heerschappij kwam zo feitelijk ten einde; het kalifaat zou nog vijftien maanden symbolisch voortduren. Vahdeddin, die naar Malta en vervolgens naar Italië ging, vestigde zich in de Villa Nobel in San Remo; zijn verzoeken om in een moslimland te worden opgenomen leverden niets op en hij stierf daar op 16 mei 1926, waarbij hij herhaalde dat hij nooit afstand had gedaan van zijn rechten op sultanaat en kalifaat.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Overlijden van de laatste sultan Mehmed VI Vahdeddin in San Remo", "7149ed0e"], "d": ["Mehmed Vahdeddin, de laatste Osmaanse sultan, die zich na zijn vertrek uit Constantinopel in de Italiaanse stad San Remo vestigde, stierf op 16 mei 1926 zonder te hebben gehoord dat het kalifaatscongres (13 mei 1926) was bijeengekomen, waarin hij meedeelde nooit afstand te hebben gedaan van zijn rechten op sultanaat en kalifaat. Hij verkeerde in zware geldnood; hij had 60.000 lire schuld bij de winkeliers van San Remo en toen de schuldeisers van zijn dood hoorden, lieten zij beslag leggen op de inboedel van zijn huis.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Verovering van de streek Bolu door Konuralp — Mudurnu, Konurapa en Bolu", "e245cd27"], "d": ["Konuralp, een van de commandanten van Orhan Gazi, richtte zich op het bergachtige gebied ten oosten van de Sakarya en bond Mudurnu, Konurapa en de streek Bolu aan het Osmaanse bestuur; het stadje in de vlakte van Düzce wordt naar hem genoemd. De exacte datum van de verovering is niet bekend; het verhaal berust op de overlevering van Âşıkpaşazâde. De regio was toen een grensgebied dat tussen de Candaroğulları en Byzantium van hand wisselde; de verovering bracht de Osmanen voor het eerst dicht bij de westkust van de Zwarte Zee. Na de Slag bij Ankara zou de streek opnieuw naar de Candaroğulları gaan, maar onder de Veroveraar definitief worden teruggenomen.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Inname van de Byzantijnse stadjes ten zuiden van de Zee van Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Nadat İznik en İzmit waren ingenomen, kwamen de stadjes die Byzantium nog in handen had ten westen van de vlakte van Bursa een voor een onder Osmaans bestuur. Gölyazı rond het Uluabat-meer, Kirmasti en Mihaliç langs de Susurluk-rivier voltooiden de corridor die de zuidkust van de Zee van Marmara met het gebied van Karesi verbond. Deze stadjes gaven zich langdurig zonder beleg over doordat hun omgeving werd afgesneden; de Byzantijnse aanwezigheid in de regio werd zo beperkt tot de Golf van Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korinthe (Gördüs) ging naar het Despotaat Morea", "392495eb"], "d": ["Korinthe, dat sinds 1358 een leen van de Florentijnse familie Acciaiuoli was binnen het prinsdom Achaea, kwam in 1395 in handen van Theodoros, de Byzantijnse despoot van Morea. De stad bleef hierna tot de Osmaanse verovering onder bestuur van het despotaat.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Annexatie van het Hacıemîroğulları-beylik — Ordu en Ünye", "c064f07f"], "d": ["Het Turkmeense beylik, gesticht door Bayram Bey rond Ordu en in de jaren 1350 uitgebreid door zijn zoon Hacı Emîr, was een kleine maar strategische kuststaat met als centrum het huidige Eskipazar: het was het enige onafhankelijke heerschapsgebied tussen Samsun en Trabzon. Emir Süleyman had in 1398 tijdens de Canik-campagne van Yıldırım Bayezid zijn trouw betuigd; na de Slag bij Ankara was het beylik weer vrij geworden. Onder Murad II werd het beylikgebied in dezelfde jaren als de liquidatie van de Tâceddinoğulları rechtstreeks aan het Osmaanse bestuur gebonden en werd de Zwarte Zeekust van Samsun tot Giresun in één hand verenigd.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Verovering van Korinthe (Gördüs)", "87a2bc59"], "d": ["In de Morea-veldtocht van de Veroveraar werd de burcht Akrokorinthos drie maanden belegerd en uiteindelijk vreedzaam overgenomen. De Landengte van Korinthe, die gold als de poort van de Morea, kwam zo bij de Osmanen.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Montenegro bij het Osmaanse bestuur gevoegd — Cetinje", "7fdb7cc8"], "d": ["Toen de dynastie Crnojević, die Zeta bestuurde, in 1496 haar heerschappij opgaf, werd het bergachtige gebied Montenegro, dat de achtertuin van Shkodër vormde, rechtstreeks onder Osmaans bestuur gebracht en eerst als afzonderlijke sandjak en daarna als deel van de sandjak Shkodër georganiseerd. Het klooster van Cetinje werd als religieus centrum van de regio op zijn plaats gelaten. Door de ruwheid van het landschap functioneerde het bestuur hier nooit zo strak als in de vlaktes; twee eeuwen later zou het uit datzelfde klooster voortgekomen vladika-bestuur de kern van de feitelijke onafhankelijkheid worden.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Aanvaarding van de Osmaanse heerschappij door de burcht Bayezid in de Irakeyn-veldtocht", "f29e2e17"], "d": ["Toen grootvizier İbrahim Pasja in de Irakeyn-veldtocht in de omgeving van Bingöl kwam, stemden samen met vele Koerdische stammen in de regio de burchten Van, Toprakkale, Avnik en Bayezid ermee in onder Osmaanse heerschappij te komen. Bayezid was in 1514 tijdens de veldtocht van Yavuz bij de Osmanen gekomen, maar toen het leger terugkeerde, hadden de Safawiden de regio teruggenomen.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz opnieuw naar de Safawiden — terugkeer van Irakeyn", "80b8b761"], "d": ["In de Irakeyn-veldtocht was het leger Tabriz binnengetrokken, maar omdat het eigenlijke doel Bagdad was, was er geen blijvend garnizoen in de stad achtergelaten. Toen het leger, dat de winter in Bagdad had doorgebracht, naar het westen terugkeerde, trok sjah Tahmasp opnieuw het ontruimde Azerbeidzjan binnen en nam Tabriz terug. Dit was het herhaalde patroon van de Osmaans-Safawidische oorlogen: Tabriz werd vijf keer ingenomen en kon vijf keer niet worden gehouden; de stad zou pas in 1585 een langdurig Osmaans garnizoen krijgen.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van en Erciş vielen in handen van Tahmasp (Osmaanse positie eindigde in 1534-35)", "cb93d561"], "d": ["In de regio die Van in 1534 onder Osmaanse heerschappij had gebracht, hield Ulama Pasja in de burcht Van stand tegen het Safawidische beleg; de burcht kwam in Safawidische handen en de Safawidische strijdkrachten die Erciş belegerden, waren met Osmaanse hulp teruggedrongen. Toen Süleyman Ahlat bereikte (23 september 1535) was Van al in handen van Tahmasp. Van bleef tot 1548 Safawidisch.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["De sandjak Bayezid kwam onder Safawidische heerschappij (Van en Erciş waren in 1535 al Safawidisch)", "806a2cf1"], "d": ["De sandjak Bayezid in het midden van de Osmaans-Safawidische grens kwam opnieuw in Iraanse handen (Kaya 2017 noemt dit 'samen met Van en Erciş'; maar Van en Erciş waren volgens Karataş 2025 en de TDV al op 22 september 1535 naar de Safawiden teruggekeerd — zie het vorige item); bij deze overdracht werden sommige plaatsen van de sandjak verwoest. De sandjak wisselde tot het laatste kwart van de 16e eeuw herhaaldelijk van hand tussen de twee staten.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["De sandjak Bayezid kwam tijdens de Nachitsjevan-veldtocht opnieuw bij de Osmanen", "cf0171fa"], "d": ["Tijdens de derde Iraanse (Nachitsjevan-)veldtocht van Süleyman werd de sandjak Bayezid opnieuw onder Osmaans bestuur gebracht. In de veldtocht van 1554 werd Bayezid een belangrijke basis voor het leger; de sandjak kwam in 1578 definitief onder Osmaanse soevereiniteit.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Verlies van Revan aan Sjah Abbas", "34413cf2"], "d": ["Toen het oostfront onverdedigd bleef in de jaren waarin de Celali-opstanden Anatolië op slot zetten, ging Sjah Abbas, die zijn leger naar Europees model had gereorganiseerd, over tot het offensief. De burcht Revan, die Ferhad Pasja in 1583 had laten bouwen, gaf zich over na een beleg van zeven maanden. De eerste schakel van de met het Verdrag van Ferhad Pasja verworven Kaukasuslijn was gebroken en binnen de volgende drie jaar zou heel Zuid-Kaukasus verloren gaan.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Verlies van Tbilisi en Ganja", "3fb51753"], "d": ["Na de val van Revan rukte het Safawidische leger op langs de Kuravallei; Ganja, het centrum van Karabach, en Tbilisi, de hoofdstad van Georgië, gingen achtereenvolgens verloren. De Osmaanse staat voerde tegelijkertijd de dertien jaar durende lange oorlog aan het Oostenrijkse front en was in Anatolië bezig met de Celali's; er waren geen strijdkrachten om naar het oosten te sturen. Zo kwam feitelijk een einde aan de orde van de brede Kaukasus-provincies die met het Verdrag van Ferhad Pasja in 1590 was gevestigd.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Verlies van Shirvan — Shamakhi, Bakoe en Derbent", "81beab11"], "d": ["De provincie Shirvan aan de Kaspische kust, die met de veldtochten van Özdemiroğlu Osman Pasja van 1578-1585 was verworven en als belangrijkste bron van de zijdehandel aanzienlijke inkomsten aan de Osmaanse financiën had verschaft, werd door de naar het noorden gerichte campagne van Sjah Abbas, die Shamakhi, Bakoe en Derbent achtereenvolgens innam, geliquideerd. Het verlies was niet alleen gebiedsverlies: ook de route waarlangs de Iraanse zijde via de Osmanen naar Europa stroomde, kwam buiten controle en de Safawidische staat begon de zijde via de Indische Oceaan te verhandelen.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Verlies van Taiz", "65f20d53"], "d": ["De Osmanen verlieten in 1038 (1629), samen met de aan het Qasimidische bestuur in Sanaa overgelaten heerschappij over Jemen, ook Taiz — de eerste grote stap in het proces waarin de Zaidi-imams het binnenland van Jemen terugnamen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Verlies van Jemen — heerschappij van de Qasimidische imams", "49e83e3c"], "d": ["Jemen was sinds 1538 een Osmaanse provincie; maar het verzet van de Zaidi-imams hield nooit op. De opstand die imam al-Qasim begon, verspreidde zich onder zijn zoon al-Mu'ayyad Muhammad over het hele land en de Osmaanse garnizoenen werden een voor een belegerd. In de jaren waarin Murad IV zich op Bagdad en Revan concentreerde, konden geen versterkingen worden gezonden; Taiz ging in 1629 verloren en Mocha werd in de laatste fase van dezelfde ineenstorting op 22 oktober 1635 ontruimd. In 1635 ontruimden ook de laatste eenheden in Sanaa en Zabid Jemen. Zo bleef de oostkust van de Rode Zee tweehonderdzevenendertig jaar buiten het rijk en werd pas in 1872 teruggenomen. Lahij (al-Hawta) was volgens de TDV İslâm Ansiklopedisi tot 1635 in handen van de Osmanen; vanaf die datum waren de Zaidi-imams er invloedrijk.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Ontruiming van Mocha", "c6b3061a"], "d": ["Mustafa Bey ontruimde Mocha op 10 Jumada al-awwal 1045 (22 oktober 1635) met de resterende strijdkrachten en wapens; daarna benoemde Hasan b. al-Qasim, zoon van imam al-Qasim, zijn eigen mannen in Zabid en Mocha en vestigde zo ook aan de kust van Tihama Qasimidische controle.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Verlies van Al-Hasa aan het emiraat van de Banu Khalid", "a9b6131a"], "d": ["Al-Hasa was in 1550 gesticht als provincie om de westkust van de Perzische Golf voor Portugal af te sluiten; maar het lag ver van Constantinopel, aan het uiteinde van één enkele woestijnroute. In de jaren waarin het beleg van Kreta de middelen uitputte, verdreef de stam Banu Khalid in de regio onder leiding van Barrak b. Ghurayr het Osmaanse garnizoen en stichtte een eigen emiraat. De westkust van de Golf bleef anderhalve eeuw in handen van stamemiraten; in 1795 ging zij naar de Saoedi's, in 1871 opnieuw naar de Osmanen.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Verlies van Preveza en Vonitsa aan Venetië — opening van de kust van Epirus", "1201204c"], "d": ["Venetië, dat zich bij de Heilige Liga had aangesloten, nam voor het begin van de Morea-campagne twee burchten in die de monding van de Ambracische Golf bewaken: Preveza en Vonitsa aan de overkant. In dezelfde zomer was ook Santa Maura (Lefkada) gevallen. Deze drie posities maakten het mogelijk de vloot veilig vanuit de Ionische Zee het binnenland van Griekenland in te brengen en werden de basis van de Morea-campagne die het jaar daarop begon. Preveza en Vonitsa werden in Passarowitz ook bij Venetië gelaten; zij zouden pas in 1798 naar het Osmaanse bestuur terugkeren.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Verlies van Szolnok — uiteenvallen van de Tisza-lijn", "51c2c8ef"], "d": ["Na de val van Uyvar in augustus draaide het Habsburgse leger naar het zuiden en nam Szolnok, het bruggenhoofd aan de rivier de Tisza, in. De stad was de enige veilige doorgang tussen Boeda en Transsylvanië; het verlies ervan betekende dat de Osmaanse burchten in de oostelijke helft van Hongarije van elkaar werden afgesneden. Dat de bevoorradingsroute afgesneden was bij het beleg van Boeda het jaar daarop, was beslissend.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Verlies van Modon aan Venetië", "114c9cc0"], "d": ["Modon aan de zuidwestpunt van het schiereiland Morea was de haven die Venetië drie eeuwen eerder had verloren en 'een van de twee ogen van de staat' noemde. De burcht, die na de val van Koroni werd belegerd, werd gelijktijdig over land en zee beschoten en overgenomen. Morosini's Morea-campagne nam zo de hele westkust van het schiereiland in en de weg naar het binnenland ging open.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Verlies van Pécs", "99d54cf4"], "d": ["Na de val van Boeda in september trok het Habsburgse leger ten westen van de Donau naar het zuiden en nam Pécs in, dat sinds de tijd van Süleyman Osmaans was. De stad, die bekend stond om de Gazi Kâsım Pasja-moskee, was een van de meest ontwikkelde sandjakcentra van de provincie Boeda. Het verlies betekende de opening van de weg die naar de vlakte van Mohács afdaalt; het jaar daarop zou de Tweede Slag bij Mohács precies hier plaatsvinden.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Verlies van Szeged", "9fbee1b2"], "d": ["Szeged, op het punt waar de rivieren Tisza en Maros samenvloeien, was de zuidelijke poort van de Hongaarse vlakte en bewaakte de weg naar de provincie Temesvár. Na de val van Boeda en Pécs in dezelfde herfst gaf de belegerde burcht zich snel over. Het verlies van drie burchten in één seizoen was een teken dat de sinds 1541 gevestigde Osmaanse bestuursstructuur in Hongarije begon in te storten. De atlas beschouwt op dezelfde dag ook Zenta aan de Tisza als van de Osmanen naar de Habsburgse kant gegaan (een voor Zenta specifieke overgavedag werd in de bron niet gelezen, de dag is overgenomen van Szeged; TDV zenta: vanaf oktober 1686 begonnen gevechten tussen de Osmanen en de door de Habsburgers aangevoerde bondgenoten — verklaarde benadering).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Verlies van Patras (Balyabadra) — noordelijke poort van de Morea", "b9cff63c"], "d": ["Patras aan de ingang van de Golf van Korinthe was de haven die de doorgang tussen de Morea en Rumelië controleerde. Nadat het Venetiaanse leger de stad had ingenomen, vielen ook de burchten aan beide oevers van de golf achtereenvolgens en werd het schiereiland over land volledig geïsoleerd. Aan het einde van deze campagne ging de gehele Morea naar Venetië; de regio zou tot 1715 onder de naam 'Regno di Morea' worden bestuurd.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Korinthe (Gördüs) aan Venetië gelaten", "9a25b6b9"], "d": ["Na de val van Patras werd Korinthe vreedzaam aan de Venetianen gelaten en verliet de moslimse bevolking de stad. In augustus 1687 verzamelde het leger van Morosini zich in Korinthe voor de Atheense veldtocht.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Verlies van Eger", "983391aa"], "d": ["Eger was in 1596 ingenomen met de veldtocht waaraan Mehmed III persoonlijk deelnam en was het centrum van een provincie met dezelfde naam geworden. Deze laatste grote Osmaanse burcht in Noord-Hongarije hield, na de Tweede Slag bij Mohács volledig omsingeld, nog een jaar stand en gaf zich over door honger. Met het verlies ervan werd de noordelijke flank van de Osmaanse staat in Hongarije volledig geliquideerd.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Verlies van Székesfehérvár — kroningsstad van de Hongaarse koningen", "c6147255"], "d": ["De stad waar de Hongaarse koningen eeuwenlang werden gekroond en begraven, was in 1543 door Süleyman ingenomen en een van de belangrijkste sandjakcentra van de provincie Boeda geworden. Ongeveer twee jaar na de val van Boeda gaf de burcht, die geheel van haar omgeving was afgesneden, zich over. Met dit verlies werd de Osmaanse aanwezigheid ten westen van de Donau teruggebracht tot de omgeving van Srem en Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Verlies van Szigetvár", "834910a7"], "d": ["Szigetvár was de burcht waar Süleyman de Wetgever tijdens zijn dertiende en laatste veldtocht in 1566 stierf terwijl het beleg nog voortduurde; daarom had het een symbolische plaats in het Osmaanse geheugen. Honderddrieëntwintig jaar later, nadat alle burchten in de omgeving waren gevallen, gaf ook de door moerassen beschermde burcht zich over. Het mausoleum waar de ingewanden van Süleyman begraven lagen en het stadje eromheen werden na de overgang naar Habsburgs bestuur verwoest. Andere plaats die op dezelfde datum in de atlas van de Osmanen naar de Habsburgers ging: Barcs — volgt de abi-centrumketen van Szigetvár (Bánlaky 0017/1449; verklaarde benadering).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Verlies van Varad", "6cce360d"], "d": ["Varad was de sleutelburcht naar Transsylvanië, die Köprülü Mehmed Pasja in 1660 had ingenomen en tot centrum van een provincie met dezelfde naam had gemaakt. De burcht, die na de nederlaag bij Slankamen volledig alleen kwam te staan, gaf zich na een bijna twee jaar durende blokkade over door honger. Met het verlies ervan kwam feitelijk een einde aan de Osmaanse invloed op Transsylvanië en vestigde de Habsburgse heerschappij zich ten oosten van de Tisza.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Verlies van Ineu — sluiting van de weg naar Transsylvanië", "4b5e30d8"], "d": ["Ineu was een burcht die in 1658 was ingenomen en de verbinding tussen Varad en Temesvár in stand hield. Toen zijn omgeving onmiddellijk na de val van Varad werd afgesneden, ging ook hij verloren. Zo werd de provincie Temesvár vanuit het noorden volledig geïsoleerd en bleef tot Karlowitz bestaan als het enige grondgebied in Hongarije dat in Osmaanse handen bleef.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Vestiging van het vladika-bestuur in Montenegro — feitelijke afscheiding van Cetinje", "a924b778"], "d": ["In de jaren waarin de oorlog van de Heilige Liga de Osmaanse controle op de Balkan verslapte, werd het metropolitaat aan het hoofd van het klooster van Cetinje een ambt dat binnen de familie Petrović van vader op zoon overging en kreeg de regio feitelijk een afzonderlijk bestuur. Dankzij de ontoegankelijkheid van de bergen bleef dit vladikaat twee eeuwen lang bestaan in een positie die noch volledig onafhankelijk noch volledig gebonden was; juridisch zou zijn onafhankelijkheid pas met het Verdrag van Berlijn in 1878 worden erkend.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Herovering van Korinthe (Gördüs)", "26f53e3a"], "d": ["De eerste grote halte van de Morea-veldtocht van Damad Ali Pasja was Korinthe; de Osmanen namen de stad in juni 1715 terug op de Venetianen en rukten vanaf hier op naar de rest van het schiereiland.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Offensief van Nadir: verlies van Tabriz, Nachitsjevan, Hamadan, Kermanshah, Maragheh en Qasr-i Shirin", "d95efd59"], "d": ["De steden van West-Iran die tussen 1723 en 1727 waren ingenomen gebruik makend van de ineenstorting van de Safawidische staat, gingen door het offensief van Nadir Khan, die in Iran de feitelijke macht greep, een voor een verloren. In Azerbeidzjan kwamen ook Ardabil en Khalkhal in handen van Nadir. Het verlies van Hamadan, Kermanshah en Qasr-i Shirin vond in Constantinopel zware weerklank; dat het leger niet ten strijde trok maar in Üsküdar bleef wachten en dat men het verlies probeerde te verhullen, was een van de directe oorzaken van de Opstand van Patrona Halil die zes weken later uitbrak. De atlas beschouwt ook Kotur, dat de keten van Khoy volgt, op deze dag als van de Osmanen naar de Safawiden gegaan (Uluerler 2015, Turkish Studies 10/5, p. 6; een voor Kotur specifieke dag staat niet in de bron — verklaarde benadering).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Nederlaag bij Baghavard (Arpaçay) — verlies van de Kaukasus aan Nadir Khan", "4262f54c"], "d": ["De Kaukasische provincies die in 1723-1725 waren ingenomen gebruik makend van de ineenstorting van de Safawidische staat, konden tien jaar worden gehouden. Nadir Khan, die in Iran de feitelijke macht had gegrepen, bracht bij Baghavard bij Revan het Osmaanse leger een zware nederlaag toe; serdar Abdullah Köprülü Pasja sneuvelde op het slagveld. Na de nederlaag werden Revan, Tbilisi, Ganja en Shirvan binnen enkele maanden ontruimd. De oostgrens keerde terug naar de lijn van Qasr-i Shirin van 1639, zoals in 1746 zou worden bevestigd.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Verlies van Bender aan de Russen", "0daca453"], "d": ["Na de nederlaag bij Kagul had het Osmaanse leger zich teruggetrokken ten zuiden van de Donau en waren de burchten tussen Moldavië en Özi alleen komen te staan. Bender, dat het doorwaadbare punt van de Dnjestr bewaakte, werd na een beleg van twee maanden bij storm ingenomen; de stad werd geplunderd. Het verlies van de burcht verbrak de middelste schakel van de verdedigingslinie van de noordelijke Zwarte Zee, waarna ook Akkerman en Kilia vielen. In Küçük Kaynarca zou Bender worden teruggegeven, maar in 1806 opnieuw worden verloren.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Het emiraat van de Sabah in Koeweit kwam onder Osmaanse bescherming", "3584dba0"], "d": ["Volgens het TDV-lemma Kuveyt was de aanlegplaats aan het begin van de 18e eeuw gesticht door de stam Utub uit Nejd en nam de familie Sabah tegen het einde van de eeuw het bestuur over. In dezelfde jaren dat Al-Hasa in handen van de Saoedi's kwam, kwam het emiraat, dat tegenover de wahhabitische druk geen andere keus had dan steun te zoeken bij Basra, onder Osmaanse bescherming. De band zou in 1871 met de regeling van Midhat Pasja voor Basra worden geformaliseerd en Koeweit zou gelden als een van de drie kazas van de sandjak Basra; ook de latere gebiedsaanspraak van Irak berust op deze aantekening.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Verlies van Mekka aan de wahhabieten", "2da23acd"], "d": ["De wahhabitische beweging, die in Nejd was ontstaan, richtte zich onder Saud b. Abd al-Aziz op de Hidjaz; na Ta'if en Medina werd ook Mekka voor de tweede keer overgenomen — de emir van Mekka, sjerief Ghalib, droeg de stad onder voorwaarde dat hij emir bleef over aan de wahhabieten. De mausoleums werden verwoest en de weg voor de pelgrimskaravanen uit Damascus en Caïro werd afgesneden; ook de surre die de sultan elk jaar naar de Haramain zond, werd in deze jaren onderbroken — de enige uitzondering op deze toewijzing die tot 1915 ononderbroken doorliep, is de periode van wahhabitische heerschappij. Omdat de titel van beschermheer van de Haramain een van de fundamentele steunpilaren van de legitimiteit van de sultan was, was dit verlies meer dan gebiedsverlies een zware politieke slag; de herovering zou zeven jaar duren en mogelijk worden met het leger van Mehmed Ali Pasja van Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Einde van de Republiek Dubrovnik — Franse bezetting", "f8e27bf1"], "d": ["De Fransen, die zich met het Verdrag van Campo Formio (1797) aan de Dalmatische kust vestigden, namen op 27 mei 1806 Dubrovnik in en maakten een einde aan de kleine handelsrepubliek. Zo kwam een einde aan de drieënhalve eeuw durende vazalstatus van Dubrovnik, dat sinds 1458 schatting aan de Osmanen betaalde en zijn autonomie en handelsprivileges behield; de stad en het eiland Mljet van de republiek gaan op de kaart over naar rechtstreeks Frans bestuur.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Verlies van Soechoem aan de Russen — opening van de oostelijke Zwarte Zeekust", "adc96bd4"], "d": ["In de Osmaans-Russische oorlog van 1806-1812 richtte de Russische vloot zich op de oostelijke Zwarte Zeekust en nam in Abchazië Suhumkale, waarop de Osmaanse heerschappij steunde, in. De burcht was het centrum van de verbinding met de Kaukasische stammen en van de kusthandel. Met het verlies ervan vestigde Rusland zich voor het eerst blijvend aan de oostkust van de Zwarte Zee; de Osmaanse invloed in de Kaukasus werd teruggebracht tot de omgeving van Anapa en Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga overgelaten aan Osmaans bestuur", "66e0cc5d"], "d": ["Parga was sinds 1401 in handen van Venetië en was nooit onder Osmaans bestuur gekomen; na de ondergang van Venetië ging het achtereenvolgens naar Frankrijk en Engeland. Het TDV-lemma Tepedelenli Ali Paşa vat de situatie als volgt samen: de stad gaf zich over aan de Engelsen en werd pas in 1819 aan het bestuur van Ali Pasja afgestaan. De overdracht resulteerde in de migratie van het grootste deel van de bevolking naar de Ionische eilanden. Zo kwam ook de laatste van het in Passarowitz bij Venetië gelaten trio Preveza-Parga-Vonitsa bij het rijk; Parga zou vierennegentig jaar Osmaans blijven.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Korinthe (Gördüs) ging naar de Griekse rebellen", "892dcdc6"], "d": ["Tijdens de Griekse onafhankelijkheidsoorlog kwam Akrokorinthos in handen van de rebellen en werd de burchtcommandant Kâmil Bey gevangengenomen.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Verlies van Nauplion (Anabolu) aan de rebellen", "1a67fa50"], "d": ["Nauplion, de best versterkte haven van de Morea, gaf zich na een blokkade van meer dan een jaar over door honger. De burcht was sinds het begin van de opstand het laatste grote steunpunt van de Osmaanse controle op het schiereiland; met het verlies ervan kwam de hele Morea in handen van de rebellen. De stad zou kort daarna de eerste hoofdstad van de nieuwe Griekse staat worden.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Lepanto (İnebahtı) kwam onder Grieks bestuur", "c9d19d4b"], "d": ["Lepanto aan de noordkust van de Golf van Korinthe, dat tot de Griekse opstand in Osmaanse handen was gebleven, ging in april 1829 verloren en kwam onder Grieks bestuur; de naam van het stadje werd veranderd in het antieke Nafpaktos. De moslimse en joodse bevolking van de stad verdween volledig en het werd een klein stadje.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Franse bezetting van Algiers — einde van het driehonderd jaar oude ocak", "0be8f568"], "d": ["Onder het voorwendsel van het incident van de waaier, ontstaan uit een schuldgeschil, hield Frankrijk de kust van Algiers drie jaar lang geblokkeerd en zette daarna soldaten aan land bij Sidi Ferruch. Aan het einde van een drie weken durende campagne gaf Hussein Dey zich over en kwam een einde aan het Osmaanse ocak van Algiers dat sinds 1516 bestond. De bezetting bleef niet beperkt tot de hoofdstad; ook Tlemcen, Cherchell en Médéa in het binnenland gingen in dezelfde zomer verloren. Het zou nog vierentwintig jaar duren voordat de hele kust onder Franse controle kwam.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Euboea (Eğriboz) aan Griekenland gegeven — samen met het eiland (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, dat tijdens de Griekse onafhankelijkheidsoorlog het toneel was van hevige gevechten maar in Osmaanse handen was gebleven, werd in 1831 na de inwerkingtreding van het vredesverdrag aan de Grieken gegeven. De moslimse bevolking van de stad, die sinds 1470 een belangrijke zeebasis was, verkocht al haar bezittingen tegen zeer lage prijzen en migreerde massaal naar Osmaans grondgebied; de stad bleef lange tijd leeg en de Duitse reiziger Fallmerayer noemde haar in 1842 een spookstad.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Franse bezetting van Oran", "a8415d66"], "d": ["Oran, dat Spanje in 1792 zonder oorlog overdroeg, was de grootste haven in het westen van Algerije. Zes maanden na de val van de hoofdstad trokken Franse eenheden de stad binnen. De westelijke campagne die hier begon, zou al snel het verzet van emir Abdelkader ontmoeten dat vijftien jaar zou duren.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Bezetting van Annaba (Bône)", "21f37fb1"], "d": ["Annaba, de haven in Oost-Algerije dicht bij de Tunesische grens, werd door Franse strijdkrachten ingenomen en tot basis gemaakt voor de opmars naar Constantine. De stad was tevens de dichtstbijzijnde Afrikaanse haven tegenover het eiland Sardinië.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Overdracht van Athene aan de nieuwe Griekse staat (dag waarop de Beierse eenheden de Akropolis overnamen)", "deee4d37"], "d": ["Athene, dat sinds 1456 Osmaans was, was tijdens de Griekse onafhankelijkheidsoorlog enkele keren van hand gewisseld en het garnizoen op de Akropolis was in 1827 opnieuw onder Osmaanse controle gekomen. Omdat het ten noorden van de met het Protocol van Londen getrokken grens lag, werd de stad aan het nieuwe koninkrijk overgedragen en ontruimde het garnizoen de Akropolis. De atlasdag is de dag waarop de Beierse eenheden de Akropolis overnamen; het feitelijke vertrek van het Osmaanse garnizoen vond enkele dagen later plaats (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, hfst. 13; Finlay, Journals and Letters, dl. I, p. 67). Het jaar daarop werd Athene in de plaats van Nauplion tot hoofdstad van Griekenland uitgeroepen.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Bezetting van Bejaïa (Bougie)", "a8927e00"], "d": ["De haven Bejaïa, waar het Kabylische gebergte de zee bereikt, was de laatste onafhankelijke schakel van de kustlijn tussen Algiers en Annaba. Zij werd ingenomen met steun van zeeartillerie; maar het bergachtige binnenland erachter zou nog dertig jaar niet onder Franse controle komen. Deze bezettingen langs de kust vormen het jaar na jaar smelten van Osmaans Algerije op de kaart.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Bezetting van Sétif", "2073731a"], "d": ["Na de val van Constantine een jaar eerder trokken de Franse strijdkrachten het plateau op, namen de oude Romeinse stad Sétif in en vestigden daar een blijvend garnizoen. Sétif was het punt waar de karavaanroutes tussen de kust en de Sahara elkaar kruisten; de bezetting toonde dat Frankrijk niet langer alleen de havens maar ook het binnenlandse handelsnetwerk begon te controleren.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Bezetting van Biskra — verlies van de poort naar de Sahara", "d895cad0"], "d": ["Biskra was de poort naar de Sahara aan de zuidvoet van het Atlasgebergte en het centrum van de dadeloases. Met de inname in de jaren waarin het verzet van emir Abdelkader begon te bezwijken, bereikte de Franse controle voor het eerst de noordkust van de woestijn. Wat volgde was een woestijncampagne die oase voor oase vorderde.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Bezetting van Touggourt — verlies van heel Algerije", "33c056e2"], "d": ["Met de inname van de oasestad Touggourt ten noorden van de Sahara was de in 1830 begonnen bezetting in de noordelijke helft van het huidige Algerije voltooid. De Osmaanse staat vocht in deze jaren in de Krimoorlog aan dezelfde kant als Frankrijk; zij gaf haar juridische aanspraak op Algerije nooit formeel op, maar kon feitelijk geen enkele stap zetten. Het enige gebied dat in Noord-Afrika overbleef, was Tripolitanië.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Val van El Obeid — Kordofan ging naar de Mahdistische strijdkrachten", "58299f62"], "d": ["De beweging die Muhammad Ahmad begon nadat hij zichzelf tot mahdi had uitgeroepen, verspreidde zich snel tegen het Egyptische bestuur in Soedan. El Obeid, het centrum van Kordofan, viel na een beleg van vier maanden en werd de hoofdstad van de opstand; de schatkist en wapendepots in de stad maakten het mogelijk dat de beweging zich tot een leger ontwikkelde. Soedan was juridisch nog gebied van het khedivaat Egypte, dat aan de Osmanen was gebonden, dus het verlies valt op de kaart uit het lichaam van het rijk.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Val van Khartoem — verlies van heel Soedan", "d4b98464"], "d": ["Na een beleg van tien maanden trokken de Mahdistische strijdkrachten Khartoem binnen op het punt waar de Blauwe en de Witte Nijl samenvloeien; de gouverneur van de stad, Gordon, werd gedood en de voor hulp gezonden Britse colonne kwam twee dagen te laat. Vanaf deze datum bleef heel Soedan, inclusief Sennar, Dongola en Kordofan, veertien jaar onder bestuur van de Mahdistische staat. De regio zou pas in 1899, met volledig verbroken Osmaanse band, onder gezamenlijk Brits-Egyptisch bestuur komen.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Italiaanse bezetting van Massawa — verlies van de westkust van de Rode Zee", "c333b95b"], "d": ["De haven Massawa, het centrum van de provincie Habesh, werd bezet door Italië, dat gebruik maakte van de verwarring die de Mahdistische opstand in Soedan veroorzaakte; dit vormde de kern van Italiaans Eritrea. Ook het noordelijker gelegen Suakin en de archipel Dahlak in zee gingen in hetzelfde proces verloren. Zo kwam een einde aan de sinds de tijd van Yavuz Sultan Selim durende Osmaanse heerschappij aan de westkust van de Rode Zee en werd de zee nu aan beide oevers een buitenlands water.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Italiaanse bezetting van Rhodos", "e08662c5"], "d": ["Italië, dat de Osmaanse staat in de Tripolitaanse oorlog aan de onderhandelingstafel wilde brengen, bracht de oorlog naar de Middellandse Zee en zette soldaten aan land op Rhodos. Het eiland werd binnen enkele dagen overgenomen. Rhodos, dat Süleyman in 1522 na een lang beleg had ingenomen en driehonderdnegentig jaar had gehouden, hield zo op de grootste eilandbasis van het rijk in de oostelijke Middellandse Zee te zijn; hoewel het in het Verdrag van Ouchy als tijdelijke bezetting gold, kon het niet meer worden teruggenomen.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Italiaanse bezetting van de Dodekanesos", "200aacf2"], "d": ["Binnen een week na de inname van Rhodos bezette de Italiaanse vloot ook de omliggende eilanden; deze archipel zou later de naam 'Dodekanesos' krijgen. De meeste eilanden lagen enkele mijlen van de Anatolische kust en beheersten de zuidoostelijke doorgang van de Egeïsche Zee. De bezetting gold in het Verdrag van Ouchy als tijdelijk in ruil voor het opgeven van Tripolitanië, maar Italië ontruimde de eilanden nooit; zij zouden in 1947 aan Griekenland worden overgedragen.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Bezetting van Kos", "ab246c62"], "d": ["Kos, de laatste schakel van de Dodekanesos-operatie, was een vruchtbaar en dichtbevolkt eiland recht tegenover het schiereiland Bodrum. Met de bezetting kwamen alle eilanden in de zuidoostelijke hoek van de Egeïsche Zee onder Italiaanse controle en werd de zuidwestkust van Anatolië van begin tot eind omringd door een keten van buitenlandse eilanden.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Onafhankelijkheidsverklaring van Ikaria", "c4452033"], "d": ["Op het kleine eiland Ikaria tussen Samos en Chios kwam de bevolking in het klimaat van onzekerheid dat de Italiaanse bezettingen creëerden in opstand, verdreef de Osmaanse gendarmerie van het eiland en riep met een eigen vlag, postzegel en raad een 'vrije staat' uit die vijf maanden duurde. In november 1912 sloot het eiland zich aan bij Griekenland. Ondanks zijn kleinheid is dit voorval een duidelijke aanwijzing van hoe het centrale bestuur in de Egeïsche Zee uiteenviel.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Samos verliet het Osmaanse bestuur", "3a862f2b"], "d": ["Samos was sinds 1832 een autonoom vorstendom dat belasting aan de Osmanen betaalde en werd bestuurd door een door Constantinopel benoemde bey. In het vacuüm dat de Tripolitaanse oorlog schiep, nam de eenheidsgezinde beweging op het eiland het bestuur over en kwam feitelijk een einde aan de orde van het autonome vorstendom; het eiland verklaarde in hetzelfde jaar dat het zich bij Griekenland aansloot. Dit eiland, twee kilometer van de Anatolische kust, werd een van de eerste gebieden die in de Egeïsche Zee verloren gingen.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Val van Ioannina — verlies van Epirus en Parga", "d42fce18"], "d": ["Ioannina, dat in de Balkanoorlog vijf maanden werd belegerd, gaf zich over na de val van de stellingen van Bizani; met de stad ging heel Epirus naar Griekenland. Ook Parga, dat aan de sandjak Ioannina was gebonden, ging op deze datum verloren en het Osmaanse bestuur van vierennegentig jaar kwam ten einde. Het verlies van Ioannina betekende het sluiten van het laatste venster van het rijk naar de Adriatische Zee.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Val van Edirne aan de Bulgaren", "459d2e56"], "d": ["Na een beleg van vijfenhalve maand gaf Edirne, waarvan munitie en voorraden waren uitgeput, zich over; Şükrü Pasja werd gevangengenomen. De val van de stad, die sinds 1361 Osmaans was en tweeënnegentig jaar hoofdstad was geweest, werd beschouwd als de zwaarste slag van de Balkanoorlog. Edirne zou vier maanden later in de Tweede Balkanoorlog worden teruggenomen gebruik makend van de ineenstorting van Bulgarije aan de andere fronten.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Verlies van Yanbu aan de strijdkrachten van sjerief Hoessein", "e291c816"], "d": ["De opstand die sjerief Hoessein in juni begon, verspreidde zich naar de kust van de Rode Zee; Yanbu, de haven van Medina, kwam met steun van de Britse vloot in handen van de rebellen. De haven werd de hoofdpoort van de stroom wapens en geld die van buiten naar de opstand ging. Zo werd de zeeverbinding van de strijdkrachten van Fahreddin Pasja in Medina afgesneden en bleef de stad alleen achter aan het uiteinde van de Hidjaz-spoorlijn.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Derde Slag bij Gaza — verlies van Gaza en Khan Yunis", "c142a069"], "d": ["Na twee mislukte pogingen doorbrak Allenby in zijn derde offensief het front door Beersheba heen te omtrekken en stortte de zes maanden gehouden Gaza-lijn in. Gaza en Khan Yunis ten zuiden ervan werden op dezelfde dag ontruimd. Deze doorbraak was het begin van de ineenstorting van het Palestijnse front; Jeruzalem zou vijf weken later vallen.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Bezetting van Gümülcine — verlies van West-Thracië", "904d813c"], "d": ["West-Thracië, dat na Moudros eerst onder controle van de Entente-eenheden kwam, werd met het besluit van de Conferentie van San Remo aan Griekenland gelaten en het Griekse leger trok Gümülcine binnen. De regio, die in 1913 op Bulgarije was teruggenomen, werd het laatste gebied dat het rijk in Rumelië verloor. De status van de Turkse bevolking in de regio zou drie jaar later in Lausanne met een minderhedenregime worden geregeld. Met deze bezetting gingen de kazas Gümülcine, İskeçe, Dedeağaç en Sofulu van West-Thracië naar Griekenland.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Ineenstorting van de staat der Ilkhans: dood van Abu Sa'id Bahadur Khan", "0f187469"], "d": ["Volgens het TDV-lemma İlhanlılar leidde het overlijden van Abu Sa'id zonder erfgenaam te laten tot het uiteenvallen van de Ilkhanidische staat die al een eeuw over Iran heerste; de emirs maakten gebruik van de troonstrijd en stichtten lokale dynastieën zoals de Jalayiriden, Kara Koyunlu, Muzaffariden, Sarbadars van Khorasan en Eretnaoğulları. Deze versplintering verdeelde de regio in een mozaïek van beyliks dat een eeuw zou duren; uiteindelijk zouden zij door de veldtochten van Timur opnieuw worden verenigd.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Timur bracht het grootste deel van Iran onder zijn heerschappij", "1cee2b82"], "d": ["Volgens het TDV-lemma Timur bracht Timur, die vanaf het begin van de jaren 1380 de post-Ilkhanidische lokale dynastieën zoals de Sarbadars, Kerts en Muzaffariden een voor een liquideerde, tijdens de 'driejarige veldtocht' van 1386-1388 het grootste deel van Iran feitelijk onder zijn heerschappij; het definitieve einde van de Muzaffariden-dynastie zou in 1393 volgen. De regio werd zo na een eeuw versplintering opnieuw aan één centraal gezag gebonden.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Overwinning aan de Aras: Kara Yusuf versloeg de Timoeride Abu Bakr Mirza", "4b61a75a"], "d": ["Na de dood van Timur in 1405 versloeg de Kara Koyunlu-bey Kara Yusuf, die uit ballingschap was teruggekeerd, nadat hij Avnik had ingenomen en zijn gebieden in Oost-Anatolië had hervonden, Abu Bakr Mirza, Timurs kleinzoon, die werd beschouwd als heer van Azerbeidzjan en de twee Irak's, aan de oever van de Aras. Deze overwinning gaf Tabriz niet aan de Kara Koyunlu: TDV `tebriz` schrijft dat de stad in 1408 in handen van Abu Bakr Mirza was; de slag die Azerbeidzjan opleverde is die van Sardrud op 13 april 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Overwinning bij Sardrud: Tabriz en Azerbeidzjan gingen naar de Kara Koyunlu", "1f0a429d"], "d": ["Kara Yusuf versloeg de Timoeride Abu Bakr Mirza na de Aras voor de tweede keer bij Sardrud bij Tabriz; deze overwinning leverde Azerbeidzjan op voor de Kara Koyunlu. Kara Yusuf gaf daarna Bistam Bey de opdracht Irak-i Acem te veroveren;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Pestepidemie in Constantinopel en verhuizing van het paleis naar Edirne", "70c7a163"], "d": ["Volgens het TDV-lemma İstanbul legde de snelle en intensieve vestiging in de stad periodiek de bodem voor de verspreiding van epidemieën; tijdens de pestepidemie van 1466 trokken het paleis en de staatsnotabelen tijdelijk naar Edirne. De bevolking van de stad leed bij dergelijke epidemieën ernstige verliezen.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Uzun Hasan maakte een einde aan de staat Kara Koyunlu", "ef68399e"], "d": ["Volgens het TDV-lemma Uzun Hasan versloeg en doodde de Akkoyunlu-heerser Uzun Hasan de Kara Koyunlu-heerser Jahan Shah op 12 Rabi' al-akhir 872 / 10 november 1467 in de streek Bingöl-Sancak; Jahan Shah's zoon Hasan Ali werd in september 1468 bij Marand verslagen en in april-mei 1469 voor Hamadan gedood, waarmee een definitief einde kwam aan de staat Kara Koyunlu. De gebieden gingen over naar Akkoyunlu-heerschappij; de staat zou zich in het volgende decennium uitbreiden tot diep in Iran.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Opening van de Sahn-ı Semân-madrasa's voor onderwijs", "021f2a83"], "d": ["Volgens het TDV-lemma Sahn-ı Semân werden deze acht madrasa's, gesticht binnen het Fatih-complex, ontworpen als de hoogste onderwijsinstelling van die tijd en vormden zij de top van de Osmaanse ilmiye-hiërarchie. Het müderrisschap en afstuderen hier gold in de volgende eeuwen als de meest aanzienlijke sport in de loopbaan van kadi en müderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Voltooiing van het Topkapı-paleis (Saray-ı Cedîd)", "d2db6323"], "d": ["Volgens het TDV-lemma Topkapı Sarayı lopen de bronnen van die tijd uiteen over het begin- en einddatum van de bouw; volgens de datum 883 (1478) op het opschrift van de Bâb-ı Hümâyun was de bouw, die waarschijnlijk in 1465 op bevel van de Veroveraar begon, in dit jaar grotendeels voltooid en nam het paleis de plaats van het staatscentrum in het oude paleis over. Zo verhuisde de sultan naar zijn nieuwe verblijf, dat drie eeuwen lang het bestuurlijke en ceremoniële hart van de staat zou zijn.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Troonsbestijging van Bayezid II in Constantinopel", "9b686d04"], "d": ["Volgens het TDV-lemma Bayezid II kwam prins Bayezid, die sandjakbey van Amasya was, na het nieuws van de dood van zijn vader snel naar Constantinopel en besteeg de troon; hij liet het vertrek van zijn broer Cem uit Konya met steun van de janitsaren achter zich. Tijdens de troonsbestijging werd aan de janitsaren de gebruikelijke troonsbestijgingsfooi uitgedeeld. Deze troonswisseling ontstak ook de lont van de strijd tussen de twee broers.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan riep zich in Bursa uit tot sultan", "b355168a"], "d": ["Volgens het TDV-lemma Cem Sultan nam Cem, die via Karaman Bursa had bereikt, de stad in, riep zich uit tot sultan en liet de khutba lezen. Dit korte sultanaat eindigde toen de strijdkrachten die zijn oudere broer Bayezid II zond, Cem bij Yenişehir versloegen. Na de nederlaag moest Cem naar Egypte vluchten.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Executie van Gedik Ahmed Pasja", "6d75a58c"], "d": ["Volgens het TDV-lemma Gedik Ahmed Paşa werd de pasja, bekend om de veldtocht naar Otranto en zijn grootvizierschap, op bevel van Bayezid II in Edirne geëxecuteerd vanwege zijn houding in de kwestie-Cem en de zorg over zijn invloed. De dood van een van de meest ervaren commandanten uit de tijd van de Veroveraar wekte in het paleis grote weerklank.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Oprichting van de eerste drukkerij in Constantinopel", "04475930"], "d": ["Volgens het TDV-lemma Matbaa stichtten de uit Spanje gekomen Joodse migranten, de broers David en Samuel ibn Nahmias, in Constantinopel de eerste drukkerij die met Hebreeuwse letters drukte. Dit werd opgetekend als de eerste drukkerijonderneming die op Osmaans grondgebied actief was; drukken in Turks met Arabische letters zou pas veel later, in de 18e eeuw, mogelijk zijn.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Sjah Ismail nam Tabriz in: stichting van de Safawidische staat", "014d81e6"], "d": ["Volgens de TDV-lemma's Safevîler en Akkoyunlular bracht İsmail, de jonge sjeik van de tekke van Ardabil, met het leger dat hij had gevormd uit de Kızılbaş-murids in Anatolië, de Akkoyunlu-sultan Alvand in de streek Nachitsjevan een zware nederlaag toe; Alvand vluchtte naar Diyarbakır, İsmail trok Tabriz binnen en besteeg de troon en riep het twaalver-sjiisme uit tot officiële geloofsrichting. Zo kwam een einde aan zowel de Akkoyunlu-heerschappij als aan het tijdperk van de post-Ilkhanidische beyliks in de regio; de Safawidische staat, die drie eeuwen zou duren, werd gesticht.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Aardbeving 'Kleine Dag des Oordeels' in Constantinopel", "53e3b1d6"], "d": ["Volgens het TDV-lemma İstanbul werd de hevige aardbeving die de stad trof onder de bevolking 'Kleine Dag des Oordeels' genoemd; er ontstond zware schade aan muren, moskeeën en vele gebouwen en er vielen veel doden. Op bevel van Bayezid II werd in de stad een grootschalige herstel- en wederopbouwmobilisatie gestart.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Begin van de opstand van Şahkulu", "3d9a4a90"], "d": ["Volgens het TDV-lemma Şahkulu Baba Tekeli bracht Şahkulu, gevoed door Safawidische propaganda, in de streek Teke een brede Turkmeense massa om zich heen en begon een grote opstand van religieus-maatschappelijke aard. De opstand schokte als een van de ernstigste interne veiligheidscrises van die tijd het centrale gezag van de staat diepgaand.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Overlijden van Bayezid II op weg naar Dimetoka", "c46e98c9"], "d": ["De voormalige sultan, die na zijn troonsafstand Constantinopel verliet om naar zijn geboortestad Dimetoka te gaan, werd onder het reizen in zijn draagstoel, waarmee hij slechts 5-6 km per dag kon afleggen, onwel in het dorp Abalar bij Çorlu en stierf op 25 Rabi' al-awwal 918 (10 juni 1512). Het TDV-lemma vindt de doodsoorzaak zeer verdacht; volgens sommige binnenlandse en buitenlandse bronnen wordt de mogelijkheid benadrukt dat hij vergiftigd was. Na een regering van eenendertig jaar stierf zo de achtste sultan uit de lijn van Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Executie van prins Ahmed op bevel van Yavuz Selim", "65abb2f2"], "d": ["Volgens het TDV-lemma Selim I werd prins Ahmed, de favoriet van zijn vader Bayezid II en de eigenlijke rivaal voor de troon, in de strijd die hij na de troonsbestijging van zijn broer Selim voerde, verslagen op de vlakte van Yenişehir en tijdens zijn vlucht van het slagveld gevangengenomen en gedood. Met dit voorval maakte Selim grotendeels een einde aan de troonrivaliteit onder zijn broers en neven.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Pasja tot grootvizier benoemd", "9c94c1e3"], "d": ["Volgens het TDV-lemma İbrâhîm Paşa, Makbul werd İbrahim Pasja, die van has odabaşı tot beylerbey van Rumelië en op dezelfde dag tot grootvizier werd verheven, op 13 Sha'ban 929 (27 juni 1523) grootvizier. Dit was een ongekende benoeming rechtstreeks van paleisdienst naar het grootvizierschap en toonde de buitengewone nabijheid van İbrahim Pasja tot Süleyman.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Pasja tot kapudan pasja benoemd", "a0ff6bab"], "d": ["Volgens het TDV-lemma Barbaros Hayreddin Paşa werd Hayreddin Pasja, bekend om zijn successen in Algiers, op 6 april 1534 naar Constantinopel geroepen en benoemd tot kapudan pasja en beylerbey van Cezâyir-i Bahr-i Sefîd. Deze benoeming wordt beschouwd als het begin van de herstructurering van de Osmaanse vloot en de institutionalisering van de zeemacht in de Middellandse Zee.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pasja werd voor het eerst grootvizier", "ddfcc014"], "d": ["Volgens het TDV-lemma Rüstem Paşa werd Rüstem Pasja op 17 Ramadan 951 (2 december 1544) tot grootvizier benoemd, nadat Hadım Süleyman Pasja was ontslagen na een geschil met een vizier. Rüstem Pasja, die dankzij zijn huwelijk met Mihrimah Sultan dichter bij het paleis stond, werd met dit ambt een van de invloedrijkste staatslieden uit de tijd van Süleyman.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi werd sjeik-ul-islam", "11ed04f8"], "d": ["Volgens het TDV-lemma Ebüssuûd Efendi werd Ebüssuûd Efendi, die acht jaar kazasker van Rumelië was geweest, in Sha'ban 952 (oktober 1545) tot sjeik-ul-islam benoemd en bleef in dit ambt achtentwintig jaar en elf maanden. Ebüssuûd Efendi, bekend om zijn fatwa's die de kanunnames van Süleyman in overeenstemming brachten met het sharia-recht, speelde een bepalende rol bij de vormgeving van de rechts- en onderwijsinstellingen van zijn tijd.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Overlijden van Barbaros Hayreddin Pasja", "3378a0bf"], "d": ["Volgens het TDV-lemma Barbaros Hayreddin Paşa stierf hij na een korte ziekte op 6 Jumada al-awwal 953 (5 juli 1546) in Constantinopel. De dood van Barbarossa, die werd begraven in het mausoleum naast de door hemzelf gebouwde madrasa in Beşiktaş, werd gezien als het sluiten van een tijdperk in de Middellandse Zee-suprematie die de Osmaanse vloot had gevestigd.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Begin van de bouw van de Süleymaniye-moskee en het complex", "101ec36f"], "d": ["Volgens het TDV-lemma Süleymaniye Camii ve Külliyesi werd het complex, waarvan in 1550 onder leiding van hoofdarchitect Sinan de fundamenten werden gelegd, ontworpen als een groot sociaal complex dat naast de moskee uit madrasa's, een ziekenhuis, een imaret en een bibliotheek bestond. De bouw was een van de grootste bouwprogramma's die de macht van de regering van Süleyman en de wederopbouw van Constantinopel symboliseerden.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Nieuwe pestgolf begon in Constantinopel en omgeving", "547d6bf6"], "d": ["Volgens het TDV-lemma Tâun vond een van de epidemieën van de 16e eeuw die de islamitische wereld troffen plaats tussen 1552 en 1566 en was vooral werkzaam in Constantinopel, Anatolië, Rumelië, Egypte en Noord-Afrika. De uitbreidende handelsroutes en toegenomen bevolkingsbeweeglijkheid worden gerekend tot de factoren die in de sterkste periode van het rijk de verspreiding van epidemieën vergemakkelijkten.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pasja tot grootvizier benoemd", "a7d7748e"], "d": ["Volgens het TDV-lemma Kara Ahmed Paşa werd Kara Ahmed Pasja, die als tweede vizier diende, op 27 Shawwal 960 (5 oktober 1553) tot grootvizier verheven nadat de zittende grootvizier plotseling was ontslagen. Deze verandering wijst op een periode, vallend in dezelfde dagen als de executie van prins Mustafa, waarin de machtsevenwichten binnen het paleis snel van hand wisselden.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Kapudan pasja Pîrî Reis geëxecuteerd", "3b2ad7a0"], "d": ["Volgens het TDV-lemma Pîrî Reis werd de beroemde zeevaarder en cartograaf, toen de beschuldigingen Egypte bereikten dat hij bij het opheffen van het beleg van Hormuz tegen omkoping de bezittingen van moslims had geplunderd en zijn leger op het slagveld had verlaten, eind 960 (eind 1553) in Caïro geëxecuteerd. De dood van Pîrî Reis, wiens vermogen in beslag werd genomen, wordt beschouwd als een gevolg van de rivaliteit tussen pasja's in de zeepolitiek van Basra en de Indische Oceaan in die tijd.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pasja geëxecuteerd, Rüstem Pasja opnieuw grootvizier", "9a85076a"], "d": ["Volgens de TDV-lemma's Rüstem Paşa en Kara Ahmed Paşa werd Rüstem Pasja, met steun van Hürrem en Mihrimah Sultan, op dezelfde dag voor de tweede keer tot grootvizier benoemd in plaats van Kara Ahmed Pasja, die op 13 Dhu al-Qa'da 962 (29 september 1555) plotseling werd geëxecuteerd tijdens een divanzitting. De achtergrond van het voorval is in de bronnen open gelaten en wordt beoordeeld als het gevolg van paleisintriges.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Overlijden van Hürrem Sultan", "1ae998b5"], "d": ["Volgens het TDV-lemma Hürrem Sultan stierf Hürrem Sultan, die als haseki sultan van Süleyman jarenlang grote invloed in het paleis had, op 26 Jumada al-akhira 965 (15 april 1558) in Constantinopel en werd begraven in haar mausoleum in het complex van de Süleymaniye-moskee. De dood van Hürrem Sultan, die na de dood van valide sultan Hafsa in 1534 haar gezag over de harem versterkte, nam ook het evenwichtsbrengende effect weg dat de troonrivaliteit tussen haar zonen Bayezid en Selim in toom hield.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Pasja werd grootvizier", "896391a2"], "d": ["Volgens het TDV-lemma Sokollu Mehmed Paşa werd Sokollu Mehmed Pasja, die grootvizier werd na de dood van Semiz Ali Pasja op 30 Dhu al-Qa'da 972 (29 juni 1565), de laatste grootvizier van Süleyman en bleef in dit ambt onder Selim II en Murad III, waarmee hij een van de langstzittende grootviziers uit de Osmaanse geschiedenis werd.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II bereikte Constantinopel en besteeg de troon", "0289ef97"], "d": ["Na de dood van Süleyman de Wetgever bij Szigetvár werd het nieuws door Sokollu Mehmed Pasja weken geheim gehouden om de orde niet te verstoren. Volgens het TDV-lemma geeft Selânikî de datum van Selims aankomst in Constantinopel als 15 Rabi' al-awwal 974 (30 september 1566), terwijl de meeste hedendaagse historici 9 Rabi' al-awwal (24 september) als juist beschouwen. De dood van Süleyman werd pas op 24-25 oktober 1566 in Belgrado officieel bekendgemaakt.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["De door Kılıç Ali Pasja herbouwde vloot werd te water gelaten", "d0fc9f48"], "d": ["Na de zware nederlaag bij Lepanto (7 oktober 1571) werden de hele winter door scheepswerven schepen gebouwd. Volgens het TDV-lemma werd op 1 Safar 980 (13 juni 1572) een nieuwe vloot van 250 galeien en ongeveer 300 galeien met vrijwillige roeiers in een machtsvertoon te water gelaten.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pasja werd vermoord bij een aanslag", "6ffa8dec"], "d": ["Sokollu Mehmed Pasja, die veertien jaar lang grootvizier onder drie sultans was geweest, werd op 20 Sha'ban 987 (12 oktober 1579) in de middagdivan in zijn herenhuis doodgestoken door een derwisj die naderde alsof hij een verzoekschrift wilde indienen. Volgens het TDV-lemma wordt besproken dat de aanslag verband kan hebben gehouden met de wraak voor de geëxecuteerde Hamzawiyya-sjeik Hamza Bâlî.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Eerste handelsahidname met Engeland — capitulaties aan de Engelsen verleend", "59c8e3ee"], "d": ["De Engelse vertegenwoordiger William Harborne, die in oktober 1578 naar Constantinopel was gezonden, verkreeg met steun van Sokollu Mehmed Pasja en Hoca Sâdeddin Efendi van Murad III een ahidname van 1580. Met deze ahidname kregen de Engelse kooplieden het recht in dezelfde mate te profiteren van de handelsprivileges (capitulaties) die eerder aan de Fransen en Venetianen waren verleend. Tussen koningin Elizabeth I en Murad III werden brieven gewisseld en tussen de twee staten werd ook een officiële betrekking gevestigd. Onmiddellijk na deze privileges werd in 1581 in Londen de Levant Company opgericht; de Engelsen dreven hun handel in de regio via deze maatschappij tot 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Sterrenwacht van Constantinopel op bevel (hatt-ı hümâyun) afgebroken", "3bc0c78c"], "d": ["Onder invloed van de fatwa dat sterrenwachten ongeluk over landen brengen en de oppositie in het paleis, werd de Sterrenwacht van Constantinopel met een hatt-ı hümâyun van 4 Dhu al-Hijja 987 (22 januari 1580) met al haar instrumenten afgebroken. Volgens het TDV-lemma was dit het korte einde van de door Takiyyüddin er-Râsıd gestichte instelling.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Begin van het besnijdenisfeest van prins Mehmed op het Atmeydanı", "c2926d5d"], "d": ["Prins Mehmed, zoon van Murad III, werd besneden met luisterrijke ceremonies die op 6 Jumada al-awwal 990 (29 mei 1582) begonnen en zesenvijftig-zevenenvijftig dagen duurden. Volgens het TDV-lemma behoorden de festiviteiten die op het Atmeydanı werden gehouden tot de meest grootse paleisvieringen van hun tijd.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Overlijden van Nurbanu Valide Sultan", "77d0a577"], "d": ["Nurbanu Sultan, de moeder van Murad III, stierf op 22 Dhu al-Qa'da 991 (7 december 1583). Volgens het TDV-lemma voerde zij als valide sultan briefwisseling met de hoven van Venetië en Frankrijk en had de Venetiaanse senaat in hetzelfde jaar ingestemd haar als beloning voor haar diensten een geschenk ter waarde van 2000 Venetiaanse gouden munten te sturen.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Door verslechterde akçe brak het incident van de Beylerbeyi uit", "db2f2e61"], "d": ["Toen de staat betalingen deed door het zilvergehalte van de akçe te verlagen, omsingelden de sipahi's en janitsaren het paleis en veroorzaakten een bloedige opstand die als het Beylerbeyi-incident de geschiedenis inging. Volgens het TDV-lemma Abdülkadir Şeyhî Efendi werd de sjeik-ul-islam naar aanleiding van dit voorval afgezet.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III besteeg de troon, negentien prinsen gewurgd", "2cd9a8c5"], "d": ["Mehmed III bereikte na de dood van zijn vader Murad III op vrijdag 16 Jumada al-awwal 1003 (27 januari 1595) Constantinopel en besteeg de troon. Volgens het TDV-lemma werden in dezelfde nacht negentien prinsen, onder wie vier volwassenen (Mustafa, Bayezid, Osman en Abdullah), gewurgd; dit was de grootste broedermoord uit de Osmaanse geschiedenis.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan kreeg invloed als valide sultan", "000bec21"], "d": ["Safiye Sultan, de vrouw van Murad III en de moeder van Mehmed III, steeg met de troonsbestijging van haar zoon op tot een beslissende positie in de paleispolitiek in de hoedanigheid van valide sultan. Volgens het TDV-lemma bereikte de uit de harem voortkomende invloed in deze periode de omvang van rechtstreekse inmenging in staatszaken.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III trok onder druk van de janitsaren persoonlijk ten strijde", "d3c50656"], "d": ["Ondanks het verzet van grootvizier Damad İbrahim Pasja trok Mehmed III, onder druk van de janitsaren, op 20 juni 1596 als eerste sultan na Süleyman de Wetgever persoonlijk aan het hoofd van het leger ten strijde uit Constantinopel. Volgens het TDV-lemma betekende dit de heropleving van de oude ghaza-traditie.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["De in de jaren 1570 begonnen pestepidemie bleef Constantinopel treffen", "eb4ca37a"], "d": ["Volgens het TDV-lemma Tâun hield de in de jaren 1570 begonnen epidemie tot het begin van de 17e eeuw haar effect en trof zij vooral Constantinopel, Anatolië, de Balkan, Egypte en Noord-Afrika. De epidemieperioden vormden een chronische dreiging die het paleis- en stadsleven vaak onderbrak.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim stierf, de opstandsbeweging verzwakte", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, die zich gewond terugtrok na de zware nederlaag die hij op 12 augustus 1601 bij Sepetli bij Elbistan leed, stierf in het jaar 1010 (1602). Volgens het TDV-lemma bereikte het nieuws van zijn dood Constantinopel in Ramadan van het jaar 1010 (februari-maart 1602); de bronnen vermelden dat het omstreden is of zijn dood het gevolg was van de wond of door zijn eigen mannen werd bewerkstelligd.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Feitelijk einde van de traditie van broedermoord", "9046c607"], "d": ["Bij zijn troonsbestijging liet Ahmed I, anders dan de voorgaande sultans, zijn broer prins Mustafa niet doden maar schonk hem het leven; dit besluit wordt beschouwd als het begin van de feitelijke aanvaarding van het ekber-erşed-stelsel in het Osmaanse opvolgingsstelsel. Het TDV-lemma 'Mustafa I' vermeldt dat Mustafa vanaf deze datum een leven in het paleis leidde. De praktijk maakte feitelijk een einde aan de eeuwenoude moorden bij troonsbestijging.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Eerste steen van de Sultan Ahmed-moskee gelegd", "1683262f"], "d": ["Op bevel van Ahmed I werd op het Atmeydanı in een ceremonie de eerste steen gelegd van de moskee die zou worden gebouwd door architect Sedefkâr Mehmed Ağa. Volgens het TDV-lemma 'Sultan Ahmed Camii ve Külliyesi' werd het gebouw, als eerste grote sultansmoskee die zonder een veroveringsoverwinning rechtstreeks uit de schatkist werd gebouwd, ook het onderwerp van kritiek van zijn tijd. Het complex werd ontworpen met naast de moskee ook een madrasa, imaret en mausoleum.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Moord op Jonge Osman door de janitsaren (Hâile-i Osmâniye)", "324f6582"], "d": ["Janitsaren en sipahi's die in opstand kwamen bij de geruchten dat hij onder het voorwendsel van de hadj Constantinopel zou verlaten en het janitsarenkorps wilde opheffen, zetten Osman II af en lieten hem in de kerkers van Yedikule wurgen. Volgens het TDV-lemma 'Osman II' is dit voorval het eerste geval in de Osmaanse geschiedenis waarin een sultan openlijk door een militaire opstand werd vermoord en het veroorzaakte een diepe breuk in de verhouding tussen dynastie en leger. Zijn laatste uren verliepen als volgt: toen zijn poging om onderdak te zoeken in het herenhuis van janitsarenagha Ali Ağa niets opleverde, werd de sultan, in de woorden van de TDV 'op ellendige wijze, met onbedekt hoofd, in een bedroevende staat' op een paard gezet en onder zware beledigingen eerst naar de Orta Cami, waar Mustafa I zich bevond, en in de namiddag van dezelfde dag naar Yedikule gebracht; volgens sommige historici werden zijn oor en neus afgesneden om zijn dood te bewijzen en aan de moeder van Mustafa I getoond. Na het voorval werd Mustafa I voor de tweede keer op de troon gezet. Het voorval, dat 'Hâile-i Osmâniye' (Osmaanse ramp) wordt genoemd, verstoorde het evenwicht tussen paleis en korps blijvend en startte legitimiteitsdiscussies die een eeuw zouden duren.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Mustafa I voor de tweede keer op de troon gezet", "34a0b29a"], "d": ["Na de moord op Jonge Osman door de janitsaren werd Mustafa I, omdat er geen andere volwassen mannelijke leden in de dynastie waren, voor de tweede keer op de troon gezet. Volgens het TDV-lemma 'Mustafa I' verliep ook dit tweede sultanaat, net als het eerste, zonder dat hij feitelijk de staatszaken kon uitvoeren en bleef het staatsbestuur in handen van de viziers en de valide sultan. Deze periode van veertien maanden eindigde in 1623 met de troonsbestijging van Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Brand van Cibali", "3e42fb08"], "d": ["De brand die in Cibali uitbrak en zich onder invloed van de wind snel verspreidde, legde een groot deel van Constantinopel in de as; volgens het TDV-lemma 'İstanbul' vermelden de bronnen van die tijd dat duizenden huizen verbrandden. Dat de brand in verband werd gebracht met de houten huizenstructuur en het roken van tabak, werd de directe reden voor het strenge tabaks- en koffiehuisverbod dat Murad IV kort daarna zou afkondigen. De ramp was slechts een van de terugkerende grote branden in het Constantinopel van die tijd.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Tabaks- en koffiehuisverbod van Murad IV", "5dd71297"], "d": ["Na de brand van Cibali verbood Murad IV uit zorg over brand en openbare orde het roken van tabak en de koffiehuizen; op overtreding van het verbod werden zware straffen, inclusief de doodstraf, toegepast. Volgens het TDV-lemma 'Murad IV' voerde de sultan een zo strikt intern disciplinebeleid dat hij zelf incognito door de straten van de stad liep om het verbod te controleren. Deze harde maatregelen worden beschouwd als onderdeel van de pogingen van Murad IV om het centrale gezag te herstellen.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Pestepidemie in Constantinopel", "f33f58c5"], "d": ["Onder Murad IV werd Constantinopel geschokt door een zware pestepidemie die een belangrijk deel van de bevolking trof; de handel in de stad en het dagelijks leven stokten maandenlang. Het TDV-lemma 'İstanbul' vermeldt dat de in de 17e eeuw terugkerende epidemieën het bevolkingsevenwicht van de stad ernstig beïnvloedden. Tijdens de epidemie verhuisden het paleis en de elite voor een tijd naar tuinen en paviljoens buiten de stad.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Gevleugelde vlucht van Hezarfen Ahmed Çelebi (overlevering)", "df474c04"], "d": ["Volgens de overlevering die Evliya Çelebi doorgeeft, slaagde Hezarfen Ahmed Çelebi erin met zelfgemaakte vleugels van de Galata-toren te springen en tot Üsküdar te zweven; hoewel de historische zekerheid omstreden is, werd het een symbool van technische verbeelding. De sultan, die Hezarfen aanvankelijk beloonde, verbande hem later naar aanleiding van de weerklank van het voorval naar Algiers.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi kreeg invloed in het paleis", "41d21572"], "d": ["Hüseyin Efendi, een uitdrijver die naar het paleis werd geroepen om de geestelijke nood van sultan İbrahim te behandelen, won snel het vertrouwen van de sultan en steeg op tot kazasker van Anatolië. Volgens het TDV-lemma 'Hüseyin Efendi, Cinci Hoca' gebruikte hij deze invloed om rijkdom te vergaren en in te grijpen in de politieke gebeurtenissen van die tijd. Na de dood van İbrahim werd hij van al zijn functies ontheven en in 1648 geëxecuteerd.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Executie van Kemankeş Mustafa Pasja", "0ecc8030"], "d": ["Kemankeş Mustafa Pasja, die sinds Murad IV grootvizier was en met zijn financiële hervormingen de schatkist een aanzienlijk overschot bezorgde, werd gewurgd en geëxecuteerd nadat zijn rivalen in het paleis İbrahim hadden beïnvloed en hij werd beschuldigd van het veroorzaken van een janitsarenopstand. Volgens het TDV-lemma 'Kemankeş Mustafa Paşa' vond zijn executie plaats op 21 Dhu al-Qa'da 1053 / 31 januari 1644: Kemankeş Kara Mustafa Pasja werd in de Hocapaşa-bazaar door beul Kara Ali gewurgd en begraven in zijn eigen mausoleum bij de Çarşıkapı. Zijn dood wordt vermeld als een treffend voorbeeld van de instabiliteit van het grootvizierschap van die tijd en maakte een einde aan de korte periode van strenge hervorming.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Besluit van de Divan tot de Kretenzische veldtocht en vertrek van de vloot", "9076827e"], "d": ["In de Divan-ı Hümayun werd besloten tot het openen van een grootschalige veldtocht tegen het aan Venetië toebehorende eiland Kreta en de Osmaanse vloot onder bevel van de kapudan pasja vertrok uit Constantinopel richting Kreta. Volgens het TDV-lemma 'Girit' vormde dit besluit het politieke begin van een lange periode van beleg en oorlog die ongeveer vijfentwintig jaar zou duren. Het openen van de veldtocht had onder de staatsnotabelen tot brede discussies geleid als het grootste buitenlandspolitieke initiatief uit de tijd van İbrahim.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Troonsbestijging van Mehmed IV op zevenjarige leeftijd", "a197a3bc"], "d": ["Onmiddellijk na de afzetting van İbrahim werd zijn nog zevenjarige zoon Mehmed op de troon gezet en werd sultan onder de titel Mehmed IV. Volgens het TDV-lemma 'Mehmed IV' deed een troonsbestijging op zo jonge leeftijd de machtsstrijd binnen het paleis tussen zijn grootmoeder Kösem Sultan en zijn moeder Turhan Sultan oplaaien. Deze machtsstrijd zou in 1651 uitmonden in de moord op Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Begrotingshervorming van Tarhuncu Ahmed Pasja", "376fc7f2"], "d": ["Grootvizier Tarhuncu Ahmed Pasja voerde, om de financiële crisis die de lange oorlogsjaren hadden veroorzaakt te boven te komen, een streng bezuinigingsprogramma uit dat ook de paleisuitgaven omvatte en stelde de eerste bekende sluitende begroting uit de Osmaanse geschiedenis (de tarhuncu-layiha) op. Volgens het TDV-lemma 'Tarhuncu Ahmed Paşa' leverde deze hervorming de schatkist een aanzienlijk overschot op, maar wekte brede ontevredenheid in de kringen rond het paleis en de hoge bureaucratie. Deze ontevredenheid zou een jaar later uitmonden in zijn executie.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Incident van de Plataan (Çınar Vak'ası)", "4c6ed90f"], "d": ["Volgens het TDV-lemma Çınar Vak'ası kwamen de janitsaren en sipahi's, die zonder betaling terugkeerden van de Kretenzische veldtocht, in opstand in Constantinopel en eisten de executie van de staatslieden die zij van corruptie beschuldigden. Het voorstel van grootvizier Zurnazen Mustafa Pasja tot verbeurdverklaring en verbanning werd niet aanvaard; eerst werden drie functionarissen en daarna bijna dertig staatslieden geëxecuteerd en hun lichamen werden opgehangen aan de platanen op het Sultanahmet-plein. Het voorval wordt daarom het Incident van de Plataan genoemd.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Benoeming van Köprülü Mehmed Pasja tot grootvizier onder voorwaarden", "3a6b7f8f"], "d": ["Volgens het TDV-lemma Köprülü Mehmed Paşa nam de bijna tachtigjarige Köprülü Mehmed Pasja het zegel pas aan nadat hij Valide Turhan Sultan en Mehmed IV zijn zware voorwaarden — geen inmenging in zijn benoemingen, geen geloof aan wat tegen hem werd gezegd — had laten aanvaarden. Hij begon op 26 Dhu al-Qa'da 1066 als opvolger van Boynueğri Mehmed Pasja en ging over tot het hard herstellen van de staatsdiscipline.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Neerslaging van de Kadızadeli-beweging door Köprülü Mehmed Pasja", "5ec3ce84"], "d": ["Volgens het TDV-lemma Kadızâdeliler pakte Köprülü Mehmed Pasja zodra hij aantrad het religieuze conflict aan tussen de kring rond Kadızâde Mehmed Efendi en de tarikat-aanhangers. Nadat hij de ulema had geraadpleegd, liet hij weliswaar een executiefirman uitvaardigen voor de leiders van de beweging Üstüvânî Mehmed Efendi, Türk Ahmed en Divâne Mustafa, maar deze straf werd omgezet in ballingschap en de drie werden naar Cyprus gezonden; zo eindigde de tweede fase van de beweging.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Grote brand in Constantinopel: afbranden van Ağakapısı", "b9253b66"], "d": ["Volgens het TDV-lemma Ağakapısı brandde bij de grote brand die in juli 1660 onder Mehmed IV uitbrak Ağakapısı, het officiële hoofdkwartier van de janitsarenagha, volledig af en werd daarna herbouwd. Deze brand was een van de grote stadsbranden die het Constantinopel van die tijd telkens troffen.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Benoeming van Köprülüzâde Fâzıl Ahmed Pasja tot grootvizier", "c1999b5c"], "d": ["Volgens het TDV-lemma Köprülüzâde Fâzıl Ahmed Paşa werd hij na de dood van zijn vader Köprülü Mehmed Pasja op 8 Rabi' al-awwal 1072 (1 november 1661) tot grootvizier benoemd. Fâzıl Ahmed Pasja, die in tegenstelling tot zijn vader bekendstond als zachtaardig, vroom en beschermheer van geleerden en kunstenaars, liet tijdens zijn grootvizierschap van meer dan vijftien jaar bibliotheken en liefdadigheidsinstellingen stichten in Constantinopel en de veroverde gebieden.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Benoeming van Vânî Mehmed Efendi tot prediker van de Yeni Cami en leraar van de sultan", "7ea6aaae"], "d": ["Volgens het TDV-lemma Mehmed Efendi, Vânî won Vânî Mehmed Efendi, die met het grootvizierschap van Köprülüzâde Fâzıl Ahmed Pasja naar Constantinopel was geroepen en aan Mehmed IV werd voorgesteld, snel de nauwe belangstelling van de sultan. In 1665 werd hij benoemd tot prediker van de Yeni Cami en leraar van de sultan en werd zo een van de invloedrijkste geestelijken van het paleis.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Benoeming van Merzifonlu Kara Mustafa Pasja tot grootvizier", "3d1e836c"], "d": ["Volgens het TDV-lemma Merzifonlu Kara Mustafa Paşa werd hij na de dood van Fâzıl Ahmed Pasja op 28 Sha'ban 1087 (5 november 1676) tot grootvizier benoemd. Merzifonlu, die als schoonzoon en leerling van de Köprülü-familie lange ervaring had in het staatsbestuur, werd een van de sterkste en invloedrijkste grootviziers van Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Overlijden van Vânî Mehmed Efendi in ballingschap", "cda714aa"], "d": ["Volgens het TDV-lemma Mehmed Efendi, Vânî werd Vânî Mehmed Efendi, die gold als een van de voornaamste personen die de sultan hadden overtuigd van de Wenen-veldtocht, na de uitkomst van de veldtocht in een nederlaag onder druk van de publieke opinie in ongenade gebracht en verbannen naar het stadje Kestel bij Bursa. Hij stierf hier op 14 Dhu al-Qa'da 1096 (12 oktober 1685) en werd begraven bij de ingang van de door hem gebouwde moskee.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Benoeming van Köprülüzâde Fâzıl Mustafa Pasja tot grootvizier en zijn financiële hervormingen", "b048570e"], "d": ["Volgens het TDV-lemma Köprülüzâde Fâzıl Mustafa Paşa herordende Fâzıl Mustafa Pasja, die op 11 Muharrem 1101 (25 oktober 1689) tot grootvizier werd benoemd, de wijze van inning van de jizya volgens de sharia, bestreed de inflatie van de mangır en versterkte de schatkist door middelen over te hevelen uit paleisinstellingen. Bovendien versterkte hij het provinciale bestuur met betrouwbare functionarissen en liet lokale raden instellen die op de centrale divan leken.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Inwerkingtreding van het mâlikâne-stelsel", "316b8426"], "d": ["Volgens het TDV-lemma Mâlikâne bracht de toename van de oorlogskosten en de afname van de inkomsten door gebiedsverlies in het laatste kwart van de 17e eeuw de schatkist in een zware financiële crisis. In het mâlikâne-stelsel dat in 1106 (1695) in werking trad, kregen de belastingpachters een levenslang vast belastingrecht, waarbij in plaats van kortetermijnuitbuiting een prikkel kwam om de productie te beschermen.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Troonsbestijging van Mustafa II", "b53656c7"], "d": ["Volgens het TDV-lemma Mustafa II riep Mustafa II, die op eenendertigjarige leeftijd de troon besteeg, zijn sultanaat uit zonder de goedkeuring van de grootvizier en de sjeik-ul-islam af te wachten; de zwaardomgordingsceremonie vond enkele dagen later plaats in de Eski Cami. De sultan, die de troon besteeg in een periode waarin na de nederlaag bij Wenen de oorlogen aan meerdere fronten voortduurden, werd de laatste sultan uit de Osmaanse geschiedenis die persoonlijk ten strijde trok.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Tweede benoeming van Feyzullah Efendi tot sjeik-ul-islam", "1cf14cff"], "d": ["Volgens het TDV-lemma Feyzullah Efendi, Seyyid werd hij na de troonsbestijging van Mustafa II op 11 Shawwal 1106 (25 mei 1695) voor de tweede keer tot sjeik-ul-islam benoemd. Zijn invloed op de sultan nam tijdens deze ambtsperiode van meer dan acht jaar steeds verder toe.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi plaatste zijn zonen in hoge functies en de ontstane reactie", "a6398280"], "d": ["Volgens het TDV-lemma Feyzullah Efendi, Seyyid verkreeg de sjeik-ul-islam van Mustafa II een ongekend firman waarin zijn zoon Fethullah Efendi na hem sjeik-ul-islam zou worden en plaatste hij zijn verwanten op jonge leeftijd in hoge ambten. Deze praktijken wekten brede ontevredenheid onder de ilmiye-klasse, de militairen en de bevolking van Constantinopel; samen met de geruchten dat de hoofdstad naar Edirne zou worden verplaatst bereidden zij de bodem voor het Edirne-incident van 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Begin van het Edirne-incident", "5a106458"], "d": ["Volgens het TDV-lemma 'Edirne Vak'ası' begon de beweging met de opstand van soldaten die hun soldij niet ontvingen en groeide al snel uit tot een brede opstand waaraan janitsaren, madrasa-studenten, handelaren en volk deelnamen. Het eigenlijke doel van de opstand was sjeik-ul-islam Feyzullah Efendi, die werd beschuldigd van overmatige inmenging in staatszaken. Een menigte van ongeveer 60.000 mensen marcheerde van Constantinopel naar Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Grootvizierschap van Nevşehirli Damad İbrahim Pasja", "8d627a6f"], "d": ["Volgens het TDV-lemma 'Damad İbrâhim Paşa, Nevşehirli' werd hij tijdens de lopende vredesonderhandelingen met Oostenrijk op 8 Jumada al-akhira 1130 (9 mei 1718) tot grootvizier benoemd en richtte zich zodra hij was benoemd op de onderhandelingen om de oorlog te beëindigen; twee maanden later werd het Verdrag van Passarowitz ondertekend (21 juli 1718). In de woorden van de TDV 'wilde hij zich bezighouden met sociale en financiële kwesties en verlangde hij naar een vredesperiode die de al jarenlang in nederlagen eindigende oorlogen zou doen vergeten'. Hij voerde hervormingen door in de financiën, verlaagde de soldij van de soldaten en creëerde een aanzienlijk overschot in de staatskas. Zijn grootvizierschap van twaalf jaar vormde het politieke kader van het tijdperk dat zijn naam draagt (het Tulpentijdperk).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Oprichting van het Tulumbacı-korps", "f58b0d97"], "d": ["Volgens het TDV-lemma 'Tulumbacı' droeg grootvizier Nevşehirli Damad İbrahim Pasja, naar aanleiding van het succes dat Gerçek Dâvud, die terugkeerde van de Morea-veldtocht van 1715, bij de branden in Constantinopel met de tulumba (brandspuit) toonde, hem op een officieel brandweerkorps op te richten. Het korps, in de Acemi Oğlanları-kazerne opgericht met zes officieren en vijftig manschappen, bereikte in 1724 150 en in 1755 461 man. Dâvud bleef tot zijn dood in 1733 aan het hoofd van het korps.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Ontvangst van Mehmed Efendi door Lodewijk XV", "0ff5b174"], "d": ["Volgens het TDV-lemma 'Yirmisekiz Çelebi Mehmed Efendi' werd de gezant in het Tuileries-paleis officieel ontvangen door de Franse koning Lodewijk XV en overhandigde hij de geschenken en de brief van Ahmed III. Tijdens zijn bezoek bezocht hij de paleizen van Versailles, Trianon en Marly, ziekenhuizen, sterrenwachten en fabrieken; wat hij zag legde hij met tekeningen vast.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Terugkeer van Mehmed Efendi naar Constantinopel", "a09a8bba"], "d": ["Volgens het TDV-lemma 'Yirmisekiz Çelebi Mehmed Efendi' beïnvloedden de waarnemingen van de gezant, die terugkeerde van een ambassade van een jaar in Parijs, de architectonische smaak van het Tulpentijdperk. Dat zijn zoon later samenwerkte met İbrahim Müteferrika, legde de basis voor de stichting van de eerste Turkse drukkerij, de meest blijvende erfenis van de ambassade.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Bouw van het Sa'dabad-paviljoen", "aec9c65e"], "d": ["Volgens het TDV-lemma 'Sâdâbâd' werd aan de oever van de Kağıthane-beek een uitgebreid amusements- en wandelcomplex gebouwd, bestaande uit paviljoenen, kanalen, fonteinen en kiosken, geïnspireerd door de Franse paleisarchitectuur. Sa'dabad, dat de meest geliefde amusementsplek van zijn tijd werd, werd vereeuwigd in de gedichten van de dichter Nedîm. Het complex werd tijdens de Opstand van Patrona Halil in 1730 grotendeels verwoest.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Russische strijdkrachten namen Derbent in: Kaspische veldtocht van Peter I", "c2b269f9"], "d": ["Terwijl de Safawidische staat door de Afghaanse invasie in interne verwarring raakte, trok de Russische tsaar Peter I ten strijde met het doel de Iraanse gebieden aan de Kaspische kust in te nemen; de kuststad Derbent gaf zich zonder noemenswaardig verzet over aan de Russische strijdkrachten. Volgens het TDV-lemma Derbend was deze bezetting het begin van een tijdelijke Russische heerschappij die dertien jaar zou duren; de Osmaanse staat richtte zich, gebruik makend van dezelfde verwarring, op het westelijke deel van de Kaukasus. Het leger was vanuit Astrachan over zee naar de baai van Agrakhan gegaan en was daar langs de kust over Tarku over land opgetrokken; de shamkhal van Tarku ontving Peter en kwam onder Russische onderwerping.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Afschaffing van het shamkhalaat van Tarku: Russisch rechtstreeks bestuur", "b0f029c6"], "d": ["De shamkhal van Tarku, Adil-Girey, die in 1722 Peter ontving en onder Russische onderwerping kwam, kwam in 1725 in opstand; Jeropkin verwoestte Tarku in de herfst van 1725, de shamkhal werd midden mei 1726 gearresteerd en verbannen en het shamkhalaat werd afgeschaft. Tarku en omgeving bleven tot het Verdrag van Ganja in 1735 onder rechtstreeks Russisch bestuur.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Toestemming aan İbrahim Müteferrika om een drukkerij te stichten", "0659dd0a"], "d": ["Volgens het TDV-lemma 'İbrâhim Müteferrika' werd met het firman van Ahmed III en de fatwa van sjeik-ul-islam Yenişehirli Abdullah Efendi toestemming gegeven voor de stichting van de eerste Turkse drukkerij. De drukkerij kwam in werking in de wijk Yavuzselim in Constantinopel. Müteferrika drukte tot zijn dood in 1747 zeventien werken in drieëntwintig delen.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Voltooiing van het eerste gedrukte boek, het Vankulu-woordenboek", "684700e8"], "d": ["Volgens het TDV-lemma 'İbrâhim Müteferrika' werd begin 1729 de Turkse vertaling van de Sihah al-Jawhari (het Vankulu-woordenboek), het eerste werk van de drukkerij, voltooid. Dit was het eerste boek dat op Osmaans grondgebied met Arabische letters werd gedrukt en geldt als het begin van de Turkse drukkunstgeschiedenis.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Executie van Nevşehirli Damad İbrahim Pasja", "50c64341"], "d": ["Volgens het TDV-lemma 'Damad İbrâhim Paşa, Nevşehirli' werd het lichaam van de grootvizier, die tijdens de Opstand van Patrona Halil in het paleis werd gedood, door de straten van Constantinopel gesleept en achtergelaten bij de Ahmed III-fontein op het Sultanahmet-plein. Zijn grootvizierschap van twaalf jaar en het Tulpentijdperk kwamen zo bloedig ten einde.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Troonsafstand van Ahmed III, troonsbestijging van Mahmud I", "a43f5d40"], "d": ["Volgens het TDV-lemma 'Mahmud I' deed Ahmed III, tegenover de druk van de opstandelingen, afstand van de troon nadat hij garanties voor zichzelf en zijn kinderen had gekregen en zette zijn neef prins Mahmud persoonlijk op de troon. Mahmud I, die de troon besteeg met het advies van zijn oom 'neem de staatszaken in eigen hand en vertrouw niemand', begon als eerste met het breken van de invloed van de opstandelingengroep die hem op de troon had gezet.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Hervorming van het artilleriekorps door Humbaracı Ahmed Pasja", "ea3a7c64"], "d": ["Volgens het TDV-lemma 'Humbaracı' begon de officier van Franse afkomst Ahmed Pasja, die zich tot de islam had bekeerd, onder grootvizier Hekimoğlu Ali Pasja met de hervorming van de bezoldigde humbaracı-organisatie naar Europese wijze. Hij vestigde een nieuwe structuur van 601 personen, rechtstreeks aan de grootvizier gebonden, met 300 bezoldigden en 301 timarhouders. Met de technologie van die tijd liet hij 100 mortieren en 50.000 kogels produceren.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Oprichting van de Hendesehâne (eerste voorbeeld van een ingenieursschool)", "a77ed1f3"], "d": ["Volgens het TDV-lemma 'Mahmud I' stichtte Humbaracı Ahmed Pasja in Üsküdar de Hendesehâne, ook Humbarahâne genoemd, en gaf aan de studenten die hij onder het paleispersoneel en de bostancı's selecteerde militair onderwijs gebaseerd op wiskunde en meetkunde. Deze instelling wordt beschouwd als het eerste voorbeeld van de ingenieursscholen die zich later zouden ontwikkelen.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Verdrag van Ganja: teruggave van Derbent en Bakoe aan Iran", "ff19d531"], "d": ["Rusland, dat tegenover de Osmaanse dreiging een bondgenootschap met Iran zocht, gaf de steden aan de Kaspische kust die het dertien jaar in handen had met het Verdrag van Ganja terug aan Iran onder bevel van Nadir Khan (die de titel sjah nog niet had aangenomen). Volgens het TDV-lemma Derbend was deze terugtrekking het gevolg van het feit dat Rusland in het zuiden niet aan twee fronten (Osmanen en Iran) tegelijk wilde strijden en versterkte het de militaire reputatie van Nadir, die enkele jaren later de weg naar de troon opende. Ook Tarki (Tarku) onder Russisch bestuur keerde met deze terugtrekking terug naar de Iraanse kant (op de kaart wordt de dag van Ganja gebruikt). Ook Salyan en Shabran onder Russisch bestuur keren met deze terugtrekking terug naar de Iraanse kant (een plaatsspecifieke dag staat niet in de bron, op de kaart wordt de dag van Ganja gebruikt — verklaarde benadering).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Troonsbestijging van Nadir Sjah op de Moghan-vlakte: feitelijk einde van de Safawidische dynastie", "4f640979"], "d": ["Volgens het TDV-lemma Nadir Şah verzocht de kurultai van ongeveer twintigduizend mensen die op de Moghan-vlakte bijeenkwam, hem dringend aan het hoofd van Iran te staan; Nadir aanvaardde dit voorstel onder de voorwaarde dat het extreme sjiitische denken dat de oorlogen tussen de Safawiden en de Osmanen had veroorzaakt, werd verlaten en de gematigde Ja'farietische rechtsschool werd aangenomen, en besteeg op 24 Shawwal 1148 (8 maart 1736) de troon met de titel Nadir Sjah. Dit betekende het feitelijke einde van de twee eeuwen durende Safawidische dynastie en de stichting van de Afsharid-dynastie.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Begin van de pestepidemie in Constantinopel", "9fa82b56"], "d": ["Volgens het TDV-lemma 'Tâun' trof de pestepidemie die tussen 1739 en 1743 in de islamitische wereld werkzaam was, in deze periode ook Constantinopel. Het lemma vermeldt dat de epidemieën van de 18e eeuw in vergelijking met voorgaande eeuwen relatief milder verliepen. Tot de epidemieperioden worden ook de jaren 1713, 1719, 1728-1729 en 1759-1765 gerekend.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Brand van Hocapaşa", "321c7d0d"], "d": ["Volgens het TDV-lemma 'Fatma Sultan Camii' verwoestte de 's nachts uitgebroken Hocapaşa-brand de Hoge Porte en omgeving; vermoedelijk raakte ook de Fatma Sultan-moskee in de regio bij deze brand beschadigd. Deze ramp, een van de grote branden die Constantinopel onder Osman III troffen, richtte zware schade aan in het handels- en bestuurscentrum van de stad.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Grootvizierschap van Koca Ragıp Mehmed Pasja", "a1846910"], "d": ["Ragıp Pasja, bekend als dichter en diplomaat, werd door Osman III tot grootvizier benoemd (hij bleef in functie bij de dood van Osman III in oktober 1757 en kreeg van Mustafa III een nieuw zegel). Terwijl de Zevenjarige Oorlog woedde, voerde hij een evenwichtig buitenlands beleid dat de Osmaanse staat buiten de Europese conflicten hield. Tijdens zijn grootvizierschap van zes jaar hechtte hij ook belang aan culturele activiteiten zoals het stichten van bibliotheken.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Overlijden van Ragıp Pasja", "6bc19323"], "d": ["Ragıp Pasja stierf na zijn grootvizierschap van zes jaar. Met zijn dood kwam een einde aan het langstdurende en evenwichtigste grootvizierschap uit de tijd van Mustafa III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Grote aardbeving van Constantinopel en instorting van de Fatih-moskee", "2475b4dc"], "d": ["Volgens het TDV-lemma 'Fâtih Camii ve Külliyesi' stortte bij de grote aardbeving van 1766 de hoofdkoepel van de moskee volledig in en raakten de muren zo beschadigd dat ze niet meer te herstellen waren. De wederopbouw, die in 1767 begon op bevel van Mustafa III onder leiding van de architecten Sarım İbrahim Efendi en İzzet Mehmed Bey, werd in 1771 voltooid met een nieuw ontwerp dat van het oude plan afweek.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Kortstondige poging tot een artillerieschool onder leiding van baron de Tott", "4192260c"], "d": ["Volgens het TDV-lemma 'Mühendishâne-i Bahrî-i Hümâyun' maakten de mislukkingen in de Osmaans-Russische oorlog van 1768 de behoefte aan technisch militair onderwijs duidelijk; de kortlevende artillerieschool die met bijdrage van de Franse officier baron de Tott werd geopend, kwam in oktober 1772 in werking maar bleef zonder effect. Deze poging wordt beschouwd als de voorloper van de in 1775 te stichten Mühendishâne-i Bahrî-i Hümâyun.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III besteeg de troon", "00d046d9"], "d": ["Na de dood van Abdülhamid I besteeg zijn neef Selim III de troon. Volgens het TDV-lemma Selim III liet de nieuwe sultan, die sinds zijn prinsentijd belangstelling had voor de hervorming van de Europese legers, kort na zijn troonsbestijging een ingrijpend vernieuwingsprogramma voorbereiden. Dit programma zou binnen enkele jaren bekendstaan als Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Voorbereiding van het hervormingsprogramma Nizâm-ı Cedîd begon", "eff78a68"], "d": ["Selim III liet een omvattend vernieuwingsprogramma voorbereiden aan de hand van de memories die hij van staatslieden en buitenlandse deskundigen had gevraagd. Volgens het TDV-lemma Nizâm-ı Cedîd bleef dit programma niet beperkt tot het stichten van een nieuw leger, maar groeide het uit tot een brede hervormingsbeweging die ook de financiën, het provinciale bestuur en de diplomatie omvatte. Het programma zou in de volgende vijftien jaar zowel voorstanders als tegenstanders vinden.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Permanente ambassades gevestigd in Europese hoofdsteden", "2e9dc8a1"], "d": ["Selim III zond voor het eerst in de geschiedenis van de Osmaanse staat permanente gezanten naar de grote Europese centra. Volgens het TDV-lemma Elçi gaf deze stap de Osmaanse diplomatie, die tot dan toe slechts met tijdelijke en eenmalige delegaties werd gevoerd, een permanente organisatie. De voornaamste taak van de nieuwe ambassades was Constantinopel regelmatig te informeren over de politieke en militaire ontwikkelingen in Europa.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Schatkist İrad-ı Cedîd gesticht", "ae5c8ce2"], "d": ["Om de kosten van het Nizâm-ı Cedîd-leger en het hervormingsprogramma te dekken werd een afzonderlijke schatkist gesticht. Volgens het TDV-lemma Esham behoorden tot de inkomsten van de nieuwe schatkist het rechtstreeks door de staat exploiteren van sommige mukataa's en het onder controle brengen van de verkoop van esham. Deze regeling was een poging om buiten het traditionele financiële stelsel een nieuwe bron te scheppen.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Opstand van Kabakçı Mustafa begon", "b98eee17"], "d": ["De ontevredenheid die zich tegen Nizâm-ı Cedîd had opgehoopt, brak los met de opstand van de yamak-soldaten onder leiding van Kabakçı Mustafa. Volgens het TDV-lemma Kabakçı İsyanı namen de opstandelingen binnen korte tijd de controle in Constantinopel over en eisten de hoofden van de staatslieden die voor Nizâm-ı Cedîd waren. De opstand mondde binnen enkele dagen uit in de afzetting van Selim III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III afgezet", "ff2c30ec"], "d": ["Onder druk van de opstand van Kabakçı Mustafa werd Selim III afgezet met een fatwa van de sjeik-ul-islam. Volgens het TDV-lemma Selim III was dit besluit het moment waarop de hervormingsperiode van achttien jaar feitelijk eindigde; ook het Nizâm-ı Cedîd-leger werd kort daarna opgeheven. Selim werd in het Topkapı-paleis onder bewaking gehouden.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV besteeg de troon", "8f1ac86c"], "d": ["Onmiddellijk na de afzetting van Selim III werd zijn neef Mustafa IV tot sultan uitgeroepen. Volgens het TDV-lemma Mustafa IV begon de nieuwe sultan zijn regering onder invloed van de anti-Nizâm-ı Cedîd-kringen die de opstand hadden gesteund. Deze korte periode werd een fase van instabiliteit waarin het centrale gezag sterk verzwakte.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasja trok met zijn leger Constantinopel binnen", "0cad3dea"], "d": ["Alemdar Mustafa Pasja, de ayan van Rusçuk, kwam met zijn leger voor Constantinopel met als doel Selim III weer op de troon te zetten. Volgens het TDV-lemma Alemdar Mustafa Paşa werd zijn intocht in de stad door Mustafa IV zelf ontvangen; maar binnen enkele dagen zou het machtsevenwicht in het paleis volledig veranderen. Deze intocht startte de keten van gebeurtenissen die zowel met de dood van Selim als met een nieuwe troonsbestijging eindigde.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III vermoord", "e452f5f6"], "d": ["Op de dag dat Alemdar Mustafa Pasja de Hoge Porte innam, werd Selim III op bevel van Mustafa IV in het paleis vermoord. Volgens het TDV-lemma Selim III was dit een besluit dat was genomen om een poging te voorkomen om een afgezette sultan weer op de troon te zetten. De dood van Selim eindigde dezelfde dag met de troonsbestijging van Mahmud.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II besteeg de troon", "661c1974"], "d": ["Na de moord op Selim III besteeg Mahmud, die het enige overgebleven mannelijke lid van de dynastie was, met steun van Alemdar Mustafa Pasja de troon. Volgens het TDV-lemma Mahmud II bracht de nieuwe sultan de eerste maanden van zijn regering door onder voogdij van Alemdar, die hem op de troon had gezet, en in zijn streven het evenwicht tussen de ayans en het centrum te herstellen. Deze periode werd het begin van het daarop volgende twintig jaar durende ingrijpende hervormingsproces.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Het Sekbân-ı Cedîd-leger gesticht", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasja liet in de plaats van het opgeheven Nizâm-ı Cedîd een nieuw leger met Europese uitrusting stichten. Volgens het TDV-lemma Sekbân-ı Cedîd werd deze strijdmacht van drie regimenten in de ogen van de janitsaren als een rechtstreekse dreiging gezien en na slechts enkele maanden na haar oprichting bij een janitsarenopstand uitgeschakeld.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Val van İbrail (Brăila) — eerste grote bres in de Donaulijn", "ee519321"], "d": ["In de Russische oorlog die in 1806 begon, werd de burcht İbrail aan de noordoever van de Donau belegerd en beschoten door Russische strijdkrachten onder bevel van graaf Kamenski. Binnen bevonden zich 4100 infanteristen, 1100 ruiters en 260 kanonnen; de burcht gaf zich wegens voedselgebrek over aan generaal Essen. Het noordelijk uiteinde van de Donau-verdedigingslinie was zo geopend.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Overgave van Rusçuk — ook de zuidoever van de Donau gaat verloren", "084062e8"], "d": ["Rusçuk bood weerstand aan het lange en bloedige beleg van het Russische leger onder bevel van graaf Kamenski; het gaf zich over onder de voorwaarde dat het garnizoen en de burgerbevolking de stad veilig mochten verlaten. De val van de sterkste burchtstad aan de zuidoever van de Donau keerde het verloop van de oorlog in het voordeel van Rusland.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Het Eşkinci-korps gesticht", "67c56759"], "d": ["Mahmud II liet een nieuwe eenheid stichten van soldaten die uit het janitsarenkorps werden gekozen en naar Europese wijze werden getraind. Volgens het TDV-lemma Eşkinci Ocağı begon de eenheid op 12 juni 1826 met de training, maar de janitsaren zagen dit als het einde van hun eigen korps. De opstand die drie dagen later uitbrak, maakte ook een einde aan het korte leven van het Eşkinci-korps.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["De Asâkir-i Mansûre-i Muhammediyye gesticht", "14b84a7e"], "d": ["Onmiddellijk na de afschaffing van het Janitsarenkorps liet Mahmud II in zijn plaats een nieuw regulier leger met opleiding naar Europese wijze stichten. Volgens het TDV-lemma Asâkir-i Mansûre-i Muhammediyye werd dit leger, anders dan de eerdere pogingen, met zijn rangorde, opleidingsprogramma en soldijstelsel een blijvende instelling. Het leger zou in de volgende jaren veranderen in het Nizamiye-leger van de Tanzimat-periode.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["De Bektashi-orde gesloten", "f7d9a367"], "d": ["Gelijktijdig met de afschaffing van het Janitsarenkorps werd ook de Bektashi-orde, die bekendstond om haar religieuze banden met het korps, verboden. Volgens het TDV-lemma Bektaşîlik werden sommige kleine tekke-sjeiks geëxecuteerd, terwijl de sjeik van de Hacı Bektaş-dergah naar Amasya werd verbannen en de tekkes aan Naqshbandi-bestuur werden overgedragen. De orde zette ondanks deze zware klap haar organisatie in het geheim voort.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Incident van de waaier — voorwendsel voor de bezetting", "e949001e"], "d": ["In de besprekingen die gespannen raakten doordat Frankrijks oude graanschuld aan Algiers niet werd betaald, sloeg Hussein Dey de Franse consul Deval met de waaier in zijn hand. Dit voorval, voortgekomen uit een schuldgeschil, werd het officiële voorwendsel voor de bezetting die drie jaar later zou beginnen.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Franse blokkade van de kust van Algiers — drie jaar durend beleg", "d0ba97a5"], "d": ["Na het incident van de waaier blokkeerde Frankrijk de kust van Algiers. De blokkade duurde drie jaar; de zeehandel en inkomstenbronnen van het ocak werden drooggelegd en het vermogen tot verzet werd uitgehold voordat de bezetting begon.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Verdrag van Turkmenchay: overgang van Revan en Talysh naar Rusland", "abffcfdb"], "d": ["Toen de Russisch-Iraanse oorlog van 1826-1828 eindigde met een zware nederlaag van Iran, werden met het Verdrag van Turkmenchay de khanaten Revan en Nachitsjevan en het gebied Talysh aan de Kaspische kust (Lankaran, Astara) aan Rusland gelaten; bovendien werd een zware oorlogsvergoeding opgelegd. Volgens het TDV-lemma Revan is dit verlies het moment waarop de Russisch-Iraanse grens in de Kaukasus werd getrokken zoals zij grotendeels tot op heden geldt, en het leidde ook tot de migratie van Armeense bevolking naar Revan. Met dit verdrag gingen het khanaat Revan (Echmiadzin, Iğdır, Norapat, Beri) en het khanaat Nachitsjevan (Julfa, Şerur) naar Rusland.", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Tweede val van İbrail — tsaar Nicolaas voor de burcht", "eb6a8741"], "d": ["İbrail, dat in 1812 aan de Osmanen was teruggegeven en in 1817-1818 opnieuw werd versterkt, werd in april belegerd met 4000 bewakers en 278 kanonnen binnen. De bewaker Ebûbekir Pasja vestigde een nieuwe verdedigingslinie; tsaar Nicolaas I kwam eind mei persoonlijk voor de burcht. De stad kwam onder Russische bezetting, maar zou met het Verdrag van Edirne worden teruggegeven en aan het vorstendom Walachije worden gelaten.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["De fez tot officiële hoofdbedekking uitgeroepen", "f55be4eb"], "d": ["Mahmud II maakte een ingrijpende verandering in de kleding van ambtenaren en soldaten en riep de fez in plaats van de tulband tot officiële hoofdbedekking uit. Volgens het TDV-lemma Fes werd dit besluit met een hatt-ı hümâyun bekendgemaakt en samen met de westers gerichte hervormingen van de Asâkir-i Mansûre-i Muhammediyye in praktijk gebracht. De verandering betekende ook het beëindigen van de traditionele kledinghiërarchie.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Ahıska aan Rusland gelaten — het centrum van de provincie Çıldır gaat verloren", "e2e00b2a"], "d": ["Ahıska (Akhaltsikhe), dat sinds de Slag bij Çıldır in 1578 onder Osmaans bestuur stond en het centrum van de provincie Çıldır vormde, werd met het Verdrag van Edirne, dat aan het einde van de oorlog van 1828-1829 werd ondertekend, aan Rusland gelaten. Het verlies van de stad wekte onder de bevolking diepe droefheid en werd het onderwerp van vele klaagliederen. Met deze gebeurtenis gingen Akhalkalaki, Zazalo en Ts'q'altbila (regio Akhaltsikhe–Akhalkalaki) naar Rusland.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Landing bij Sidi Ferruch — Frans leger op Algerijnse bodem", "33327553"], "d": ["Na de drie jaar durende blokkade zette het Franse landingsleger onder bevel van graaf de Bourmont soldaten aan land in de baai van Sidi Ferruch in het westen van Algiers. De strijdkrachten die naar de stad oprukten, doorbraken binnen drie weken de verdedigingslinie; op 4 juli viel het Keizersfort dat de stad beheerst en de volgende dag gaf Hussein Dey zich over.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Verbanning van Hussein Dey — feitelijk einde van het ocak van Algiers", "e122403b"], "d": ["Krachtens de overgavevoorwaarden werd de laatste dey van Algiers, Hussein, met zijn familie en schatkist uit de stad verwijderd en naar Napels gestuurd. Het bestuur van het ocak, dat in 1519 aan Selim I (Yavuz) was gebonden en driehonderd jaar lang de sterkste Osmaanse zeebasis in de Middellandse Zee was, kwam zo ten einde.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Terugtrekking van het Russische leger uit Walachije en Moldavië — einde van de zes jaar durende bezetting", "efdb0275"], "d": ["In de Osmaans-Russische oorlog van 1828-1829 hadden de Russen Walachije en Moldavië bezet en zich ook na het Verdrag van Edirne niet teruggetrokken totdat de oorlogsvergoeding was betaald. Toen de vergoeding in januari 1834 tot vijf miljoen werd verlaagd, ontruimden de Russische strijdkrachten de Memleketeyn en werden in de twee vorstendommen nieuwe woiwoden benoemd. De Osmaanse suzereiniteit keerde op papier terug, maar Rusland behield de invloed die het met het Règlement Organique had gevestigd.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["De Redif-i Asâkir-i Mansûre-organisatie gesticht", "15947493"], "d": ["Als reservemacht ter ondersteuning van de Asâkir-i Mansûre-i Muhammediyye werd de Redif-organisatie gesticht bij het reglement van 8 juli 1834. Volgens het TDV-lemma Redif werden onder bevel van seraskier Koca Hüsrev Pasja in de provinciale kazas bataljons van ongeveer veertienhonderd man gevormd. De organisatie was zo ontworpen dat zij, zonder permanent in dienst te worden genomen, ook de lokale veiligheid ondersteunde.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Het Ministerie van Buitenlandse Zaken gesticht", "750c6c7d"], "d": ["Mahmud II schafte het ambt van Reisülküttâb, dat de buitenlandse zaken behartigde, af en richtte in zijn plaats het Ministerie van Buitenlandse Zaken (Hariciye Nezareti) op. Volgens het TDV-lemma Hariciye Nezâreti werd Mehmed Âkif Pasja de eerste minister van het nieuwe ministerie en begon de organisatie haar werkzaamheden in het herenhuis van de ambassadeur in Wenen, Rıfat Bey. Deze regeling was het begin van het voeren van het Osmaanse buitenlands beleid volgens het beginsel van een modern ministerie.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["De Meclis-i Vâlâ-yı Ahkâm-ı Adliyye gesticht", "69db056e"], "d": ["Mahmud II liet de Meclis-i Vâlâ-yı Ahkâm-ı Adliyye stichten als hoge raad waarin de op te stellen wetten en reglementen zouden worden besproken. Volgens het TDV-lemma Meclis-i Vâlâ-yı Ahkâm-ı Adliyye begon de raad op 31 maart 1838 feitelijk te werken en werden bijna alle volgende Tanzimat-hervormingen via dit orgaan voorbereid en gecontroleerd. De instelling werd een van de belangrijkste centra van de moderne Osmaanse bureaucratie.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Overval bij Sinope", "5947e93f"], "d": ["De Russische Zwarte Zeevloot viel onder bevel van admiraal Nachimov de in de haven van Sinope voor anker liggende Osmaanse vloot zonder oorlogsverklaring aan; twaalf schepen zonken, meer dan tweeduizend soldaten sneuvelden als martelaar en de vlootcommandant Osman Pasja werd gevangengenomen. Volgens het TDV-lemma Sinop brandden bij de overval ook zeven moskeeën, twee scholen, 247 huizen en 170 winkels in de stad af en kwamen vijf moslimse en zestien christelijke burgers om. Het voorval, dat in de Europese publieke opinie als 'Ramp van Sinope' weerklank vond, werd de directe aanleiding voor Engeland en Frankrijk om binnen enkele maanden aan Osmaanse zijde in de oorlog te treden.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Tasvir-i Efkâr verscheen", "506c98e2"], "d": ["De door Şinasi uitgegeven Tasvir-i Efkâr begon als vierde Turkse krant te verschijnen na Takvîm-i Vekāyi', Cerîde-i Havâdis en Tercüman-ı Ahvâl. Volgens het TDV-lemma 'Tasvîr-i Efkâr' werd de krant onder het hoofdredacteurschap van Nâmık Kemal, dat hij later op zich nam, de spreekbuis van de Jonge Osmanen-beweging.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Genootschap van de Jonge Osmanen gesticht", "335fb02d"], "d": ["De Osmaanse intellectuelen die onder leiding van Mustafa Fâzıl Pasja naar Europa waren gevlucht, organiseerden zich met een reglement van dertien artikelen onder de naam Jong Turkije. Volgens het TDV-lemma 'Yeni Osmanlılar Cemiyeti' verspreidde de groep in Parijs, Londen en Genève met kranten als Muhbir en Hürriyet de eis voor een constitutioneel bestuur.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Şûrâ-yı Devlet gesticht", "b863b306"], "d": ["De Meclis-i Ahkâm-ı Adliyye werd in tweeën gesplitst en de Şûrâ-yı Devlet, die de administratieve zaken behandelde, en de Dîvân-ı Ahkâm-ı Adliyye, die de rechterlijke zaken behandelde, werden gesticht. Volgens het TDV-lemma 'Şûrâ-yı Devlet' werd Midhat Pasja de eerste voorzitter van de instelling, die naar het voorbeeld van de Franse Conseil d'État was gemodelleerd; het doel was de scheiding van wetgevende, uitvoerende en rechterlijke macht.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Irade voor de stichting van de Dârülfünun uitgevaardigd", "513704bf"], "d": ["Met het irade dat door grootvizier Âli Pasja en minister van Onderwijs Saffet Pasja werd voorbereid, werd de Dârülfünun formeel gesticht; de eerste lessen waren echter al in 1863 begonnen. Volgens het TDV-lemma 'Darülfünun' ging de instelling in februari 1870 onder directeur Hoca Tahsin Efendi feitelijk over tot onderwijs, met afdelingen voor filosofie-letteren, natuurwetenschappen en rechten.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Werkzaamheden aan de Mecelle-i Ahkâm-ı Adliyye begonnen", "8abdcbee"], "d": ["Het Mecelle-genootschap, opgericht onder voorzitterschap van Ahmed Cevdet Pasja, de voorzitter van de Dîvân-ı Ahkâm-ı Adliyye, begon met de voorbereiding van een burgerlijk wetboek op basis van de Hanafitische fiqh. Volgens het TDV-lemma 'Mecelle-i Ahkâm-ı Adliyye' werd het laatste deel van het werk, bestaande uit zestien boeken en 1851 artikelen, op 15 september 1876 voltooid en trad het in werking; het wordt beschouwd als de eerste gecodificeerde vorm van het islamitische recht.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["'Vaderland of Silistra' opgevoerd, Nâmık Kemal verbannen", "3861284c"], "d": ["Toen het patriottische toneelstuk van Nâmık Kemal in het Gedikpaşa-theater werd opgevoerd, stroomden de toeschouwers de straat op met de kreet 'Leve het vaderland, leve Kemal'. Volgens het TDV-lemma 'Nâmık Kemal' schrok de regering van deze demonstratie, sloot de krant İbret en verbande op 6 april 1873 Nâmık Kemal zonder proces naar Cyprus (Famagusta).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz stierf onder verdachte omstandigheden", "85816692"], "d": ["Abdülaziz, die na zijn afzetting op eigen verzoek naar het Feriye-paleis was overgebracht (1 juni 1876), werd op 4 juni in zijn kamer gevonden met doorgesneden polsaderen. Een commissie van negentien artsen, waaronder artsen van de ambassades, stelde een vaag geformuleerd rapport op; de dood werd op 6 juni in de kranten als zelfmoord aangekondigd. Het onderzoek dat Abdülhamid II liet instellen kwam echter tot de overtuiging dat de dood geen zelfmoord maar moord was en de verdachten werden in 1881 in het Yıldız-proces berecht; de kwestie is in de geschiedschrijving nog steeds omstreden.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Afzetting van Midhat Pasja als grootvizier en zijn verbanning", "b5247b06"], "d": ["Grootvizier Midhat Pasja, de architect van de Kanûn-ı Esâsî, werd zes weken na de afkondiging door Abdülhamid II ontslagen en in één nacht naar het buitenland verbannen. Volgens het TDV-lemma Midhat Paşa wordt de afzetting in verband gebracht met het ongenoegen van de sultan over de bepalingen in de grondwet die zijn eigen bevoegdheden beperkten. De pasja ging eerst naar Napels en daarna naar verschillende steden in Europa.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdulaziz b. Saud nam Riyad terug van de Rashidi's", "75eb8830"], "d": ["Abdulaziz, een jonge telg van de dynastie Saud die tien jaar eerder naar Koeweit was verbannen, overviel met een klein detachement Riyad, doodde de gouverneur-kaymakam van Al Rashid (Shammar) en nam de stad in. Volgens het TDV-lemma Riyad vergemakkelijkte de toenemende verzwakking van de Rashidi's en hun onvermogen versterkingen naar de stad te sturen het succes van deze overval; het voorval geldt als het moment van stichting van de Tweede Saoedische Staat, die in de volgende dertig jaar de kern van het huidige Saoedi-Arabië zou vormen.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Intocht van het Actieleger in Constantinopel", "41c8304c"], "d": ["Het Actieleger, dat uit Thessaloniki vertrok en grotendeels uit eenheden bestond die aan het Comité voor Eenheid en Vooruitgang waren gebonden, trok Constantinopel binnen om de opstand van 31 maart neer te slaan. Volgens het TDV-lemma Hareket Ordusu nam Mahmud Şevket Pasja het bevel op zich en was kolağası Mustafa Kemal chef-staf. Na korte gevechten werd de openbare orde in de stad hersteld.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Ontbinding van de laatste Osmaanse Meclis-i Mebusan", "2b709269"], "d": ["Nadat Constantinopel formeel door de Entente-strijdkrachten werd bezet en veel afgevaardigden werden gearresteerd, kon de Meclis-i Mebusan niet meer werken en werd zij met het irade van Mehmed VI formeel ontbonden. Volgens het TDV-lemma Meclis-i Mebusan symboliseerde deze ontbinding het feitelijke einde van de Osmaanse constitutionele parlementaire traditie. De sluiting versterkte de behoefte aan de bijeenkomst van een nieuwe nationale vergadering in Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Opening van de Grote Nationale Vergadering van Turkije", "6eab539d"], "d": ["Na de ontbinding van de Meclis-i Mebusan in Constantinopel kwamen de afgevaardigden in Ankara bijeen en openden de Grote Nationale Vergadering van Turkije; Mustafa Kemal Pasja werd tot voorzitter van de vergadering gekozen. Volgens het TDV-lemma Türkiye Büyük Millet Meclisi had de vergadering een buitengewoon karakter doordat zij zowel de wetgevende als de uitvoerende macht in zich verenigde. Deze opening was het keerpunt waarop het politieke en institutionele centrum van de Nationale Strijd naar Ankara verhuisde. Met deze gebeurtenis kwamen 124 plaatsen (de niet-bezette gebieden van Turkije), waaronder Konya, Sivas, Kayseri, Eskişehir, Erzurum, Trabzon, Samsun, Diyarbakır, Van, Malatya, Denizli en Isparta, onder het bestuur van de regering van de TBMM.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Verovering van de burcht Zvornik (İzvornik)", "657c465a"], "d": ["De burcht Zvornik (İzvornik) aan de Drina werd in 1460 door de Osmanen veroverd. Volgens het TDV-lemma werd hij wegens zijn gunstige administratieve en militaire ligging eerst kaza-centrum, in 1480 centrum van de sandjak met dezelfde naam en in 1491 met stenen muren versterkt en veranderde met zes moskeeën, acht tekkes en badhuizen in een belangrijk administratief-commercieel centrum.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Dood van Qasim Khan, troonsbestijging van Daniyal Khan (Khanaat Qasim)", "522fd0fd"], "d": ["Met de dood van Qasim Khan, de stichter van het khanaat, in 873/1468 volgde zijn zoon Daniyal hem op; Daniyal regeerde tot 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Zeeslag bij Diu — Portugese suprematie in de Indische Oceaan", "1778d347"], "d": ["De door de Mamelukken gesteunde vloot van Malik Ayaz, die de regio namens het Sultanaat Gujarat bestuurde, leed voor Diu een zware nederlaag tegenover de vloot van de Portugese gouverneur-generaal Francisco de Almeida, die probeerde aan deze kusten een bevoorradingsbasis te vestigen. Deze nederlaag gaf Portugal blijvende zeesuprematie in de Indische Oceaan en brak de Mamelukse-Gujarati zeemacht; zij wordt beschouwd als het begin van de machtsonevenwichtigheid die de achtergrond vormt van de Rode Zee-Indische Oceaan-strijd (verdediging van Jeddah, belegering van Diu in 1538) die de Osmanen na 1517 overnamen.", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Opstand van Kalender Shah", "f60f6ca4"], "d": ["Door de financiële nood in Anatolië, de ontevredenheid over de nieuwe administratieve regelingen en de invloed van de Safawidische propaganda verzamelden grote Turkmeense stammen zoals de Çiçekli, Akça Koyunlu, Masadlı en Bozoklu en de groepen die waren overgebleven van de eerdere opstand van Baba Zünnûn zich rond Kalender Shah en bereikten een macht van ongeveer dertigduizend man. De opstandelingen versloegen eerst de beylerbey van Rum; toen grootvizier Makbul İbrâhim Pasja soldaten bijeenbracht en hun rechten beloofde, smolt de steun voor Kalender weg en werd de opstand bij Elbistan neergeslagen; Kalender Shah en Veli Dündar werden in juni 1527 gedood.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Verovering van Şehrizor — inname van de burcht Zalm", "4320d9b8"], "d": ["Tijdens de Nachitsjevan-veldtocht van Süleyman was de beylerbey van Bagdad, Osman Pasja, belast met het innemen van de regio Şehrizor; Baltacı Mehmed Pasja, die na zijn dood beylerbey van Bagdad werd, belegerde de centrale burcht van de regio, Zalm, en nam hem op 22 augustus 1554 (23 Ramadan 961) in. Zo kwam het bekken Şehrizor aan de westelijke helling van de Zagros onder Osmaans bestuur en werd de verbinding tussen Bagdad en Koerdistan verzekerd; de regio werd eerst een sandjak en aan Murad Bey gegeven. In 1563 bouwde beylerbey Muzaffer Pasja de burcht Gülanber als nieuw provinciecentrum; de burcht zou in 1623 op bevel van Sjah Abbas worden verwoest en in 1638 onder Hüsrev Pasja opnieuw worden gebouwd.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Bekering van de heerser van het Khanaat Qasim tot het christendom en zijn verwijdering uit het khanaat", "a1a8eeb9"], "d": ["De heerser aan het hoofd van het khanaat nam de naam 'Semen (Simeon)' aan en werd christen; de Russen namen hem uit het khanaat weg rekening houdend met de reactie van de moslimse onderdanen. Deze persoon werd kort daarna door Ivan de Verschrikkelijke in Moskou uitgeroepen tot nominale heerser met de titel 'grootvorst van de tsaar en van Rusland' (1575) — het meest opvallende snijpunt tussen het Khanaat Qasim en de Moskouse troon.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Aansluiting van de sandjak Fezzan bij Tripolitanië — Murzuk en het karavaankruispunt van de Sahara", "2e6554a4"], "d": ["Als gevolg van de druk van het beylerbeylik van Tripolitanië aanvaardde Fezzan, het karavaankruispunt van de Sahara, met Murzuk als centrum de Osmaanse onderwerping. Volgens het TDV-lemma Fizan werd de dynastie Awlad Muhammad die de regio bestuurde onder voorwaarde van betaling van regelmatige belasting vrij gelaten in haar binnenlandse zaken; Fezzan werd georganiseerd als sandjak die was gebonden aan de in 1551 ingenomen provincie Tripoli. Zo kwam de handel in slaven, goud en kamelen op de lijn Tripoli–Murzuk–Bornu onder Osmaanse controle. Dit indirecte bestuur zou in 1711 in handen van de Karamanlis komen en in 1842 in handen van de rechtstreekse kaza-organisatie.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Nachitsjevan en Ordubad kwamen onder Osmaans bestuur", "24d939b3"], "d": ["Na de inname van Revan in 1583 en de verheffing ervan tot beylerbeylik-centrum, bonden de strijdkrachten die langs de Arasvallei naar het zuidoosten afdaalden Nachitsjevan en Ordubad aan het Osmaanse bestuur; de twee steden werden sandjaks van de nieuw gestichte provincie Revan. Volgens het TDV-lemma Nahcıvan werd in de stad voor het eerst blijvend Osmaans bestuur gevestigd tijdens deze oorlog — in de Nachitsjevan-veldtocht van 1553 was de stad ingenomen maar slechts geplunderd en verlaten. Zo werd de legerroute tussen Revan en Tabriz geopend en kon in september van hetzelfde jaar Tabriz worden binnengetrokken. Sjah Abbas zou Nachitsjevan in 1603 terugnemen.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Opstand van Deli Hasan Pasja en bedaring door het beylerbeylik van Bosnië", "144f3f2d"], "d": ["Deli Hasan, die na de dood van de Celali-leider Karayazıcı Abdülhalim in 1602 aan het hoofd van de beweging kwam, viel gebruik makend van de bewegingsvrijheid die de voortdurende oorlogen met Oostenrijk aan de Celali-groepen gaven Kütahya binnen en trok op naar Afyonkarahisar. In deze periode waarin de staat tegelijk met de Oostenrijkse en Iraanse fronten bezig was, werd de kwestie 'met zoetheid' opgelost: door Deli Hasan de rang van pasja en het beylerbeylik van Bosnië te geven, werd de opstandsbeweging in 1603 officieel beëindigd.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Inname van de stad Qasim door Russische strijdkrachten, Uraz Muhammad Khan", "b3f0bd34"], "d": ["Als weerspiegeling van de Tijd van Troebelen (Smoeta) in Rusland belegerden en namen Russische strijdkrachten de stad Qasim in en joegen het grootste deel van haar bevolking over de kling. Uraz Muhammad, aan het hoofd van het khanaat, was doelwit omdat hij Valse Dmitri II steunde; het jaar daarop (1610) werd hijzelf bij een samenzwering gedood.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Verlies van de burcht Azak aan de Donkozakken", "ba068b2f"], "d": ["De Donkozakken namen de burcht Azak, die zij op 21 april 1637 hadden belegerd, twee maanden later in; de burcht, die de noordoostelijke poort van de Zwarte Zee en het slot van de Donhandel was, ging voor het eerst uit Osmaanse handen. Volgens het TDV-lemma Azak namen de Kozakken de burcht in 1637, hielden stand tegen het grote beleg van drie maanden onder Deli Hüseyin Pasja in 1641 en ontruimden de burcht pas in 1642 met de komst van de Krim-khan Mehmed Giray. De staat was toen bezig met het front van Bagdad; dat de burcht vijf jaar niet kon worden gehouden, is de eerste barst in de kwaliteit van de Zwarte Zee als 'Osmaans meer'.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Herovering van Lemnos en Samothrake", "c445553b"], "d": ["Na de bevrijding van Tenedos op 31 augustus 1657 stuurde Köprülü Mehmed Pasja de vloot naar het noorden en nam Lemnos en Samothrake, die Venetië zestien maanden in handen had, terug. Volgens het TDV-lemma Limni was het eiland in juli 1656 in handen van Venetië gekomen en in november 1657 teruggenomen. Zo werd de Venetiaanse blokkade aan de monding van de Dardanellen volledig doorbroken en de graanroute van Constantinopel opnieuw veiliggesteld; dit is de meest concrete winst van het eerste jaar waarin de grootvizier met buitengewone bevoegdheden aantrad.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Verlies van Knin aan Venetië — de 166 jaar oude Dalmatische grensburcht viel", "252406b7"], "d": ["In de oorlog die na de nederlaag bij Wenen in 1683 aan meerdere fronten werd geopend, rukten de Venetiaanse strijdkrachten op naar het binnenland van Dalmatië. Knin, dat werd belegerd door de generaal van Dalmatië, Girolamo Cornaro, werd na een beleg van twaalf dagen overgegeven door beylerbey Mehmed Pasja. Knin was de sleutelburcht van de Dalmatische grenslijn die Gazi Hüsrev Bey in 1522 had veroverd en 166 jaar in Osmaanse handen was gebleven; het verlies opende de regio grotendeels voor Venetië.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Herovering van Basra op Iraanse bezetting", "5b10c5c1"], "d": ["Basra, dat Sâdık Han, de broer van Karim Khan Zand, in 1776 had ingenomen, werd ontruimd toen na de dood van Karim Khan op 2 maart 1779 in Iran een troonstrijd begon; Sâdık Han keerde met een aanspraak op het sultanaat terug naar Iran. De stad bleef enige tijd in handen van de stam Muntafiq en kwam daarna weer onder Osmaans bestuur. De voormalige mütesellim Süleyman Ağa, die uit Shiraz terugkeerde, vroeg om het gouverneurschap van Basra en werd onder de naam Büyük Süleyman Pasja gouverneur van Basra, Bagdad en Şehrizor. De handel in de Golf keerde terug onder Osmaanse controle; in de jaren van de bezetting was een deel van de handel naar Koeweit verschoven en werd vanaf 1778 ook de woestijnpost uit Koeweit verzonden.", "2f14ff54"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — beëindiging van het traditionele kapu-stelsel op Hawaï", "0b10e1d8"], "d": ["Zes maanden na de dood van Kamehameha I overtrad de nieuwe koning Liholiho met steun van zijn moeder Kaʻahumanu opzettelijk het verbod op gescheiden eten voor mannen en vrouwen (ʻaikapu). Deze handeling, die 'ʻAi Noa' (vrij eten) wordt genoemd, maakte formeel een einde aan het traditionele religieus-juridische kapu-stelsel; de oude tempels (heiau) op de eilanden werden snel verwoest. Het is de grootste religieus-politieke breuk vóór de komst van de westerse missionarissen (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protocol van Londen — erkenning van de onafhankelijkheid van Griekenland", "4c7b4b72"], "d": ["Het protocol dat Engeland, Frankrijk en Rusland in Londen ondertekenden, ging verder dan de met het Verdrag van Edirne voorziene autonomie en erkende Griekenland als ONAFHANKELIJKE staat. Bepalingen: het schiereiland Morea, Attica en Euboea en de Cycladen werden aan de nieuwe staat gelaten; de grens werd getrokken op de lijn Arta–Volos; er werd besloten tot betaling van een vergoeding aan de Osmaanse staat; de regeringsvorm van de staat werd bepaald als 'onafhankelijke monarchie'. Dit is de EERSTE onafhankelijke staat die zich van het rijk losmaakte en vormde het juridische voorbeeld voor de latere Balkanse onafhankelijkheden. Bij Griekenland, waarvan de onafhankelijkheid met het Protocol van Londen werd erkend, hoorden ook de Cycladeneilanden (Naxos, Tinos, Santorini, Paros, Antiparos, Syros, Mykonos enz.).", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Rashid nam het emiraat Ha'il in — stichting van de Shammar (Rashidi)-dynastie", "fb513b8a"], "d": ["Toen Dir'iyya in 1818 viel door de strijdkrachten van Mehmed Ali Pasja, kwam de regio Jabal Shammar uit de Saoedische heerschappij en bleef het emiraat in handen van de familie Ibn Ali. Abdullah b. Rashid, die het herstel van de Osmaanse heerschappij steunde, won in 1835 samen met zijn broer Ubayd de strijd die hij tegen de familie Ibn Ali voerde, nam het emiraat Ha'il in en vestigde de heerschappij van de Rashidi-dynastie.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Eerste geschreven grondwet van Hawaï afgekondigd", "401a8a1d"], "d": ["De eerste volledige geschreven grondwet van het koninkrijk werd afgekondigd; dit document, dat de macht van de koning beperkte en een representatieve vergadering vestigde, maakte van Hawaï een constitutionele monarchie.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Bajonetgrondwet — de bevoegdheden van koning Kalākaua ingeperkt", "4953363b"], "d": ["Een gewapende militiegroep dwong koning Kalākaua onder bedreiging een nieuwe grondwet te ondertekenen die de bevoegdheden van het koninkrijk grotendeels beknotte; het document wordt de 'Bajonetgrondwet' (Bayonet Constitution) genoemd en bracht de troon feitelijk onder controle van de blanke kolonistenelite.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Dood van George Tupou I, troonsbestijging van George Tupou II (Tonga)", "b56e2b32"], "d": ["Na de dood van stichter-koning George Tupou I besteeg zijn achterkleinzoon George Tupou II de troon; de kroningsceremonie vond plaats op 17 maart 1893 in Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Nieuw-Zeeland werd het eerste zelfbesturende land dat vrouwen kiesrecht verleende", "0d277cde"], "d": ["Met de nieuwe Kieswet die door gouverneur Lord Glasgow werd ondertekend, werd Nieuw-Zeeland het eerste zelfbesturende land ter wereld dat vrouwen stemrecht bij parlementsverkiezingen verleende.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Republiek Hawaï uitgeroepen", "4346bd5d"], "d": ["De samenzweerders die in 1893 koningin Liliuokalani afzetten, veranderden de voorlopige regering in een formele republiek; Sanford Dole werd tot president uitgeroepen. Dit tussenregime duurde tot de Amerikaanse annexatie in 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["De grenzen van Nieuw-Zeeland werden uitgebreid met de Cookeilanden en Niue", "d0370a33"], "d": ["De grenzen van Nieuw-Zeeland werden uitgebreid met de Cookeilanden (Rarotonga, Aitutaki en de zuidelijke eilanden en de noordelijke Cookeilanden) en Niue; deze eilanden werden een gebied dat aan Nieuw-Zeeland was gebonden.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Dood van George Tupou II, troonsbestijging van Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II stierf aan tuberculose; zijn achttienjarige dochter Sālote werd de volgende dag tot koningin uitgeroepen, de kroningsceremonie vond plaats op 11 oktober 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Verdrag van Sèvres — verdelingstekst van het rijk", "64980d7b"], "d": ["De tekst die de Osmaanse regering met de Entente-mogendheden ondertekende en die het rijk feitelijk liquideerde. Bepalingen: Oost-Thracië en het gebied Smyrna aan Griekenland; in Oost-Anatolië werden een onafhankelijk Armenië en een autonoom Koerdistan voorzien; Syrië werd als mandaat aan Frankrijk, Irak en Palestina aan Engeland gelaten; de Zeestraten werden overgedragen aan een internationale commissie; het leger werd teruggebracht tot 50.700 man, de capitulaties keerden terug en de financiën kwamen onder Entente-controle. De Grote Nationale Vergadering in Ankara erkende het verdrag NOOIT en verklaarde de ondertekenaars tot vaderlandsverraders; de tekst trad niet in werking en werd in 1923 vervangen door Lausanne. Dat is de reden dat er op de kaart geen weergave van is — Sèvres werd juridisch nooit uitgevoerd.", "c9b2648b"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Inname van Köprühisar en voorbereiding op de stichting van Yenişehir", "39abff03"], "d": ["Door de passenvestingen tussen Bursa en İznik te laten vallen, werd de basis gelegd voor het voorste hoofdkwartier dat beide steden in een omsingeling zou nemen.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Stichting van Yenişehir", "d3275837"], "d": ["Om de belegeringen van Bursa en İznik te leiden werd de eerste reguliere Osmaanse garnizoensnederzetting gesticht; Orhan Gazi werd hier geboren.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Eerste beleg van İznik en verovering van Marmaracık", "cdca2349"], "d": ["İznik werd voor het eerst belegerd maar kon niet worden ingenomen (definitieve verovering 1331); de nabijgelegen burcht Marmaracık werd in die tijd ingenomen.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Veldtocht van de Catalaanse troepen in Anatolië", "4fd940d5"], "d": ["De Catalaanse compagnie, door Byzantium ingehuurd om de Turkse opmars te stoppen, behaalde tijdelijke successen maar bleef niet; met hun terugtrekking versnelde de opmars van de grensbeyliks.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal wordt moslim en sluit zich aan bij de Osmanen", "ca0d86e1"], "d": ["De tekfur van Harmankaya, Köse Mihal, werd met zijn burcht en manschappen moslim en sloot zich aan bij Osman Gazi; hij werd de eerste Byzantijnse Osmaanse commandant.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey neemt het feitelijke bestuur over", "6dadbefc"], "d": ["Vanwege de ouderdom en ziekte van Osman Gazi ging de feitelijke leiding en het bevel over het beleg van Bursa en de veldtochten over op zijn zoon Orhan Bey (de formele troonsbestijging is in 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Inname van Mudanya", "0a623368"], "d": ["Met de inname van Mudanya, de haven van Bursa, werd de zeeverbinding van de stad afgesneden; het beleg van Bursa ging de fase van wurging in.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Verovering van Akyazı en het eiland İmralı", "d041b0c8"], "d": ["Akyazı ten noorden van de Sakarya werd ingenomen; met de inname van het eiland İmralı kwamen de Osmanen voor het eerst in de buurt van het eiland Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Verovering van Gemlik (Kios) en Armutlu", "682d3bac"], "d": ["Ook de laatste zeeverbinding van Bursa werd afgesneden en de stad werd rijp gemaakt voor de overgave in 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca veroverde Kandıra en omgeving", "341bb97e"], "d": ["Akça Koca, een van de grensbeys van Orhan Gazi, nam rond 1326 Kandıra en omgeving in terwijl hij vanuit zijn hoofdkwartier ten westen van het Sapanca-meer strooptochten naar de streek van İzmit ondernam. İzmit was nog in Byzantijnse handen; de stad zou pas in 1337 vallen.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Aansluiting van Yalova en Karamürsel", "133cb07a"], "d": ["Yalova en omgeving aan de zuidkust van de baai van İzmit kwamen dit jaar in Turkse handen; de kuststrook werd door Orhan Bey als timar aan Karamürsel Gazi gegeven.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca nam Aydos en de vesting Samandıra in", "ce4daa8a"], "d": ["Na de inname van Kandıra nam Akça Koca samen met Konuralp en Gazi Abdurrahman de burcht Aydos bij Kartal en daarna de vesting Samandıra ten noorden daarvan in; het gebied Samandıra werd hem als eigendom gegeven. Akça Koca stierf in 1328 bij Kandıra; het grensbeylik werd aan prins Murad gegeven.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Osmaans-Aydın-Saruhan-bondgenootschap", "9df6bb74"], "d": ["De drie beyliks traden gezamenlijk op tegen Byzantium; de vloot van Umur Bey van de Aydınoğulları sleet Byzantium op een tweede front af met overvallen op de kust van Thracië.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Huwelijk van Orhan Gazi en Theodora: Byzantijns bondgenootschap", "9b67a590"], "d": ["Orhan Gazi, die in de Byzantijnse troonstrijd Kantakouzenos steunde, trouwde met diens dochter Theodora; dit bondgenootschap stelde de Osmaanse strijdkrachten in staat Rumelië van dichtbij te leren kennen.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Inname van Ankara", "49bf1f6d"], "d": ["Ankara, onder bestuur van de ahi's, kwam onder Osmaans bestuur; de weg naar Midden-Anatolië werd geopend. Andere plaatsen die op dezelfde datum werden toegevoegd: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Opmars in Thracië onder Süleyman Pasja: Malkara, İpsala en Tekirdağ", "fb31cf02"], "d": ["Nadat het bruggenhoofd bij Gallipoli was gevestigd, trok Süleyman Pasja vanaf het schiereiland naar het noorden en veroverde stap voor stap de vlakte tussen de kust van de Zee van Marmara en de monding van de Maritsa. Malkara, İpsala en Rodosçuk (Tekirdağ) vormden zo een ononderbroken corridor die Gallipoli met de Maritsavallei verbond. Zonder deze corridor kon men niet op Edirne oprukken; de opmars, die tot stilstand kwam door de plotselinge dood van de prins in 1357, zou door Lala Şahin en Hacı İlbey worden voortgezet.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Ontvoering van prins Halil", "b52ac3d7"], "d": ["Halil, de jongere zoon van Orhan Gazi, werd door piraten uit Foça ontvoerd; de losgeldcrisis hield de Osmaans-Byzantijnse betrekkingen jarenlang bezig.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Afsnijden van de hulproutes van Edirne: de burchten Çorlu, Lüleburgaz, Babaeski en Keşan", "8e8ad485"], "d": ["Prins Murad, die na de bevrijding van Halil de veroveringscampagne hervatte, stuurde ruiters tot voor Constantinopel om Edirne af te snijden van hulp van buiten. De burchten Çorlu, Lüleburgaz en Babaeski aan de weg Constantinopel–Edirne en Keşan aan het wegkruispunt van Zuid-Thracië werden ingenomen. De overgave van Edirne kwam nadat deze belegeringsring was voltooid.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Inname van Dimetoka — opening van de Maritsavallei", "b59aee83"], "d": ["Dimetoka (Didymoteicho), de sleutelburcht van de Maritsavallei, werd ingenomen; zo werd de weg naar de verovering van Edirne geopend. Zonder de voltooiing van de corridor die zich van Gallipoli naar het noorden uitstrekt was het niet mogelijk op Edirne op te rukken, daarom komt de burcht in de volgorde van de Rumeliaanse veroveringen vóór Edirne. De stad werd een tijd lang het Rumeliaanse hoofdkwartier van de sultans. De strijdkrachten die Dimetoka innamen, brachten daarna samen met kleine burchten zoals Kuleli Burgaz (Pythion) het hele gebied van de Midden-Maritsa onder controle.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Verlies van Gallipoli (Savoyaardse kruistocht)", "00e7e415"], "d": ["De vloot van Amadeus van Savoye, neef van de Byzantijnse keizer, nam Gallipoli in en droeg het over aan Byzantium; het Osmaanse bruggenhoofd in Rumelië werd tien jaar lang vanaf de overkant van de zeestraat bestuurd. Andere plaatsen die op dezelfde datum verloren gingen: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Slag bij Çirmen — controle over de Maritsavallei", "cd738d8d"], "d": ["Het leger van de Servische beys werd bij een nachtelijke overval uiteengeslagen; de Servische/Bulgaarse lokale beys in Macedonië en de Rodopen begonnen een voor een schatting aan de Osmanen te betalen — geen directe verovering, maar het begin van een golf van vazalisering. In de Osmaanse overlevering wordt deze slag bovendien verteld onder de naam 'Sırpsındığı' en in het jaar 1364, als de nachtelijke overval van Hacı İlbey op het kruisvaardersleger dat kwam om Edirne terug te nemen; de TDV vermeldt dat die datum onjuist is en dat de twee verhalen op dezelfde slag betrekking hebben.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Verovering van Filibe en Eski Zağra", "e780c9ae"], "d": ["Filibe (Plovdiv) hoger in de Maritsavallei en Eski Zağra (Stara Zagora) ten noorden ervan werden ingenomen; het Bulgaarse tsarenrijk werd schatplichtig gemaakt. De route Tatarpazarcığı–İhtiman tussen Filibe en Sofia bleef in handen van de lokale beys die na Çirmen vazallen waren geworden.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Vazal Byzantium: Johannes V in het leger van Murad I (gevolg van de overwinning bij Çirmen in 1371)", "13ffe568"], "d": ["Volgens de TDV had het Byzantijnse Rijk na de overwinning bij Çirmen (Maritsa) op 26 september 1371 de Osmaanse heerschappij erkend en was het in de positie van vazalstaat gekomen door schatting te betalen en dienst in het Osmaanse leger te aanvaarden. Keizer Johannes V sloot zich met deze verplichting in 1373 aan bij het leger van Murad I; zijn zoon Andronikos IV, die hij toen in Constantinopel had achtergelaten, kwam samen met prins Savcı Bey in Bursa in opstand tegen hun vaders.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Herovering van Gallipoli", "5f96c0a5"], "d": ["Andronikos IV, die in de Byzantijnse troonstrijd Osmaanse steun kreeg, gaf als tegenprestatie Gallipoli terug; de brug tussen Rumelië en Anatolië was opnieuw gevestigd. Andere plaatsen die op dezelfde datum werden toegevoegd: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Germiyan-bruidsschat: aansluiting van Kütahya", "d6a6fe61"], "d": ["Bij het huwelijk van Devletşah Hatun, de dochter van Germiyanoğlu Süleyman Şah, met Yıldırım Bayezid gingen Kütahya, Simav, Tavşanlı en Eğrigöz als bruidsschat naar de Osmanen — het klassieke voorbeeld van expansie zonder oorlog. Andere plaatsen die op dezelfde datum werden toegevoegd: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Aankoop van het gebied Hamid: aansluiting van Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey verkocht een deel van zijn beylik (Akşehir-Beyşehir-Isparta) tegen contante betaling aan Murad I; de rest van het gebied Hamid zou in 1391 door Yıldırım worden geannexeerd.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Verovering van Serres", "d4d28b60"], "d": ["Serres, de sleutel van Oost-Macedonië, werd ingenomen; Thessaloniki kwam binnen de belegeringsring. De lijn Köstendil–Petriç–Nevrokop–Drama tussen Sofia en Serres was op deze datum nog niet rechtstreeks toegevoegd; zij werd in de jaren 1370–1383 vazal en na 1383 rechtstreeks bestuurd.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Verovering van Sofia", "96d5f01f"], "d": ["De westelijke passen van het Balkangebergte kwamen onder controle; omdat Serres op deze datum al sinds 1383 in handen was, vormden de gebieden Thracië en Macedonië een ononderbroken geheel.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Verovering van Niš", "77f5d632"], "d": ["Met de inname van Niš, het slot van de Moravavallei, kwam het Servische despotaat direct onder dreiging.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Eerste overgave van Thessaloniki", "96010ee9"], "d": ["Na een lange blokkade gaf de stad zich over (zij zou in 1403 aan Byzantium worden teruggegeven en in 1430 definitief worden veroverd). Andere plaatsen die op dezelfde datum werden toegevoegd: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Osmaans-Genuees ahidname — vernieuwing van het verdrag van 1352", "be11d17a"], "d": ["Met de Genuese gezanten uit Pera werd het handelsverdrag van 1352 uit de tijd van Orhan Gazi vernieuwd; de belastingen tussen beide staten, de behandeling van krijgsgevangenen en de vrije handel werden opnieuw vastgelegd. Dit wordt beschouwd als de eerste officieel bekende ahidname van vriendschap en handel tussen de Osmanen en de Genuezen — geen militair bondgenootschap, maar een zuiver commerciële overeenkomst.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Veldtocht van Çandarlı Ali Pasja in Bulgarije: inname van Şumnu en Rusçuk", "2781c3a9"], "d": ["De burchten van het Bulgaarse tsarenrijk langs de Donau werden in één veldtocht overgenomen; niet te verwarren met de nederlaag die in hetzelfde jaar bij Bileća in Bosnië werd geleden — dit was een gelijktijdig succes aan een apart front. Tırnova en Vidin waren de laatste Bulgaarse centra die nog in handen werden gehouden.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Nederlaag bij Bileća", "89ba0a64"], "d": ["De ruitermacht die naar Bosnië optrok, werd bij Bileća in een hinderlaag gelokt en vernietigd; deze eerste grote tegenslag op de Balkan moedigde het bondgenootschap aan dat naar Kosovo leidde.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annexatie van de West-Anatolische beyliks: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Drie beyliks werden in één keer toegevoegd: Manisa, centrum van de Saruhanoğulları; Aydın, centrum van de Aydınoğulları (inclusief de Bovenburcht van Smyrna, maar de haven/benedenburcht bleef tot 1402 bij de Sint-Jansridders); Muğla-Milas, centrum van de Menteşeoğulları, inclusief de kuststrook Datça-Bodrum-Marmaris-Fethiye. De Egeïsche kusten werden voor het eerst in één hand verenigd. Andere plaatsen die op dezelfde datum werden toegevoegd: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annexatie van het gebied Teke: aansluiting van Antalya", "fdbeee5c"], "d": ["Het gebied Teke aan de Middellandse Zeekust werd bij het Osmaanse grondgebied gevoegd. De Tekeoğulları zijn een afsplitsing van de Hamîdoğulları: Feleküddin Dündar Bey liet het door hem veroverde Antalya aan zijn broer Yûnus Bey, waarna omstreeks 1321 een afzonderlijk beylik ontstond. Daarom worden Antalya en omgeving na 1321 op de kaart niet in de kleur van de Hamîdoğulları maar in die van de Tekeoğulları weergegeven. Het beylik werd na de Slag bij Ankara opnieuw gesticht en pas in 1423 definitief geliquideerd.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Verovering van Üsküp (Skopje)", "9e5a1af5"], "d": ["Het centrum van Vardar-Macedonië werd ingenomen; Üsküp werd een van de voornaamste grenscentra van Rumelië.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annexatie van Kastamonu", "876330ba"], "d": ["De Kastamonu-tak van de Candaroğulları werd geliquideerd; de Sinop-tak bleef als vazal voortbestaan. Andere plaatsen die op dezelfde datum werden toegevoegd: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Val van Tırnova — annexatie van Bulgarije", "ff666977"], "d": ["De hoofdstad van het Bulgaarse tsarenrijk viel; Bulgarije kwam rechtstreeks onder Osmaans bestuur. Andere plaatsen die op dezelfde datum werden toegevoegd: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Burcht Lofça (Loveč) kwam in Osmaanse handen", "a55e87a0"], "d": ["Lofça, een van de burchten van de Bulgaarse tsaar Ivan Šišman, werd tijdens de veldtocht van 1393, waarin Tırnova viel, samen met de overige provincies van Šišman bij het Osmaanse grondgebied gevoegd. De bron is niet stellig: 'er wordt aangenomen' dat de verovering dit jaar plaatsvond.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Aansluiting van Dobroedzja", "478e36f2"], "d": ["De gebieden van Dobroedzja die zich uitstrekken tot de Donaudelta werden toegevoegd. Andere plaatsen die op dezelfde datum werden toegevoegd: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Afdaling naar Thessalië", "8bec60dd"], "d": ["De vlakte van Thessalië met als centrum Yenişehir (Larissa) werd onder Osmaans bestuur gebracht. Andere plaatsen die op dezelfde datum werden toegevoegd: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Strak beleg van Constantinopel begon (blokkade sinds ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid hield Constantinopel met tussenpozen tien jaar lang geblokkeerd; de stad werd pas gered doordat Timur naderde.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Slag bij Rovine — veldtocht naar Walachije", "343ae7a9"], "d": ["Na de bloedige slag met de Walachijse woiwode Mircea, waarvan de uitkomst omstreden is, aanvaardde Walachije schatting te betalen aan de Osmanen; de vazalorde ten noorden van de Donau werd gevestigd.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Verovering van Nikopol", "b9791717"], "d": ["Na de slag bij Rovine in 1395 tegen de Walachen nam Yıldırım Bayezid de burcht Nikopol aan de Donau in; sommige anonieme Bulgaarse kronieken geven aan dat de verovering op 3 juni 1395 plaatsvond. De veroveringsdatum is in de bronnen niet eenduidig: het lemma Niğbolu Savaşı in de TDV İslâm Ansiklopedisi schrijft dat Bayezid Silistra en Nikopol in een Donaucampagne in 1394 innam. De burcht zou tijdens de beroemde kruistocht van 1396 worden belegerd, maar niet vallen. Andere plaatsen die op dezelfde datum werden toegevoegd: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Burcht Nikopol kwam aan de Osmanen", "327012c9"], "d": ["Na de overval bij Rovine nam Yıldırım Bayezid Nikopol in; de Bulgaarse tsaar Ivan Šišman, die daar als Osmaanse vazal woonde, werd uitgeschakeld. In de atlas staat Nikopol vanaf deze dag geschreven van het Bulgaarse tsarenrijk naar de Osmanen.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Bouw van Anadolu Hisarı", "aa259b00"], "d": ["Om de blokkade van Constantinopel te ondersteunen werd aan de Anatolische kant van de Bosporus Güzelcehisar (Anadolu Hisarı) gebouwd — de eerste blijvende stap in de controle van de zeestraat.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annexatie van Vidin", "ee1ae44b"], "d": ["Na de overwinning bij Nikopol werd ook het laatste Bulgaarse vorstendom Vidin geannexeerd.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Eerste annexatie van Karaman", "3cf07876"], "d": ["Met de overwinning bij Akçay werd het gebied van de Karamanoğulları voor het eerst bij de Osmanen gevoegd (het zou tijdens het Interregnum opnieuw worden gevestigd).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Aansluiting van de Canik-kusten: Samsun", "af9c40fa"], "d": ["In het vacuüm dat ontstond doordat Kadı Burhâneddin in handen viel van Karayülük Osman Bey van de Akkoyunlu, bracht Yıldırım Bayezid eerst het Canik-gebied aan de Zwarte Zeekust onder Osmaans bestuur. Samsun en omgeving werden zo de eerste Zwarte Zeehaven van de dynastie. De lijn Sivas–Tokat–Kayseri in het binnenland zou twee weken later worden toegevoegd met het feitelijke uiteenvallen van de staat van Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Inname van Malatya", "7cb6ae16"], "d": ["Malatya aan de Mamelukse grens werd ingenomen — een van de stappen die de spanning met Timur deden toenemen.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur nam Malatya in en liet het aan Karayülük Osman — toen Timur zich terugtrok, namen de Dulkadıroğulları het terug", "ad2ce7d8"], "d": ["Yıldırım Bayezid had Malatya, dat hij in 1399 had ingenomen, aan Dulkadıroğlu Nasreddin Mehmed overgelaten en was naar Bursa teruggekeerd. Timur, die in 1400 Anatolië binnentrok, nam eerst Sivas en Elbistan in en daarna Malatya; de stad en omgeving werden geplunderd en het bestuur werd overgelaten aan Karayülük Osman, die zich bij Timur bevond. Toen Timur de regio verliet, kwam Malatya opnieuw onder de heerschappij van de Dulkadıroğulları; de Osmaanse heerschappij eindigde zo vóór Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Süleyman Çelebi – Byzantijns verdrag: teruggave van Thessaloniki", "cc503cc2"], "d": ["Süleyman Çelebi, die tijdens het Interregnum over Rumelië heerste, liet in overeenstemming met de Byzantijnse en Latijnse staten Thessaloniki en de Zwarte Zeekust tot Mesembria aan Byzantium (TDV fetret-devri: Verdrag van Gallipoli, februari 1403) — op de kaart gaan İğneada, Rezve en Ahtapolu naar Byzantium; Thessaloniki verlaat op deze datum het Osmaanse bezit.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Zeenederlaag bij Gallipoli (Venetië)", "b71d4d68"], "d": ["De Venetiaanse vloot bracht de Osmaanse vloot voor Gallipoli een zware nederlaag toe; een gebeurtenis die de grenzen van de vroege Osmaanse zeevaart toonde.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Opstand van Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, die beweerde een zoon van Yıldırım te zijn, riep met Byzantijnse steun in Rumelië het sultanaat uit; Murad II sloeg de opstand in 1422 neer en liet zijn rivaal executeren.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Beleg van Constantinopel door Murad II", "4b9d9fba"], "d": ["Als antwoord op de Byzantijnse steun voor Düzmece Mustafa belegerde Murad II Constantinopel; het beleg werd opgeheven nadat zijn broer Küçük Mustafa in Anatolië in opstand was gebracht.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Overdracht van Thessaloniki aan Venetië", "bfa6c4a0"], "d": ["De Byzantijnse gouverneur droeg de stad onder Osmaanse druk over aan Venetië; de zeven jaar durende Osmaans-Venetiaanse strijd begon.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Heroverde annexatie van de West-Anatolische beyliks: Menteşe en Aydın", "aca30a48"], "d": ["De twee Egeïsche beyliks die tijdens het Interregnum opnieuw waren gesticht, werden onder Murad II definitief bij het Osmaanse grondgebied gevoegd. Volgens het TDV-lemma Menteşeoğulları nam Murad II het gebied Menteşe in 827 (1424) in en liet hij de twee broers aan het hoofd van het beylik gevangenzetten. Volgens het lemma Aydınoğulları liet de beylerbey van Anatolië, Hamza Bey, Cüneyd Bey, die opnieuw ongehoorzaam was geworden, grijpen en samen met zijn familie executeren (829/1425-26) en kwam het gebied Aydın aan de Osmanen. De Sint-Jansridders, die de havenburcht van Smyrna sinds 1344 in handen hielden, hadden deze in 1402 aan Timur verloren en de regio was weer onder controle van de Aydınoğulları gekomen; met deze annexatie werd ook deze bij de Osmanen gevoegd. Het gebied Teke (Antalya) is geen onderwerp van dit item: de Tekeoğulları waren in 1423 afzonderlijk geliquideerd. Germiyan zou in 1429 bij testament worden toegevoegd.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annexatie van Germiyan bij testament", "9eb86b77"], "d": ["Germiyan-bey Yakub II, die kinderloos stierf, liet zijn land bij testament aan de Osmanen na — het schoolvoorbeeld van annexatie zonder oorlog. Andere plaatsen die op dezelfde datum werden toegevoegd: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Definitieve verovering van Thessaloniki", "bc021768"], "d": ["De door Venetië bestuurde stad werd bij storm ingenomen; de tweede grote haven van Rumelië werd definitief Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Overgave van Ioannina", "ee45cb52"], "d": ["Ioannina, het centrum van Epirus, gaf zich bij verdrag over.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Eerste inname van Smederevo", "c11ca17d"], "d": ["Met een beleg van drie maanden werd de hoofdstad van het Servische despotaat ingenomen en Servië voor het eerst geannexeerd (het zou met het Verdrag van Edirne-Szeged in 1444 worden teruggegeven).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Beleg van Belgrado (mislukt)", "3e05f425"], "d": ["Het eerste grote beleg van Belgrado, dat zes maanden duurde, bracht niets op; de burcht bleef tachtig jaar lang een slot voor de Osmaanse opmars.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Nederlaag bij Zlatitsa — de 'Lange Veldtocht'", "97df1466"], "d": ["Het leger dat Hunyadi midden in de winter de Balkan binnenvoerde, trok voorbij Niš en Sofia en kwam tot Zlatitsa; de Osmaanse verdediging hield met moeite stand. Deze sfeer van nederlaag bracht de vrede van Edirne-Szeged aan de onderhandelingstafel.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Verdrag van Edirne-Szeged", "0aa4e0de"], "d": ["Tienjarige vrede: het Servische despotaat werd teruggegeven, de Donau werd als grens aanvaard. Dat het verdrag binnen enkele maanden door pauselijke aanstoken werd verbroken, leidde tot de ramp bij Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Teruggave van Smederevo en de Servische burchten aan Servië", "cda3cf9e"], "d": ["De bepaling van het Verdrag van Edirne-Szeged werd uitgevoerd: Murad II gaf op 15 augustus 1444 Smederevo met zijn vierentwintig belangrijke burchten en de overige bezette Servische gebieden terug aan Đurađ Branković (TDV semendire); ook Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) en Priština (TDV pristine) werden aan de Serviërs gelaten. Vidin was geen Servisch gebied en kwam dus niet in aanmerking voor teruggave — dit is de bron van het noordwestelijke gebiedsverlies dat op de kaart rond de overwinning bij Varna te zien is; enkele maanden later zou het verdrag met de nederlaag bij Varna toch ongeldig worden.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı voltooid — 'Boğazkesen' (Zeestraatdoorsnijder)", "480e8a76"], "d": ["Met de burcht, volgens de bronnen in buitengewoon snel tempo in vier à vijf maanden voltooid, ging de controle over de Bosporus volledig naar de Osmanen; de hulproute vanaf de Zwarte Zee naar Constantinopel werd afgesloten. Zij geldt als de feitelijke eerste stap van het beleg.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Beleg van Constantinopel begon", "8af50742"], "d": ["Het leger nam positie voor de muren; in het 54 dagen durende beleg werden reusachtige kanonnen voor het eerst systematisch tegen de muren van een hoofdstad ingezet.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Schepen over land naar de Gouden Hoorn gebracht", "4f2ba07c"], "d": ["Ongeveer 70 schepen van de vloot, die de met een ketting afgesloten Gouden Hoorn niet in kon, werden met gesmeerde sleden over de heuvels van Galata gesleept en in één nacht in de Gouden Hoorn gelaten; de verdediging werd in twee fronten gesplitst.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Verovering van Athene", "4f0f1bb2"], "d": ["Het Hertogdom Athene kwam ten einde; de Osmaanse vlag werd op de Akropolis gehesen. Andere plaatsen die op dezelfde datum werden toegevoegd: İstefe (Thebe), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annexatie van Servië (val van Smederevo)", "75fd0a62"], "d": ["Smederevo, de hoofdstad van het Servische despotaat, gaf zich over; Servië werd een Osmaanse sandjak.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Verovering van de Morea", "7d5a3c18"], "d": ["Het despotaat Morea werd geliquideerd; het schiereiland (met uitzondering van de Venetiaanse burchten) kwam onder Osmaans bestuur.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Aansluiting van Sinop", "e03c2739"], "d": ["Candaroğlu gaf Sinop zonder strijd over; de weg naar de veldtocht tegen Trebizonde lag open. Andere plaatsen die op dezelfde datum werden toegevoegd: Kastamonu, Bartın, Safranbolu. Het TDV-lemma Candaroğulları noemt ook Bolu, Eflani en Tosya onder de gebieden van het Candaroğlu-beylik die in 1461 werden geannexeerd; in de atlas staan ook deze drie plaatsen op deze dag geschreven van Candaroğlu naar de Osmanen.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Ondergang van het Koninkrijk Bosnië — Bosnische veldtocht van de Veroveraar", "5362e3f2"], "d": ["Toen de laatste Bosnische koning Stjepan Tomašević (1461-1463), vertrouwend op westerse steun, weigerde schatting te betalen, werd hij geacht geen vazalheerser meer te zijn en liquideerde het leger onder Mehmed de Veroveraar het Koninkrijk Bosnië in één veldtocht. De koning werd gevangengenomen en geëxecuteerd, het koninkrijk verdween en in de regio werd de sandjak Bosnië gesticht. De ondergang van het koninkrijk is echter niet hetzelfde als de verovering van Bosnië. Het Osmaanse bestuur was in de vlakte al vijftien jaar aanwezig — Hodidjed en de vlakte van Saray waren in 1448 ingenomen, het grensbeylik van Îsâ Bey was midden in het koninkrijk gesticht. De verovering was ook in 1463 niet klaar: Foča werd in 1465 ingenomen, Livno in 1469, het Hertogdom Herzegovina in 1483, het banaat Srebrenik in 1512, en Jajce en Banja Luka in het noorden pas in 1528 na Mohács — de Hongaren hadden na 1463 in het noorden van Bosnië een banaat gevestigd dat vijfenzestig jaar standhield. De plaats die op deze datum rechtstreeks van hand wisselde is Travnik; Jajce ging op deze datum niet naar de Osmanen maar naar Hongarije.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Definitieve annexatie van Karaman", "f1dcecaa"], "d": ["De kerngebieden van de Karamanoğulları werden definitief toegevoegd; de interne twisten duurden tot de jaren 1470 voort. Andere plaatsen die op dezelfde datum werden toegevoegd: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Verovering van Negroponte (Euboea)", "5c97daf3"], "d": ["Negroponte, de belangrijkste Venetiaanse basis in de Egeïsche Zee, viel.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annexatie van Alanya, Anamur en Silifke (İçel)", "a0b9d461"], "d": ["De kuststrook İçel die aan de Karamanoğulları toebehoorde (de gehele Middellandse Zeekust tussen Antalya en Mersin) werd toegevoegd door de zeecampagne van Gedik Ahmed Pasja; Alanya was belangrijk vanwege zijn strategische scheepswerf uit de Seltsjoekse tijd.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Annexatie van Novgorod door Moskou", "bed87170"], "d": ["Grootvorst Ivan III liet de symbolische klok van de volksvergadering (veche) in Novgorod weghalen, verving de lokale bestuurders door zijn eigen gouverneurs en bond de stad feitelijk aan Moskou; Novgorod hield op een onafhankelijke republiek te zijn. Het grondgebied van Novgorod strekte zich uit van de Oostzee tot de Witte Zee en de Oeral. In de atlas staat Novgorod vanaf deze dag geschreven van de Republiek Novgorod naar Moskou.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Verdrag van Constantinopel — Albanië en Shkodër", "b09652f7"], "d": ["De 16 jaar durende Osmaans-Venetiaanse oorlog eindigde; Shkodër en de Albanese kusten bleven Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Limni, Sisam, Bozbaba (Agios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Landing bij Otranto", "7916b89d"], "d": ["De Osmaanse strijdkrachten die op de kust van Apulië (Pulya) landden, belegerden en namen de burcht Otranto in; omdat de stad met geweld werd binnengegaan, werd een deel van de verzetsleiders geëxecuteerd en een deel gevangengenomen. De kerkelijke traditie herdenkt de doden als de 'martelaren van Otranto', ongeveer 800 personen; de TDV schrijft de overdrijving van dit aantal toe aan kerkelijke propaganda. Alleen de burcht aan de punt van het schiereiland Salento en zijn smalle omgeving werd gehouden; de overige gebieden van het Koninkrijk Napels op de lijn Taranto–Brindisi–Lecce gingen niet verloren — dit bruggenhoofd naar Italië zou een jaar duren.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Ontruiming van Otranto", "37371bb0"], "d": ["Na de dood van Mehmed de Veroveraar (3 mei 1481) ontruimde het garnizoen van Otranto, dat geen hoop op nieuwe versterkingen meer had, de burcht bij overeenkomst tegenover het beleg van de Napolitaanse kroonprins Alfonso; het enige Osmaanse bruggenhoofd in Italië ging zo een jaar later verloren.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Verovering van Modon en Koron", "38b608c4"], "d": ["Modon en Koron, de 'twee ogen' van Venetië in de Morea, werden ingenomen.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Verovering van Durrës", "1f231b98"], "d": ["Tijdens de Osmaans-Venetiaanse oorlog van 1499-1503 namen de strijdkrachten onder bevel van Mehmed Bey Durrës in, de laatste grote Albanese haven van Venetië aan de Adriatische Zee. Na Shkodër (1479) en Vlorë (1417) kwam met deze verovering de gehele Albanese kuststrook onder Osmaanse controle.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Aansluiting van Oost-Anatolië", "e0cb8f8f"], "d": ["Na Çaldıran werden Diyarbakır en omgeving toegevoegd; de Koerdische beyliks werden door toedoen van İdrîs-i Bitlisî aan de Osmanen gebonden.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Verovering van de burcht Varadin (Petrovaradin)", "abf392a5"], "d": ["Het leger dat voor de veldtocht naar Mohács uittrok, stak vanuit Belgrado over naar Hongaars grondgebied; eerst werden de buitenwijken van Varadin ingenomen en na een beleg van veertien dagen viel ook de burcht. Süleyman beval de dorpen onderweg niet in brand te steken omdat deze voortaan als Osmaans grondgebied golden.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Overgave van Boeda na Mohács — twee koningen op de Hongaarse troon", "9d3568a0"], "d": ["Nadat het Osmaanse leger na de overwinning bij Mohács naar Boeda was opgerukt, werden de sleutels van de stad op 11 september 1526 aan de sultan aangeboden; maar Süleyman hield Boeda niet en trok zijn leger terug. In het koningloze Hongarije kozen de edelen twee afzonderlijke koningen: op 10 november 1526 János Szapolyai, op 17 december 1526 de Habsburger Ferdinand I. Ferdinand nam Boeda in augustus 1527 in. De vestiging van Szapolyai in Boeda als koning onder Osmaanse bescherming zou plaatsvinden met de veldtocht van 1529 (zie het item van 1529), het rechtstreekse Osmaanse bestuur zou in 1541 worden gevestigd.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai tot Hongaars koning gekozen — de Osmanen erkenden zijn koninkrijk op voorwaarde van vazalschap", "32bc6baf"], "d": ["Een deel van de adel koos de woiwode van Transsylvanië János Szapolyai tot de Hongaarse troon die na de dood van de koning bij Mohács vacant was geworden; Szapolyai werd in Székesfehérvár gekroond. De Osmanen, die Boeda hadden verlaten, erkenden het koninkrijk van Szapolyai op voorwaarde dat het hun vazal was om het gebied als bufferzone te houden. Op de kaart staan de plaatsen die van Szapolyai afhangen vanaf deze datum als Osmaans vazalgebied.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I tot Hongaars koning uitgeroepen — West- en Noord-Hongarije naar de Habsburgse kroon", "b3910a2f"], "d": ["De Habsburgse aartshertog Ferdinand maakte, steunend op het huwelijk van zijn zuster met Lodewijk II, aanspraak op de Hongaarse troon en werd door een deel van de edelen tot koning uitgeroepen. Hongarije werd zo verdeeld tussen twee koningen; het westelijke en noordelijke deel erkende Ferdinand. De Kroatische edelen kozen hem begin 1527 afzonderlijk.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Strijd tussen de twee koningen: Esztergom onder Habsburgse bescherming, Szeged bij Szapolyai", "da92dee5"], "d": ["Esztergom, dat sinds 1526 tussen de twee koningen van hand wisselde, kwam onder Habsburgse bescherming nadat de aartsbisschop met zijn archief en schatkist naar het noorden was vertrokken. Vanaf datzelfde jaar tot 1541 bleef Szeged onder de heerschappij van Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Inwoners van Pécs kozen de kant van Szapolyai", "3fc4e7f2"], "d": ["Pécs, dat in 1528 privileges van Ferdinand had ontvangen, koos kort daarna de kant van Szapolyai; koning János verbleef in 1533 enige tijd in de stad. Met de val van Boeda in 1541 keerde de stad weer terug naar de kant van Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Verovering van Tripoli", "8c659986"], "d": ["Tripoli werd van de Johannieters ingenomen; de middelste kust van Noord-Afrika werd Osmaans. Andere plaatsen die op dezelfde datum werden toegevoegd: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Verovering van Temesvár", "e9fd4995"], "d": ["Het gebied Banat werd ingenomen en het beylerbeylik Temesvár werd gesticht.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Definitieve verovering van Tunis", "7bbd11bc"], "d": ["Tunis, onder Spaans-Hafsidische controle, kwam definitief onder Osmaans bestuur; de Noord-Afrikaanse lijn was voltooid. Andere plaatsen die op dezelfde datum werden toegevoegd: Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Verovering van Kanije", "0c7b6aa3"], "d": ["Kanije werd ingenomen in de Lange Oorlog; de verdediging van Tiryâki Hasan Pasja het jaar daarop werd legendarisch.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Veldtocht naar Uyvar begon — Fâzıl Ahmed Pasja trok vanuit Edirne tegen Oostenrijk op", "306a86db"], "d": ["Nadat Oostenrijk Transsylvanië had aangevallen en de burchten Székelyhíd en Kolozsvár had ingenomen, besloot Constantinopel tot een veldtocht tegen de Habsburgers. Grootvizier Köprülüzâde Fâzıl Ahmed Pasja vertrok op 13 april 1663 uit Edirne. In Belgrado kwam het Oostenrijkse verzoek om vrede, maar in twee gesprekken in Osijek werden de Osmaanse voorwaarden verworpen. Ook bij het overleg in Boeda werd Uyvar als doel vastgesteld.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Verovering van Uyvar", "ce289470"], "d": ["De sleutelburcht van Noord-Hongarije, Uyvar (Nové Zámky), werd ingenomen; de uitdrukking 'zo sterk als een Turk voor Uyvar' ging over in de Europese talen. Na Uyvar gaven ook Nitra en Léva zich na korte weerstand over; beide werden in de lente van 1664 door De Souches teruggenomen.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Herovering van de Morea", "9b6460f1"], "d": ["De Morea, die bij Karlowitz aan Venetië was gelaten, werd in één veldtocht teruggenomen. Andere plaatsen die op dezelfde datum werden toegevoegd: Balyabadra (Patras), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Tweede verlies van Belgrado — beleg door prins Eugenius", "6a194354"], "d": ["Na de nederlaag bij Petrovaradin en het verlies van Temesvár belegerde prins Eugenius Belgrado; toen ook het ontzettingsleger dat kwam om de stad te redden werd verslagen, gaf de burcht zich over. De stad, die na Karlowitz in 1690 was heroverd, ging zo opnieuw verloren en de Donauverdedigingslinie stortte in. Belgrado zou pas tweeëntwintig jaar later, met het Verdrag van Belgrado van 1739, kunnen worden teruggenomen. Andere plaatsen die op dezelfde datum verloren gingen: Smederevo. De atlas schrijft bovendien de streken Hisarcık (Grocka) en Yagodina (Jagodina) op deze dag aan de Habsburgers toe (gebiedsdag; een plaatsniveaudag staat niet in de bron, verklaarde benadering); Mehadia gaat met de datum 27 augustus 1717 naar de Habsburgers (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Val van Özi (Očakov)", "90a67a6c"], "d": ["Özi, de sleutelburcht ten noorden van de Zwarte Zee, viel na een bloedige bestorming in Russische handen; de bevolking van de stad werd over de kling gejaagd.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Verdrag van Boekarest — verlies van Bessarabië", "932da4d6"], "d": ["Met het verdrag dat de Russische oorlog van 1806-1812 beëindigde, werd het gebied ten oosten van de Proet (Bessarabië) aan Rusland gelaten. Andere plaatsen die op dezelfde datum verloren gingen: Akkirman, Kili, Hotin, Bender, İsmail. De atlas beschouwt bovendien Chișinău (Kişinev), Bălți, Cahul (Kahul) en Orhei binnen Bessarabië op dezelfde dag als van Moldavië (Osmaanse vazal) naar Rusland overgegaan. Ook Soroca ging op dezelfde dag naar Rusland.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Verdrag van Edirne", "b3a8fe4c"], "d": ["Aan het einde van de oorlog waarin het Russische leger Edirne binnentrok, ging de Donaudelta verloren; de autonomie/onafhankelijkheid van Griekenland werd feitelijk erkend. Andere plaatsen die op dezelfde datum verloren gingen: İbrail, Anapa, Ahıska. Hoewel het verdrag het grondgebied teruggaf, maakte het niet meteen een einde aan de bezetting: Walachije-Moldavië en Silistra bleven tot de oorlogsschadevergoeding was betaald als onderpand onder Russisch bestuur — daarom staan deze plaatsen ook na 1829 op de kaart als bezet.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Edict van autonomie voor Servië — erfelijk vorstendom en garnizoensvoorwaarde", "6a5d901d"], "d": ["Het hatt-ı hümâyun dat werd uitgevaardigd krachtens de bepaling van het Verdrag van Edirne over Servië erkende Miloš Obrenović als erfelijk vorst en maakte Servië tot een autonoom vorstendom, vrij in binnenlandse aangelegenheden en naar buiten toe aan de Osmanen gebonden. Bepalingen: het vorstendom gaat van vader op zoon over, de jaarlijkse belasting wordt als vast bedrag betaald, de Servische vergadering richt haar eigen binnenlands bestuur in, de kerk is autonoom; daartegenover bleven er Osmaanse garnizoenen in de burchten Belgrado, Smederevo, Šabac, Soko en Kladovo (Fethülislâm). Deze dubbele structuur duurde tot de terugtrekking van de garnizoenen in 1867. Op de kaart wordt de stad Belgrado op deze datum bij het autonome Servië gevoegd; de vesting Kalemegdan wordt tot 1867 als Osmaans garnizoen weergegeven.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cyprus overgelaten aan Brits bestuur", "423da3ee"], "d": ["Het bestuur over Cyprus werd in ruil voor een bondgenootschap tegen de Russische dreiging aan Engeland overgedragen; juridisch bleef het Osmaans grondgebied. Andere plaatsen die op dezelfde datum verloren gingen: Nicosia, Famagusta, Kyrenia, Limassol, Larnaca (Tuzla), Paphos, Morphou (Güzelyurt), Akrotiri, Episkopi, Dhekelia; dat wil zeggen het hele eiland.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Thessalië aan Griekenland overgelaten", "ac614d24"], "d": ["Overeenkomstig de besluiten van het Congres van Berlijn werden Thessalië en de omgeving van Arta overgedragen aan Griekenland. Andere plaatsen die op dezelfde datum verloren gingen: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Met deze overdracht gingen ook Volos, Kalambaka en Karditsa (Thessalië) naar Griekenland.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Aansluiting van Oost-Roemelië bij Bulgarije", "ee43f137"], "d": ["De autonome provincie Oost-Roemelië werd met een staatsgreep bij Bulgarije gevoegd; de Hoge Porte aanvaardde voldongen feiten. Met deze eenwording ging heel Oost-Roemelië (Stara Zagora, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) over naar het Prinsdom Bulgarije.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Slag bij Domokos", "9c6f29a5"], "d": ["In de Osmaans-Griekse oorlog van 1897 behaalde het leger bij Domokos een beslissende overwinning; door diplomatieke druk bleef de gebiedswinst beperkt.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomie voor Kreta", "2e764881"], "d": ["Hoewel de Osmaans-Griekse oorlog met een Osmaanse overwinning eindigde, kondigden Engeland, Rusland, Frankrijk en Italië op 18 december 1897 de autonomie van Kreta af; het eiland zou onder Osmaanse heerschappij een neutrale en autonome provincie worden. Na 6 november 1898 werd in Candia en Kissamos de Turkse vlag niet meer gehesen; toen prins George, zoon van de Griekse koning, op 22 december 1898 als buitengewoon commissaris zijn ambt aanvaardde, verliet Kreta feitelijk het Osmaanse bestuur (formeel in 1913). Andere plaatsen die op dezelfde datum verloren gingen: Kandiye (Kreta), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Onafhankelijkheid van Bulgarije en annexatie van Bosnië", "393feaa4"], "d": ["In de verwarring van de constitutionele periode riep Bulgarije zijn onafhankelijkheid uit en annexeerde Oostenrijk-Hongarije Bosnië-Herzegovina. Met deze proclamatie werd het hele grondgebied van het Prinsdom Bulgarije (Varna, Şumnu, Rusçuk, Burgaz, İslimye enz.) het onafhankelijke Koninkrijk Bulgarije.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Herovering van Edirne", "536e5599"], "d": ["In de Tweede Balkanoorlog stak het leger de Maritsa over en nam Edirne zonder strijd terug. Andere plaatsen die op dezelfde datum werden toegevoegd: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Overwinning bij Kut al-Amara", "98b972bc"], "d": ["De commandant van de bij Kut ingesloten Britse divisie gaf zich met 13 duizend soldaten over — een van de grootste Osmaanse overwinningen van de Eerste Wereldoorlog.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Verlies van Bagdad", "2c18a816"], "d": ["Het 383 jaar Osmaanse Bagdad ging naar het Britse leger. Andere plaatsen die op dezelfde datum verloren gingen: Kerbela.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Verlies van Jeruzalem", "94067617"], "d": ["Het 401 jaar Osmaanse Jeruzalem werd zonder verdediging overgegeven.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Verlies van Damascus", "ed177b68"], "d": ["Met de ineenstorting van het Palestijnse front werd Damascus ontruimd; het vierhonderd jaar durende Osmaanse bestuur in Syrië kwam ten einde. Andere plaatsen die op dezelfde datum verloren gingen: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Overgave van Medina", "76b505f6"], "d": ["Tweeënzeventig dagen na de wapenstilstand kwam het verzet van Fahreddin Pasja, de 'Woestijntijger', op bevel van de sultan ten einde; de laatste Osmaanse eenheid in de Hidjaz legde de wapens neer.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Bezetting van Smyrna", "e32e5e77"], "d": ["Het Griekse leger landde in Smyrna; het verzet dat met het eerste schot begon, ontstak de lont van de Nationale Strijd. Aydın werd op 27 mei 1919 bezet (afzonderlijk item).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Formele bezetting van Constantinopel", "a8e98ada"], "d": ["De Entente-troepen bezetten Constantinopel formeel en de Meclis-i Meb'ûsan werd ontbonden; de afgevaardigden trokken naar Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Verdrag van Kars", "bb32d4e0"], "d": ["Tussen de TBMM en de Kaukasische republieken werd de oostgrens getrokken zoals zij vandaag is.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Inname van het emiraat Ha'il door Saoedi-wahhabitische strijdkrachten — bestuur lag bij de familie Ibn Ali van de Abde-stam", "2d29ceb9"], "d": ["Toen de strijdkrachten van de Eerste Saoedische Staat het emiraat Ha'il innamen, lag het bestuur van de stad bij de familie Ibn Ali van de Abde-clan van de stam Shammar. Deze familie bestuurde Ha'il tot Abdullah b. Rashid in 1835 het emiraat overnam; de Rashidi-dynastie werd pas op die datum gesticht. In de atlas verscheen Ha'il tot nu toe tot 1836 als bezitloos, terwijl de bron in 1820 de emir van de stad bij naam noemt.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["De Kvarner-eilanden kwamen bij het Koninkrijk Italië van Napoleon, de Baai van Kotor onder Russisch bestuur", "c5e411c8"], "d": ["Na het Verdrag van Pressburg werden de Kvarner-eilanden — anders dan Dalmatië — niet rechtstreeks aan Frankrijk maar aan het Koninkrijk Italië van Napoleon gebonden; zij kwamen pas in 1809 bij de Illyrische Provinciën. In de Baai van Kotor kwam het Oostenrijkse bestuur ten einde en werd tussen 1806-1807 Russisch bestuur gevestigd; de Baai ging pas in 1807 naar Frankrijk. Deze twee onderscheiden kunnen niet met één enkel 'Frankrijk'-venster van de atlas worden opgevangen.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Dalmatië kwam onder Frans bestuur — uitvoering van het Verdrag van Pressburg", "00bfe4f6"], "d": ["Het Verdrag van Pressburg (Pojun) van 26 december 1805 dwong Oostenrijk om af te zien van Istrië, Dalmatië en alle Adriatische eilanden. Frankrijk nam het bestuur in februari 1806 feitelijk over; Zadar bleef centrum van de generaal-provveditore en tussen 1806 en 1810 vervulde de Venetiaan Vincenzo Dandolo deze functie. Dalmatië werd na het Verdrag van Schönbrunn van 1809 bij de Illyrische Provinciën gevoegd. Zo kwam een einde aan het eerste Oostenrijkse bestuur dat sinds 1797 bestond — in de atlas verscheen deze periode tot nu toe als ononderbroken Oostenrijks.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Oostenrijk nam de Illyrische Provinciën en Dalmatië terug — einde van het Napoleontische bestuur", "1b2ac942"], "d": ["Eind 1813 namen de Habsburgse eenheden het gebied ten zuiden van de Sava terug en werd de oude grensorganisatie hersteld; het Oostenrijkse leger trok in oktober 1813 Istrië binnen. Karlovac werd vanaf die datum deel van het Oostenrijkse Koninkrijk Illyrië. Ook de periode van het Franse bestuur in Dalmatië werd in 1813 gesloten. De Oostenrijkse toebehoren van de regio werd formeel bevestigd door de besluiten van de Vrede van Parijs in 1814 en het Congres van Wenen in 1815. Met deze campagne keerden Villach, Tarvisio, Gorizia, Gradisca en Pula (Illyrische Provinciën) eind 1813 terug naar Oostenrijk.", "bf1e49a8"]}
});
